          obtain ⟨r, hr⟩ := ih l₂ (fun x m => h₁ x (List.mem_cons_of_mem _ m))
            (fun x m => h₂ x (List.mem_cons_of_mem _ m)) (by simpa using len)
          refine ⟨d || r, fun m hm => ?_⟩
          have e₁ := hd m hm
          have e₂ := hr m hm
          dsimp only at e₁ e₂ ⊢
          unfold Elixir.Module.Types.Descr.«disjoint_arguments?/2»
          rw [e₁, e₂, orElse_bool]

