        have each := all_uni (K + 1) "Elixir.Module.Types.Descr" "-all_disjoint_arguments?/1-fun-0-" #[Term.list args]
          rest (fun q mq => by
            obtain ⟨k', args', ret', rfl, alen', hargs', -⟩ := hrest q mq
