    theorem nonempty_args_total (ops : ElemOk E K) (S : List (Term × Term)) (args : List Term) (hargs : ∀ a ∈ args, E a)
        (name : String) (lam : ∀ d a, (D (d + 1)).pure (.function "Elixir.Module.Types.Descr" name 1 #[.map S]) #[a] =
