            Elixir.Module.Types.Descr.«subtype_seen?/3», rd m' (by omega), he m' (by omega), e₂, Lynx.Except.ok_bind,
            andAlso_bool])
      refine ⟨b, fun m hm => ?_⟩
      have h := hb m hm
      dsimp only at h ⊢
      rw [Elixir.Module.Types.Descr.«fun_line_empty?/3».eq_def]
      simpa [Term.list] using h

