              refine ⟨disj_cons₁ h₁ above disj, ?_⟩
              unfold Erlang.orddict.«merge/3»
              simp [fieldsTerm, Erlang.erlang.«</2», cmp] at run ⊢
              simp [run]
          · have ab : a = b := Std.compare_eq_iff_eq.mp (by rw [← atoms_cmp]; exact cmp)
