    theorem mlit_leaf {k : Int} {a b : Term} (h : MLit E (.tuple #[.integer k, a, b])) :
        ∃ l : List (Term × Term), b = fieldsTerm l ∧ TagV E a ∧ FieldsV E l ∧ ¬(a = .atom "open" ∧ l = []) ∧
          (a = .atom "open" → 0 ≤ k) ∧ (a = .atom "closed" → k < 0) := by
