          (.tuple #[.integer k₂, t₂, fieldsTerm l₂]) S = .ok (.tuple #[.integer k₁, t₁, fieldsTerm l₁]) := by
      unfold Elixir.Module.Types.Descr.«opt_map_intersection/3»
