    theorem opt_map_inter_plain_eqG {d : Dispatcher} {x y S : Term} (tx : ∀ k, x ≠ .tuple #[k, .atom "open", .nil])
        (ty : ∀ k, y ≠ .tuple #[k, .atom "open", .nil])
