            · cases o₁
              · refine ⟨_, ?_, Or.inl ⟨rfl, a, disj_left la₁ hv₁ (by simp [ev₁, req, boolAtom]) na₂⟩⟩
                rw [Elixir.Module.Types.Descr.«opt_map_difference_strategy/5».eq_def]
