          (D m).pure (.function "Elixir.Module.Types.Descr" "-tuple_bdd_to_dnf_with_negations/1-fun-0-" 2 #[]) #[L, acc] =
            .ok (if keep L then .cons L acc else acc)) ∧ (keep L = Bool.true ↔ ∃ v, InLine den L v) := by
