    theorem dnf_map (ops : ElemOk E K) (dops : ElemDiff E K) (sem : ElemSem E K V den Safe) {m : Nat} (hm : K + 2 ≤ m)
        {S : List (Term × Term)} (hS : Safe S) {ok : Term → Prop} {r : Term} (wr : Bdd ok r) (okT : ∀ t, ok t → MapLitV E t) :
