          ∃ lines : List Term, Elixir.Module.Types.Descr.«map_bdd_to_dnf/5» (D m) (Term.list acc) pos (Term.list negs) r (.map S) =
              .ok (Term.list (lines ++ acc)) ∧ (∀ L ∈ lines, MLine E L) ∧
