        obtain ⟨tag, l, rfl, gt, el⟩ := hp
        refine ⟨[.tuple #[tag, fieldsTerm l, Term.list negs]], ?_, ?_, fun v => ?_⟩
        · rw [Elixir.Module.Types.Descr.«map_bdd_to_dnf/5».eq_def]; simp [Term.list]
