        refine ⟨[.tuple #[tag, fieldsTerm l, Term.list negs]], ?_, ?_, fun v => ?_⟩
        · rw [Elixir.Module.Types.Descr.«map_bdd_to_dnf/5».eq_def]; simp [run, Term.list]
        · intro L mL; simp at mL; subst mL; exact ⟨tag, l, negs, rfl, gt, el, lits⟩
