    theorem munion_pairs (P : List Term) (hP : ∀ p ∈ P, MPairOk E p) :
        ∃ u, MField E u ∧ (∀ w, denMF E den u w = Bool.true ↔ ∃ p ∈ P, ∃ f b, p = .tuple #[f, b] ∧ denMF E den b w = Bool.true) ∧
