        · simp [Elixir.Module.Types.Descr.«prepend_map_pair_unless_empty_diff/4»,
            rd, re, Lynx.Term.isMember, Term.list]
        · intro p mp; simp at mp; subst mp; exact ⟨d, b, rfl, hd, hb, nb⟩
        · simp [MInPairs, mpairIn_iff, sd]
