        · simp [Elixir.Module.Types.Descr.«prepend_map_pair_unless_empty_diff/4»,
            rd, re, Lynx.Term.isMember]
        · simp only [MInPairs, List.not_mem_nil, false_and, exists_false, false_iff, not_and]
          intro h₁ _
          exact se.mp rfl y ((sd y).mpr h₁)

