        intro acc p q; rw [Elixir.Module.Types.Descr.«bdd_to_dnf/4».eq_def]; rfl
      have top : ∀ acc p q, Elixir.Module.Types.Descr.«bdd_to_dnf/4» acc p q (.atom "bdd_top") =
