        obtain ⟨n₂, r₂, h₂, k₂⟩ := iu lits' (n₁ ++ (n₀ ++ es))
        obtain ⟨n₃, r₃, h₃, k₃⟩ := id lits' (n₂ ++ (n₁ ++ (n₀ ++ es)))
        refine ⟨n₃ ++ n₂ ++ n₁ ++ n₀, ?_, negNew_append (negNew_append (negNew_append h₃ h₂) h₁) h₀, ?_⟩
        · rw [Elixir.Module.Types.Descr.«bdd_reduce/3».eq_def]
