          exact Bdd.node_iff.mpr ⟨isLeaf, ⟨okl, negNamed_mono (fun e me => by simp [me]) k₀⟩,
            k₁.mono (lift n₁ (fun e me => by simp [me])), k₂.mono (lift n₂ (fun e me => by simp [me])), k₃.mono (lift n₃ (fun e me => by simp [me]))⟩

