    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    section
    variable {V : Type} {den : Term → V → Prop}

    /-- A map of values with one key set. -/
    def setW (κ : MKey) (o : Option V) (w : MW V) : MW V := fun k => if k = κ then o else w k

    /-- A literal holding a map with either of two keys set holds the map itself. -/
    theorem msem_two {tag : Term} {l : List (Term × Term)} {w : MW V} {κ₁ κ₂ : MKey} (ne : κ₁ ≠ κ₂) {o : Option V}
        (h₁ : MSem den tag l (setW κ₁ o w)) (h₂ : MSem den tag l (setW κ₂ o w)) : MSem den tag l w := by
      rw [msem_keys] at h₁ h₂ ⊢
      intro κ
      by_cases e : κ = κ₁
      · subst e; simpa [setW, ne] using h₂ κ
      · simpa [setW, e] using h₁ κ

    theorem nsem_two {N : Term} {w : MW V} {κ₁ κ₂ : MKey} (ne : κ₁ ≠ κ₂) {o : Option V}
        (h₁ : NSem den N (setW κ₁ o w)) (h₂ : NSem den N (setW κ₂ o w)) : NSem den N w := by
      obtain ⟨k, tag, l, rfl, m₁⟩ := h₁
      obtain ⟨k', tag', l', e, m₂⟩ := h₂
      obtain ⟨-, rfl, e₃⟩ := tuple3_inj e
      rw [← fieldsTerm_inj e₃] at m₂
      exact ⟨k, tag, l, rfl, msem_two ne m₁ m₂⟩

    /-- Negated literals miss a map with one of many keys set, when they miss the map. -/
    theorem survive_set {w : MW V} (o : Option V) : ∀ (Ns : List Term), (∀ N ∈ Ns, ¬NSem den N w) →
        ∀ (C : List MKey), C.Nodup → Ns.length < C.length → ∃ κ ∈ C, ∀ N ∈ Ns, ¬NSem den N (setW κ o w) := by
      intro Ns
      induction Ns with
      | nil =>
        intro _ C _ len
        cases C with
        | nil => simp at len
        | cons κ _ => exact ⟨κ, List.mem_cons_self, by simp⟩
      | cons N rest ih =>
        intro out C nd len
        have out' := fun N' (m : N' ∈ rest) => out N' (List.mem_cons_of_mem _ m)
        by_cases killed : ∃ κ₀ ∈ C, NSem den N (setW κ₀ o w)
        · obtain ⟨κ₀, mκ₀, h₀⟩ := killed
          obtain ⟨κ, mκ, hκ⟩ := ih out' (C.erase κ₀) (nd.erase κ₀) (by rw [List.length_erase_of_mem mκ₀]; simp at len; omega)
          have ne : κ ≠ κ₀ := fun e => by subst e; exact (List.Nodup.not_mem_erase nd) mκ
          refine ⟨κ, List.mem_of_mem_erase mκ, fun N' mN' => ?_⟩
          rcases List.mem_cons.mp mN' with rfl | m
          · exact fun h => out N' List.mem_cons_self (nsem_two ne h h₀)
          · exact hκ N' m
        · obtain ⟨κ, mκ, hκ⟩ := ih out' C nd (by simp at len; omega)
          refine ⟨κ, mκ, fun N' mN' => ?_⟩
          rcases List.mem_cons.mp mN' with rfl | m
          · exact fun h => killed ⟨κ, mκ, h⟩
          · exact hκ N' m

    /-- Values a literal allows at one of many keys occur at one of them in a map of a non-empty line. -/
    theorem line_witness {tag : Term} {l : List (Term × Term)} {negs : List Term} {w₀ : MW V}
        (h₀ : InMLine den (.tuple #[tag, fieldsTerm l, Term.list negs]) w₀) {x : V} (C : List MKey) (nd : C.Nodup)
        (len : negs.length < C.length) (hC : ∀ κ ∈ C, KeyAllow den tag l κ (some x)) :
        ∃ κ ∈ C, ∃ w, InMLine den (.tuple #[tag, fieldsTerm l, Term.list negs]) w ∧ w κ = some x := by
      obtain ⟨hm, hn⟩ := inMLine_iff.mp h₀
      obtain ⟨κ, mκ, out⟩ := survive_set (some x) negs hn C nd len
      refine ⟨κ, mκ, setW κ (some x) w₀, inMLine_iff.mpr ⟨msem_keys.mpr fun κ' => ?_, out⟩, by simp [setW]⟩
      by_cases e : κ' = κ
      · subst e; simpa [setW] using hC κ' mκ
      · simpa [setW, e] using msem_keys.mp hm κ'

    /-- A map of values with two atom keys swapped. -/
    def swapW (s c : String) (w : MW V) : MW V :=
      fun k => if k = .atom s then w (.atom c) else if k = .atom c then w (.atom s) else w k

    theorem swapW_swapW (s c : String) (w : MW V) : swapW s c (swapW s c w) = w := by
      funext k
      by_cases hs : k = .atom s
      · subst hs; by_cases e : s = c
        · subst e; simp [swapW]
        · simp [swapW, Ne.symm e]
      · by_cases hc : k = .atom c
        · subst hc; simp [swapW, hs]
        · simp [swapW, hs, hc]

    /-- Literals that mention neither of two atom keys hold maps with the keys swapped. -/
    theorem msem_swapW {s c : String} {tag : Term} {l : List (Term × Term)} (hs : mapLookup l (.atom s) = none)
        (hc : mapLookup l (.atom c) = none) {w : MW V} (h : MSem den tag l w) : MSem den tag l (swapW s c w) := by
      refine ⟨fun a => ?_, fun k i => by simpa [swapW] using h.doms k i⟩
      by_cases ha : a = s
      · subst ha
        have := h.atoms c
        unfold FSem at this ⊢
        rw [hc] at this; rw [hs]
        simpa [swapW] using this
      · by_cases hc' : a = c
        · subst hc'
          have := h.atoms s
          unfold FSem at this ⊢
          rw [hs] at this; rw [hc]
          simpa [swapW, ha] using this
        · simpa [swapW, ha, hc'] using h.atoms a

    theorem msem_swapW_iff {s c : String} {tag : Term} {l : List (Term × Term)} (hs : mapLookup l (.atom s) = none)
        (hc : mapLookup l (.atom c) = none) {w : MW V} : MSem den tag l (swapW s c w) ↔ MSem den tag l w :=
      ⟨fun h => by simpa [swapW_swapW] using msem_swapW hs hc h, msem_swapW hs hc⟩

    theorem fresh_str (L : List String) : ∃ c, c ∉ L := by
      obtain ⟨c, mc⟩ : ∃ c, c ∈ freshStrs ((L.map String.length).foldr max 0) 1 := ⟨_, by simp [freshStrs]; rfl⟩
      exact ⟨c, fun m => by have := le_maxLen L c m; have := freshStrs_len mc; omega⟩

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    section
    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    /-- The keys a split of keys selects: its atoms, the atoms outside its negated set, if any, and the keys of its
    domain kinds. -/
    def SplitKey (rs : List Term) (neg : Term) (ds : List Term) : MKey → Prop
      | .atom s => .atom s ∈ rs ∨ ∃ N, neg = .map N ∧ mapLookup N (.atom s) = none
      | .dom k _ => .atom (domKind k) ∈ ds

    /-- Splits of static keys: atoms, a negated set of atoms or `nil`, and domain kinds, with the atom kind exactly when
    atoms are negated. -/
    structure SplitOk (rs : List Term) (neg : Term) (ds : List Term) : Prop where
      hrs : ∀ r ∈ rs, ∃ s, r = .atom s
      hneg : neg = .atom "nil" ∨ ∃ N, neg = .map N
      hds : ∀ d ∈ ds, ∃ s ∈ domainKinds, d = .atom s
      hatom : .atom "atom" ∈ ds ↔ ∃ N, neg = .map N

    theorem domKind_of {s : String} (h : s ∈ domainKinds) (ne : s ≠ "atom") : ∃ k, domKind k = s := by
      simp only [domainKinds, List.mem_cons, List.not_mem_nil, or_false] at h
      rcases h with rfl | rfl | rfl | rfl | rfl | rfl | rfl | rfl | rfl | rfl | rfl | rfl
      · exact absurd rfl ne
      · exact ⟨0, rfl⟩
      · exact ⟨1, rfl⟩
      · exact ⟨2, rfl⟩
      · exact ⟨3, rfl⟩
      · exact ⟨4, rfl⟩
      · exact ⟨5, rfl⟩
      · exact ⟨6, rfl⟩
      · exact ⟨7, rfl⟩
      · exact ⟨8, rfl⟩
      · exact ⟨9, rfl⟩
      · exact ⟨10, rfl⟩

    theorem domKind_ne_atom (k : Fin 11) : domKind k ≠ "atom" := by
      revert k; decide

    /-- Values a tag allows at the keys of a kind are those of the type it gives them. -/
    theorem tagSem_some (ef : EF nd E V den tl K) {tag : Term} (g : TagV E tag) (kind : String) (x : V) :
        TagSem den tag kind (some x) ↔ den (tagType tag kind) x := by
      rcases g with rfl | rfl | ⟨dl, rfl, -⟩
      · simp [TagSem, tagType, ef.den_term]
      · simp [TagSem, tagType]
        exact fun h => ef.den_none x h
      · rw [tagSem_dom_iff (fun v h => ef.den_none v h), tagType_dom]
        cases mapLookup dl (.atom kind) <;> simp
        exact fun h' => ef.den_none x h'

    def atomStrs (R : List Term) : List String := R.filterMap fun r => match r with
      | .atom s => some s
      | _ => none

    theorem mem_atomStrs {R : List Term} {s : String} (h : .atom s ∈ R) : s ∈ atomStrs R :=
      List.mem_filterMap.mpr ⟨_, h, rfl⟩

    /-- The keys of the fields of a line. -/
    def lineKeys (L : Term) : List String :=
      match L with
      | .tuple ⟨[_, f, _]⟩ => keyStrs (domFields f)
      | _ => []

    theorem lineKeys_eq (tag : Term) (l : List (Term × Term)) (negs : List Term) :
        lineKeys (.tuple #[tag, fieldsTerm l, Term.list negs]) = keyStrs l := by
      simp [lineKeys, domFields_fieldsTerm]

    theorem lookup_entries_atom {es : List (Term × Term)} {s : String} {v : Term} (h : (Term.atom s, v) ∈ es) :
        .atom s ∈ (mapEntries es).map Prod.fst := by
      have hl : (mapLookup es (.atom s)).isSome := by
        rw [mapLookup]
        cases e : es.find? (fun entry => decide (compareExact (fuel (.atom s) entry.1) (.atom s) entry.1 = .eq)) with
        | none => exact absurd h (by simpa using List.find?_eq_none.mp e (.atom s, v))
        | some _ => simp
      rw [← mapLookup_mapEntries, mapLookup] at hl
      cases e : (mapEntries es).find? (fun entry => decide (compareExact (fuel (.atom s) entry.1) (.atom s) entry.1 = .eq)) with
      | none => rw [e] at hl; cases hl
      | some r =>
        have mr := List.mem_of_find?_eq_some e
        have := List.find?_some e
        simp only [decide_eq_true_eq] at this
        exact List.mem_map.mpr ⟨r, mr, (compareExact_eq_atom _ _).mp (Lynx.Term.compareExact_eq_symm this)⟩

    /-- `map_keys_from_negated_set/2` on a map type: atoms outside the negated set, beyond which the maps of the type
    hold the same values at any two atom keys outside the set. -/
    theorem neg_keys (ef : EF nd E V den tl K) (N : List (Term × Term)) (m : Nat) {b : Term} (fb : MField E b) :
        ∃ R, Elixir.Module.Types.Descr.«map_keys_from_negated_set/2» (D (m + 1)) (.map N) b = .ok (Term.list R) ∧
          (∀ r ∈ R, ∃ s, r = .atom s ∧ mapLookup N (.atom s) = none) ∧
          ∀ s c, mapLookup N (.atom s) = none → mapLookup N (.atom c) = none → .atom s ∉ R → .atom c ∉ R →
            ∀ w, denMF E den b (swapW s c w) = denMF E den b w := by
      rcases fb with ⟨k, rfl⟩ | wb
      · refine ⟨[], ?_, by simp, fun s c _ _ _ _ w => by rw [denMF_top, denMF_top]⟩
        simp [Elixir.Module.Types.Descr.«map_keys_from_negated_set/2», Elixir.Module.Types.Descr.«bdd_reduce/3»,
          Erlang.program.«Elixir.Module.Types.Descr:-map_keys_from_negated_set/2-fun-1-/2».pure,
          Elixir.Module.Types.Descr.«-map_keys_from_negated_set/2-fun-1-/3», Erlang.orddict.«fold/3»,
          Erlang.erlang.«is_function/2», Erlang.maps.«keys/1»]
      obtain ⟨new, run, hn, hk⟩ := neg_reduce N m wb []
      refine ⟨(mapEntries new).map Prod.fst, ?_, fun r mr => ?_, fun s c sN cN ns nc w => ?_⟩
      · simp [Elixir.Module.Types.Descr.«map_keys_from_negated_set/2», run, Erlang.maps.«keys/1»]
      · obtain ⟨e, me, rfl⟩ := List.mem_map.mp mr
        obtain ⟨s, rfl, hs⟩ := hn e (mem_of_mem_mapEntries me)
        exact ⟨s, rfl, hs⟩
      · rw [denMF_bdd wb, denMF_bdd wb]
        refine eval_ext hk fun t ⟨lt, nt⟩ => ?_
        obtain ⟨k, tag, l, rfl, -, -⟩ := lt.1
        have fresh : ∀ a, mapLookup N (.atom a) = none → .atom a ∉ (mapEntries new).map Prod.fst →
            mapLookup l (.atom a) = none := fun a aN na =>
          lookup_fresh' fun ma => na (lookup_entries_atom (nt k tag l rfl a ma aN))
        have lit : MapLitV E (.tuple #[.integer k, tag, fieldsTerm l]) := lt.1
        rw [Bool.eq_iff_iff, valM_iff ef.mopsE ef.mdopsE ef.semR lit, valM_iff ef.mopsE ef.mdopsE ef.semR lit, nsem_lit,
          nsem_lit, msem_swapW_iff (fresh s sN ns) (fresh c cN nc)]

    /-- Values at an atom key outside a negated set and the keys a map type names are values its lines allow at atoms
    outside their fields. -/
    theorem unnamed_tag (ef : EF nd E V den tl K) {b : Term} {N : List (Term × Term)} {R : List Term} (lines : List Term)
        (hl : ∀ L ∈ lines, MLine E L) (sl : ∀ w, denMF E den b w = Bool.true ↔ ∃ L ∈ lines, InMLine den L w)
        (swap : ∀ s c, mapLookup N (.atom s) = none → mapLookup N (.atom c) = none → .atom s ∉ R → .atom c ∉ R →
          ∀ w, denMF E den b (swapW s c w) = denMF E den b w)
        {s : String} (sN : mapLookup N (.atom s) = none) (sR : .atom s ∉ R) {w : MW V} {x : V}
        (hw : denMF E den b w = Bool.true) (hx : w (.atom s) = some x) : ∃ L ∈ lines, LineTag den L "atom" x := by
      obtain ⟨c, hc⟩ := fresh_str (s :: keyStrs N ++ atomStrs R ++ lines.flatMap lineKeys)
      simp only [List.cons_append, List.mem_cons, List.mem_append, List.mem_flatMap, not_or] at hc
      obtain ⟨cs, ⟨cN, cR⟩, cL⟩ := hc
      have cN' : mapLookup N (.atom c) = none := lookup_fresh' cN
      have cR' : .atom c ∉ R := fun m => cR (mem_atomStrs m)
      have hw' : denMF E den b (swapW s c w) = Bool.true := by rw [swap s c sN cN' sR cR']; exact hw
      obtain ⟨L, mL, hL⟩ := (sl _).mp hw'
      obtain ⟨tag, l, negs, rfl, g, -, -⟩ := hl L mL
      have hm := (inMLine_iff.mp hL).1.atoms c
      have lc : mapLookup l (.atom c) = none := lookup_fresh' fun m => cL ⟨_, mL, by rw [lineKeys_eq]; exact m⟩
      unfold FSem at hm
      rw [lc] at hm
      have sw : swapW s c w (.atom c) = some x := by
        unfold swapW; simp [show MKey.atom c ≠ MKey.atom s from fun e => cs (MKey.atom.inj e), hx]
      rw [sw] at hm
      exact ⟨_, mL, tag, l, negs, rfl, (tagSem_some ef g "atom" x).mp hm⟩

    /-- Values a line allows at the keys of a kind occur at such a key in a map of the line, outside a negated set of
    atoms for the atom kind. -/
    theorem tag_witness (ef : EF nd E V den tl K) {L : Term} (hL : MLine E L) (ne : ∃ w, InMLine den L w) {kind : String}
        (hk : kind ∈ domainKinds) {x : V} (hx : LineTag den L kind x) (N : List (Term × Term)) :
        ∃ w, InMLine den L w ∧ ∃ κ, ((kind = "atom" ∧ ∃ c, κ = .atom c ∧ mapLookup N (.atom c) = none) ∨
          ∃ k i, kind = domKind k ∧ κ = .dom k i) ∧ w κ = some x := by
      obtain ⟨tag, l, negs, rfl, g, -, -⟩ := hL
      obtain ⟨tag', l', negs', e, hx⟩ := hx
      obtain ⟨rfl, -, -⟩ := tuple3_inj e
      obtain ⟨w₀, h₀⟩ := ne
      have hs := (tagSem_some ef g kind x).mpr hx
      by_cases ka : kind = "atom"
      · subst ka
        let M := ((keyStrs l ++ keyStrs N).map String.length).foldr max 0
        have fr : ∀ c ∈ freshStrs M (negs.length + 1), c ∉ keyStrs l ++ keyStrs N := fun c mc m => by
          have := le_maxLen _ c m; have := freshStrs_len mc; omega
        obtain ⟨κ, mκ, w, hw, wκ⟩ := line_witness h₀ ((freshStrs M (negs.length + 1)).map MKey.atom)
          (List.Pairwise.map MKey.atom (fun _ _ ne e => ne (MKey.atom.inj e)) (freshStrs_nodup M _)) (by simp [freshStrs_length]) fun κ mκ => by
            obtain ⟨c, mc, rfl⟩ := List.mem_map.mp mκ
            have lc : mapLookup l (.atom c) = none := lookup_fresh' fun m => fr c mc (List.mem_append_left _ m)
            show FSem den tag l c (some x)
            unfold FSem; rw [lc]; exact hs
        obtain ⟨c, mc, rfl⟩ := List.mem_map.mp mκ
        exact ⟨w, hw, .atom c, Or.inl ⟨rfl, c, rfl, lookup_fresh' fun m => fr c mc (List.mem_append_right _ m)⟩, wκ⟩
      · obtain ⟨k, rfl⟩ := domKind_of hk ka
        obtain ⟨κ, mκ, w, hw, wκ⟩ := line_witness h₀ ((List.range (negs.length + 1)).map (MKey.dom k))
          (List.Pairwise.map (MKey.dom k) (fun _ _ ne e => ne (MKey.dom.inj e).2) List.nodup_range) (by simp) fun κ mκ => by
            obtain ⟨i, -, rfl⟩ := List.mem_map.mp mκ
            exact hs
        obtain ⟨i, -, rfl⟩ := List.mem_map.mp mκ
        exact ⟨w, hw, .dom k i, Or.inr ⟨k, i, rfl, rfl⟩, wκ⟩

    /-- `map_get_static_dnf/3` on the non-empty lines of a map type and a split of static keys unites the values its maps
    hold at the keys the split selects. -/
    theorem get_dnf (ef : EF nd E V den tl K) {n : Nat} (hn : K + 2 ≤ n) {b : Term} (fb : MField E b) (lines : List Term)
        (hl : ∀ L ∈ lines, MLine E L ∧ ∃ w, InMLine den L w)
        (sl : ∀ w, denMF E den b w = Bool.true ↔ ∃ L ∈ lines, InMLine den L w) {rs : List Term} {neg : Term}
        {ds : List Term} (hs : SplitOk rs neg ds) :
        ∃ T, Elixir.Module.Types.Descr.«map_get_static_dnf/3» (D (n + 4)) b (Term.list lines)
            (.tuple #[Term.list rs, .nil, neg, Term.list ds, .nil]) = .ok T ∧ E T ∧
          ∀ x, den T x ↔ ∃ w, denMF E den b w = Bool.true ∧ ∃ κ, SplitKey rs neg ds κ ∧ w κ = some x := by
      have hl' : ∀ L ∈ lines, MLine E L := fun L m => (hl L m).1
      obtain ⟨T₂, r₂, h₂, s₂⟩ := get_keys ef hn lines hl rs hs.hrs ef.none
      obtain ⟨T₃, r₃, h₃, s₃⟩ := get_keys ef hn lines hl [] (by simp) h₂
      obtain ⟨R, rR, hR, swR⟩ : ∃ R, Elixir.Module.Types.Descr.«map_keys_from_negated_set/2» (D (n + 4)) neg b =
          .ok (Term.list R) ∧ (∀ r ∈ R, ∃ s, r = .atom s ∧ ∃ N, neg = .map N ∧ mapLookup N (.atom s) = none) ∧
          ∀ N, neg = .map N → ∀ s c, mapLookup N (.atom s) = none → mapLookup N (.atom c) = none → .atom s ∉ R →
            .atom c ∉ R → ∀ w, denMF E den b (swapW s c w) = denMF E den b w := by
        rcases hs.hneg with rfl | ⟨N, rfl⟩
        · exact ⟨[], by simp [Elixir.Module.Types.Descr.«map_keys_from_negated_set/2»], by simp, fun N e => by cases e⟩
        · obtain ⟨R, rR, hR, swR⟩ := neg_keys ef N (n + 3) fb
          exact ⟨R, rR, fun r mr => let ⟨s, e, h⟩ := hR r mr; ⟨s, e, N, rfl, h⟩, fun N' e => by cases e; exact swR⟩
      obtain ⟨T₄, r₄, h₄, s₄⟩ := get_keys ef hn lines hl R (fun r mr => let ⟨s, e, _⟩ := hR r mr; ⟨s, e⟩) h₃
      obtain ⟨T₅, r₅, h₅, s₅⟩ := get_domains ef hn lines hl' ds (fun d md => let ⟨s, _, e⟩ := hs.hds d md; ⟨s, e⟩) h₄
      refine ⟨T₅, ?_, h₅, fun x => ?_⟩
      · have nil : Erlang.lists.«foldl/3» (D (n + 4))
            (.function "Elixir.Module.Types.Descr" "-map_get_static_dnf/3-fun-1-" 2 #[Term.list lines]) T₅ .nil = .ok T₅ := by
          simp [Erlang.lists.«foldl/3», Erlang.erlang.«is_function/2»]
        simp only [Term.list] at r₃
        simp [Elixir.Module.Types.Descr.«map_get_static_dnf/3», r₂, r₃, rR, r₄, r₅, nil]
      rw [s₅, s₄, s₃, s₂]
      constructor
      · rintro ((((h | ⟨s, ms, L, mL, w, hw, hx⟩) | ⟨s, ms, -⟩) | ⟨s, ms, L, mL, w, hw, hx⟩) | ⟨kind, mk, L, mL, hx⟩)
        · exact absurd h (ef.den_none x)
        · exact ⟨w, (sl w).mpr ⟨L, mL, hw⟩, .atom s, Or.inl ms, hx⟩
        · simp at ms
        · obtain ⟨s', e, N, eN, hN⟩ := hR _ ms
          obtain rfl : s = s' := Term.atom.inj e
          exact ⟨w, (sl w).mpr ⟨L, mL, hw⟩, .atom s, Or.inr ⟨N, eN, hN⟩, hx⟩
        · obtain ⟨k₀, hk, ek⟩ := hs.hds _ mk
          cases ek
          obtain ⟨N, eN⟩ : ∃ N, (kind = "atom" → neg = .map N) := by
            by_cases ka : kind = "atom"
            · subst ka; obtain ⟨N, eN⟩ := hs.hatom.mp mk; exact ⟨N, fun _ => eN⟩
            · exact ⟨[], fun e => absurd e ka⟩
          obtain ⟨w, hw, κ, hκ, wκ⟩ := tag_witness ef (hl L mL).1 (hl L mL).2 hk hx N
          refine ⟨w, (sl w).mpr ⟨L, mL, hw⟩, κ, ?_, wκ⟩
          rcases hκ with ⟨ka, c, rfl, hc⟩ | ⟨k, i, rfl, rfl⟩
          · exact Or.inr ⟨N, eN ka, hc⟩
          · exact mk
      · rintro ⟨w, hw, κ, sk, hx⟩
        obtain ⟨L, mL, hL⟩ := (sl w).mp hw
        cases κ with
        | atom s =>
          rcases sk with ms | ⟨N, eN, hN⟩
          · exact Or.inl (Or.inl (Or.inl (Or.inr ⟨s, ms, L, mL, w, hL, hx⟩)))
          · by_cases sR : .atom s ∈ R
            · exact Or.inl (Or.inr ⟨s, sR, L, mL, w, hL, hx⟩)
            · obtain ⟨L', mL', ht⟩ := unnamed_tag ef lines hl' sl (swR N eN) hN sR hw hx
              exact Or.inr ⟨"atom", hs.hatom.mpr ⟨N, eN⟩, L', mL', ht⟩
        | dom k i =>
          obtain ⟨tag, l, negs, rfl, g, -, -⟩ := hl' L mL
          have := (inMLine_iff.mp hL).1.doms k i
          rw [hx] at this
          exact Or.inr ⟨domKind k, sk, _, mL, tag, l, negs, rfl, (tagSem_some ef g _ x).mp this⟩

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    section
    variable {nd : Term} {E : Term → Prop} {V : Type} {den : Term → V → Prop} {tl : V → Prop} {K : Nat}

    /-- A split of keys, as `map_split_keys_and_domains/1` returns it. -/
    def splitT (rs : List Term) (neg : Term) (ds : List Term) : Term :=
      .tuple #[Term.list rs, .nil, neg, Term.list ds, .nil]

    /-- `map_get_static/2` on a map field and a split of static keys: `:badmap` when it is empty, otherwise the union of
    the values its maps hold at the keys the split selects. -/
    theorem mstatic_get (ef : EF nd E V den tl K) {n : Nat} (hn : K + 2 ≤ n) {X : List (Term × Term)} {b : Term}
        (hb : mapLookup X (.atom "map") = some b) (fb : MField E b) {rs : List Term} {neg : Term} {ds : List Term}
        (hs : SplitOk rs neg ds) :
        ∃ res, Elixir.Module.Types.Descr.«map_get_static/2» (D (n + 4)) (.map X) (splitT rs neg ds) = .ok res ∧
          ((res = .atom "badmap" ∧ ∀ w, denMF E den b w = Bool.false) ∨
            (∃ T, res = .tuple #[.atom "ok", T] ∧ E T ∧ (∃ w, denMF E den b w = Bool.true) ∧
              ∀ x, den T x ↔ ∃ w, denMF E den b w = Bool.true ∧ ∃ κ, SplitKey rs neg ds κ ∧ w κ = some x)) := by
      by_cases three : ∃ k x y, b = .tuple #[k, x, y]
      · obtain ⟨k₀, x₀, y₀, e₀⟩ := three
        obtain ⟨k, tag, l, rfl, g, sl⟩ := mfield_three fb e₀
        have sem : ∀ w, denMF E den (.tuple #[.integer k, tag, fieldsTerm l]) w = Bool.true ↔ MSem den tag l w :=
          fun w => denMF_leaf ef sl g w
        obtain ⟨e, run⟩ := init_total ef.mopsE ef.mdopsE [] g.plain (fun e me => (sl.1 e me).2) (negs := []) (by simp)
        have run : Elixir.Module.Types.Descr.«init_map_line_empty?/4» (D (n + 4)) tag (fieldsTerm l) .nil (.map []) =
            .ok (boolAtom e) := run (n + 4) (by omega)
        cases e
        · -- Not empty: a map of the literal.
          have ne : ∃ w, MSem den tag l w := Classical.byContradiction fun none => by
            have := run.symm.trans (init_val ef.mopsE ef.mdopsE ef.msemZ (m := n + 4) (by omega) rfl g sl (negs := []) (by simp)
              fun w hw => absurd ⟨w, hw⟩ none)
            simp [boolAtom] at this
          obtain ⟨w₀, h₀⟩ := ne
          have line : ∀ w, InMLine den (.tuple #[tag, fieldsTerm l, Term.list []]) w ↔ MSem den tag l w := fun w => by
            rw [inMLine_iff]; simp
          obtain ⟨T, rT, hT, sT⟩ := get_dnf ef hn fb [.tuple #[tag, fieldsTerm l, Term.list []]]
            (fun L mL => by
              simp only [List.mem_singleton] at mL
              subst mL
              exact ⟨⟨tag, l, [], rfl, g, sl, by simp⟩, w₀, (line w₀).mpr h₀⟩)
            (fun w => by simp [sem, line]) hs
          refine ⟨_, ?_, Or.inr ⟨T, rfl, hT, ⟨w₀, (sem w₀).mpr h₀⟩, sT⟩⟩
          unfold Elixir.Module.Types.Descr.«map_get_static/2»
          simp only [Term.list] at rT
          simp [getMapKeys_single, hb, Elixir.Module.Types.Descr.«map_leaf_empty?/1»,
            Elixir.Module.Types.Descr.«init_map_line_empty?/3», run, Lynx.Term.isMember, boolAtom, rT, splitT]
        · refine ⟨.atom "badmap", ?_, Or.inl ⟨rfl, fun w => ?_⟩⟩
          · unfold Elixir.Module.Types.Descr.«map_get_static/2»
            simp [getMapKeys_single, hb, Elixir.Module.Types.Descr.«map_leaf_empty?/1»,
              Elixir.Module.Types.Descr.«init_map_line_empty?/3», run, Lynx.Term.isMember, boolAtom]
          · cases h : denMF E den (.tuple #[.integer k, tag, fieldsTerm l]) w
            · rfl
            · obtain ⟨N, mN, -⟩ := init_sound ef.mopsE ef.mdopsE ef.msemZ (m := n + 4) (by omega) rfl g sl (negs := []) (by simp) run w
                ((sem w).mp h)
              simp at mN
      · have wb : Bdd (MLit E) b := by
          rcases fb with ⟨k, rfl⟩ | wb
          · exact absurd ⟨_, _, _, rfl⟩ three
          · exact wb
        obtain ⟨lines, rl, hl, sl⟩ := dnf_neg_map (den := den) ef.mopsE ef.mdopsE ef.msemZ rfl (m := n + 4) (by omega) wb
        have inB : ∀ w, denMF E den b w = Bool.true ↔ ∃ L ∈ lines, InMLine den L w := fun w => by
          rw [denMF_bdd wb]; exact sl w
        cases lines with
        | nil =>
          refine ⟨.atom "badmap", ?_, Or.inl ⟨rfl, fun w => ?_⟩⟩
          · unfold Elixir.Module.Types.Descr.«map_get_static/2»
            rcases wb.shape with rfl | rfl | ⟨k, x, y, rfl⟩ | ⟨h', lit, c, u, d, rfl⟩
            · simp [getMapKeys_single, hb, rl, Term.list]
            · simp [getMapKeys_single, hb, rl, Term.list]
            · exact absurd ⟨_, _, _, rfl⟩ three
            · simp [getMapKeys_single, hb, rl, Term.list]
          · cases h : denMF E den b w
            · rfl
            · simpa using (inB w).mp h
        | cons L rest =>
          obtain ⟨T, rT, hT, sT⟩ := get_dnf ef hn fb (L :: rest) hl inB hs
          obtain ⟨w₀, h₀⟩ := (hl L List.mem_cons_self).2
          refine ⟨_, ?_, Or.inr ⟨T, rfl, hT, ⟨w₀, (inB w₀).mpr ⟨L, List.mem_cons_self, h₀⟩⟩, sT⟩⟩
          unfold Elixir.Module.Types.Descr.«map_get_static/2»
          rcases wb.shape with rfl | rfl | ⟨k, x, y, rfl⟩ | ⟨h', lit, c, u, d, rfl⟩
          · simp [getMapKeys_single, hb, rl, rT, Term.list, splitT]
          · simp [getMapKeys_single, hb, rl, rT, Term.list, splitT]
          · exact absurd ⟨_, _, _, rfl⟩ three
          · simp [getMapKeys_single, hb, rl, rT, Term.list, splitT]

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    section
    variable {t : Term} {n : Nat}

    /-- `map_get/2` on static types of the next level, with keys that split into static keys: types holding only maps give
    the union of the values their maps hold at the selected keys, or `:error` when there are none, and others `:badmap`. -/
    theorem get_map {X : List (Term × Term)} (hX : DE (level t n).E (.map X)) {rs : List Term} {neg : Term}
        {ds : List Term} (hs : SplitOk rs neg ds) {key : Term} {m : Nat} (hm : (level t n).K + 25 ≤ m)
        (hk : Elixir.Module.Types.Descr.«map_split_keys_and_domains/1» (D m) key = .ok (splitT rs neg ds)) :
        ∃ res, Elixir.Module.Types.Descr.«map_get/2» (D m) (.map X) key = .ok res ∧
          ((res = .atom "badmap" ∧ ¬MOnly t n X) ∨
            (res = .atom "error" ∧ MOnly t n X ∧ ∀ w, MT t n X w → ∀ κ, SplitKey rs neg ds κ → w κ = none) ∨
            ∃ T, res = .tuple #[.atom "ok", T] ∧ (level t n).E T ∧ MOnly t n X ∧ (∃ x, (level t n).den T x) ∧
              ∀ x, (level t n).den T x ↔ ∃ w, MT t n X w ∧ ∃ κ, SplitKey rs neg ds κ ∧ w κ = some x) := by
      obtain ⟨k, rfl⟩ : ∃ k, m = k + 4 := ⟨m - 4, by omega⟩
      have sX := de_map hX
      rw [Elixir.Module.Types.Descr.«map_get/2».eq_def]
      simp only [hk, Lynx.Except.ok_bind, Erlang.maps.«take/2», sX.static]
      have bad : ∀ r, Lynx.Dispatcher.pure (D (k + 4))
          (.function "Elixir.Module.Types.Descr" "-map_get/2-fun-0-" 1 #[]) #[r] =
            Elixir.Module.Types.Descr.«-map_get/2-fun-0-/1» r := fun r => by
        rw [Erlang.program.«Elixir.Module.Types.Descr:-map_get/2-fun-0-/1».pure]
      cases hb : mapLookup X (.atom "map") with
      | none =>
        refine ⟨.atom "badmap", ?_, Or.inl ⟨rfl, fun ⟨_, w, b, h, _⟩ => by rw [hb] at h; cases h⟩⟩
        simp [Elixir.Module.Types.Descr.«descr_key?/2», Erlang.erlang.«is_map_key/2», any_key, hb, Lynx.Except.andAlso, bad,
          Elixir.Module.Types.Descr.«-map_get/2-fun-0-/1»]
      | some b =>
        have fb : MField (level t n).E b := fieldC_map (sX.fields "map" b hb)
        obtain ⟨dR, sR⟩ := rest_map hX
        have rE := next_empty dR (m := k + 4) (by omega)
        have mt : ∀ w, MT t n X w ↔ denMF (level t n).E (level t n).den b w = Bool.true := fun w => by simp [MT, hb]
        have only : MOnly t n X ↔ (∀ v : PN t n, ¬denD (.map (rmM X)) v) ∧
            ∃ w, denMF (level t n).E (level t n).den b w = Bool.true := by
          constructor
          · rintro ⟨h₁, w, hw⟩
            exact ⟨fun v hv => ((sR v).mp hv).2 (h₁ v ((sR v).mp hv).1), w, (mt w).mp hw⟩
          · rintro ⟨h₁, w, hw⟩
            exact ⟨fun v hv => Classical.byContradiction fun ne => h₁ v ((sR v).mpr ⟨hv, ne⟩), w, (mt w).mpr hw⟩
        have key : Elixir.Module.Types.Descr.«descr_key?/2» (.map X) (.atom "map") = .ok (.atom "true") := by
          simp [Elixir.Module.Types.Descr.«descr_key?/2», Erlang.erlang.«is_map_key/2», any_key, hb, Term.true]
        have mo : Elixir.Module.Types.Descr.«map_only?/1» (D (k + 4)) (.map X) =
            .ok (boolAtom (bp (∀ v : PN t n, ¬denD (.map (rmM X)) v))) := by
          simp only [Elixir.Module.Types.Descr.«map_only?/1», Erlang.maps.«remove/2», Lynx.Except.ok_bind]
          exact rE
        by_cases restE : ∀ v : PN t n, ¬denD (.map (rmM X)) v
        · rw [bp_true.mpr restE] at mo
          obtain ⟨res, run, ⟨rfl, emp⟩ | ⟨T, rfl, hT, ⟨w₀, hw₀⟩, sT⟩⟩ := mstatic_get (level t n).ef (n := k) (by omega) hb fb hs
          · refine ⟨.atom "badmap", ?_, Or.inl ⟨rfl, fun h => ?_⟩⟩
            · simp [key, mo, run, Lynx.Except.andAlso, bad, Elixir.Module.Types.Descr.«-map_get/2-fun-0-/1»]
            · obtain ⟨-, w, hw⟩ := only.mp h
              rw [emp w] at hw; cases hw
          have ok : MOnly t n X := only.mpr ⟨restE, w₀, hw₀⟩
          obtain ⟨eb, reb, seb⟩ := (level t n).ef.empty_pub hT
          cases eb
          · refine ⟨_, ?_, Or.inr (Or.inr ⟨T, rfl, hT, ok, Classical.byContradiction fun h => ?_, fun x => ?_⟩)⟩
            · simp [key, mo, run, Lynx.Except.andAlso, reb (k + 4) (by omega), Lynx.Term.isMember,
                boolAtom]
            · exact absurd (seb.mpr fun x hx => h ⟨x, hx⟩) (by simp)
            · rw [sT]
              exact ⟨fun ⟨w, hw, h⟩ => ⟨w, (mt w).mpr hw, h⟩, fun ⟨w, hw, h⟩ => ⟨w, (mt w).mp hw, h⟩⟩
          · refine ⟨.atom "error", ?_, Or.inr (Or.inl ⟨rfl, ok, fun w hw κ hκ => ?_⟩)⟩
            · simp [key, mo, run, Lynx.Except.andAlso, reb (k + 4) (by omega), Lynx.Term.isMember,
                boolAtom]
            · cases h : w κ with
              | none => rfl
              | some x => exact absurd ((sT x).mpr ⟨w, (mt w).mp hw, κ, hκ, h⟩) (seb.mp rfl x)
        · rw [bp_false.mpr restE] at mo
          refine ⟨.atom "badmap", ?_, Or.inl ⟨rfl, fun h => restE (only.mp h).1⟩⟩
          simp [key, mo, Lynx.Except.andAlso, bad, Elixir.Module.Types.Descr.«-map_get/2-fun-0-/1», boolAtom]

    theorem get_map_term (d : Dispatcher) (key : Term) :
        Elixir.Module.Types.Descr.«map_get/2» d (.atom "term") key = .ok (.atom "badmap") := by
      rw [Elixir.Module.Types.Descr.«map_get/2».eq_def]
      rfl

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    /-- The kinds of keys of the bits of bitmaps. -/
    def bitKind : Nat → String
      | 0 => "binary"
      | 1 => "bitstring_no_binary"
      | 2 => "list"
      | 3 => "integer"
      | 4 => "float"
      | 5 => "pid"
      | 6 => "port"
      | _ => "reference"

    theorem testBit_and_pow (x i : Nat) : (x &&& 2 ^ i ≠ 0) ↔ x.testBit i = Bool.true := by
      constructor
      · intro h
        obtain ⟨j, hj⟩ := Nat.exists_testBit_of_ne_zero h
        rw [Nat.testBit_and, Nat.testBit_two_pow] at hj
        simp only [Bool.and_eq_true, decide_eq_true_eq] at hj
        rw [hj.2]; exact hj.1
      · intro h e
        have := Nat.testBit_and x (2 ^ i) i
        rw [e, Nat.zero_testBit, Nat.testBit_two_pow_self, h] at this
        cases this

    theorem ne_bit (x i : Nat) : Erlang.erlang.«/=/2» (.integer (Int.ofNat (x &&& 2 ^ i))) (.integer 0) =
        .ok (boolAtom (x.testBit i)) := by
      have := testBit_and_pow x i
      cases h : x.testBit i <;> simp_all [Erlang.erlang.«/=/2», boolAtom, Term.false, Term.true]

    theorem band_nat (x m : Nat) :
        Erlang.erlang.«band/2» (.integer (Int.ofNat x)) (.integer (Int.ofNat m)) = .ok (.integer (Int.ofNat (x &&& m))) :=
      rfl

    theorem bit_case (c : Bool) (a y : Term) :
        Elixir.Module.Types.Descr.«atom_intersection/2».match_3 (fun _ => Except Exception Term) (boolAtom c)
          (fun _ => pure y) (fun _ => pure (a.cons y))
          (fun u => Except.error (Exception.error (.tuple #[.atom "case_clause", u]))) =
          .ok (if c then a.cons y else y) := by
      cases c <;> rfl

    /-- A list with an element added when a condition holds. -/
    def ccons (c : Bool) (a : Term) (l : List Term) : List Term := if c then a :: l else l

    theorem ccons_list (c : Bool) (a : Term) (l : List Term) :
        (if c = Bool.true then a.cons (Term.list l) else Term.list l) = Term.list (ccons c a l) := by
      cases c <;> rfl

    theorem ccons_append (c : Bool) (a : Term) (l acc : List Term) : ccons c a l ++ acc = ccons c a (l ++ acc) := by
      cases c <;> rfl

    theorem mem_ccons {c : Bool} {a d : Term} {l : List Term} : d ∈ ccons c a l ↔ (c = Bool.true ∧ d = a) ∨ d ∈ l := by
      cases c <;> simp [ccons]

    theorem exists_lt_eight {P : Nat → Prop} :
        (∃ i < 8, P i) ↔ P 0 ∨ P 1 ∨ P 2 ∨ P 3 ∨ P 4 ∨ P 5 ∨ P 6 ∨ P 7 := by
      constructor
      · rintro ⟨i, hi, h⟩
        match i, hi with
        | 0, _ => exact Or.inl h
        | 1, _ => exact Or.inr (Or.inl h)
        | 2, _ => exact Or.inr (Or.inr (Or.inl h))
        | 3, _ => exact Or.inr (Or.inr (Or.inr (Or.inl h)))
        | 4, _ => exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inl h))))
        | 5, _ => exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr (Or.inl h)))))
        | 6, _ => exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr (Or.inr (Or.inl h))))))
        | 7, _ => exact Or.inr (Or.inr (Or.inr (Or.inr (Or.inr (Or.inr (Or.inr h))))))
      · rintro (h | h | h | h | h | h | h | h)
        · exact ⟨0, by omega, h⟩
        · exact ⟨1, by omega, h⟩
        · exact ⟨2, by omega, h⟩
        · exact ⟨3, by omega, h⟩
        · exact ⟨4, by omega, h⟩
        · exact ⟨5, by omega, h⟩
        · exact ⟨6, by omega, h⟩
        · exact ⟨7, by omega, h⟩

    /-- `bitmap_to_domain_keys/2` adds the kinds of the bits of a bitmap. -/
    theorem bitmap_keys (x : Nat) (acc : List Term) :
        ∃ pre, Elixir.Module.Types.Descr.«bitmap_to_domain_keys/2» (.integer (x : Int)) (Term.list acc) =
          .ok (Term.list (pre ++ acc)) ∧ ∀ d, d ∈ pre ↔ ∃ i < 8, x.testBit i = Bool.true ∧ d = .atom (bitKind i) := by
      have a0 : Erlang.erlang.«band/2» (.integer (x : Int)) (.integer 1) = .ok (.integer (Int.ofNat (x &&& 2 ^ 0))) :=
        band_nat x 1
      have a1 : Erlang.erlang.«band/2» (.integer (x : Int)) (.integer 2) = .ok (.integer (Int.ofNat (x &&& 2 ^ 1))) :=
        band_nat x 2
      have a2 : Erlang.erlang.«band/2» (.integer (x : Int)) (.integer 4) = .ok (.integer (Int.ofNat (x &&& 2 ^ 2))) :=
        band_nat x 4
      have a3 : Erlang.erlang.«band/2» (.integer (x : Int)) (.integer 8) = .ok (.integer (Int.ofNat (x &&& 2 ^ 3))) :=
        band_nat x 8
      have a4 : Erlang.erlang.«band/2» (.integer (x : Int)) (.integer 16) = .ok (.integer (Int.ofNat (x &&& 2 ^ 4))) :=
        band_nat x 16
      have a5 : Erlang.erlang.«band/2» (.integer (x : Int)) (.integer 32) = .ok (.integer (Int.ofNat (x &&& 2 ^ 5))) :=
        band_nat x 32
      have a6 : Erlang.erlang.«band/2» (.integer (x : Int)) (.integer 64) = .ok (.integer (Int.ofNat (x &&& 2 ^ 6))) :=
        band_nat x 64
      have a7 : Erlang.erlang.«band/2» (.integer (x : Int)) (.integer 128) = .ok (.integer (Int.ofNat (x &&& 2 ^ 7))) :=
        band_nat x 128
      refine ⟨(ccons (x.testBit 7) (.atom "reference") (ccons (x.testBit 6) (.atom "port") (ccons (x.testBit 5) (.atom "pid")
        (ccons (x.testBit 4) (.atom "float") (ccons (x.testBit 3) (.atom "integer") (ccons (x.testBit 2) (.atom "list")
        (ccons (x.testBit 1) (.atom "bitstring_no_binary") (ccons (x.testBit 0) (.atom "binary") [])))))))), ?_, fun d => ?_⟩
      · simp only [Elixir.Module.Types.Descr.«bitmap_to_domain_keys/2», a0, a1, a2, a3, a4, a5, a6, a7, Lynx.Except.ok_bind,
          ne_bit, bit_case, ccons_list, ccons_append, List.nil_append]
      · simp only [mem_ccons, List.not_mem_nil, or_false, exists_lt_eight, bitKind]
        simp only [or_comm, or_left_comm, or_assoc]

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    section
    variable {t : Term} {n : Nat}

    /-- The kind of keys of a point: the kind of its bit for bitmaps, otherwise its field. -/
    def ptKind (v : PN t n) : String := if v.1.1 = "bitmap" then bitKind v.1.2.1 else v.1.1

    /-- A point of a bitmap, at a bit. -/
    def bPt (i : Nat) (h : i < 8) : PN t n := ⟨("bitmap", (i, .nil, fun _ => Bool.false)), by simp [names],
      ⟨resp_const _, fun _ => h, fun h => by simp at h, fun h => by simp at h, fun h => by simp at h,
        fun h => by simp at h⟩⟩

    /-- A point of atoms, at a term. -/
    def aPt (q : Term) : PN t n := ⟨("atom", (0, q, fun _ => Bool.false)), by simp [names],
      ⟨resp_const _, fun h => by simp at h, fun h => by simp at h, fun h => by simp at h, fun h => by simp at h,
        fun h => by simp at h⟩⟩

    theorem denD_field {Y : List (Term × Term)} (v : PN t n) :
        denD (.map Y) v ↔ ∃ x, mapLookup Y (.atom v.1.1) = some x ∧ dn v.1.1 (some x) v.1.2 = Bool.true := by
      rw [denD_map]
      cases mapLookup Y (.atom v.1.1) <;> simp [dn_none]

    /-- A type restricted to one of its fields. -/
    theorem field_de {Y : List (Term × Term)} (hY : DE (level t n).E (.map Y)) {name : String} {x : Term}
        (hx : mapLookup Y (.atom name) = some x) :
        DE (level t n).E (.map [(.atom name, x)]) ∧
          ∀ v : PN t n, denD (.map [(.atom name, x)]) v ↔ v.1.1 = name ∧ denD (.map Y) v := by
      have sY := de_map hY
      refine ⟨Or.inr ⟨_, rfl, fun q h => ?_, fun name' w h => ?_⟩, fun v => ?_⟩
      · simp only [mapLookup, List.find?_cons, List.find?_nil] at h
        by_cases e : compareExact (fuel q (.atom name)) q (.atom name) = .eq
        · rw [(compareExact_eq_atom _ _).mp e]
          exact sY.keys _ (by rw [hx]; rfl)
        · simp [e] at h
      · rw [lookup_cons_atom] at h
        by_cases e : name = name'
        · subst e
          simp at h
          subst h
          exact sY.fields _ _ hx
        · simp [e, mapLookup] at h
      · rw [denD_field, denD_field, lookup_cons_atom]
        by_cases e : name = v.1.1
        · rw [← e, hx]; simp
        · simp [e, mapLookup]
          exact fun h => absurd h.symm e

    /-- Bitmaps of key types whose kinds include lists through the empty list. -/
    def ListSkip (Y : List (Term × Term)) : Prop :=
      ∃ b : Nat, mapLookup Y (.atom "bitmap") = some (.integer b) ∧ b.testBit 2 = Bool.true

    /-- The kinds of keys that a field of a key type contributes to its domain keys. -/
    def Contrib (Y : List (Term × Term)) (name : String) (x : Term) (s : String) : Prop :=
      (name = "bitmap" ∧ ∃ b : Nat, x = .integer b ∧ ∃ i < 8, b.testBit i = Bool.true ∧ bitKind i = s) ∨
      (name = "atom" ∧ s = "atom" ∧ ∃ S, x = .tuple #[.atom "negation", .map S]) ∨
      (name ≠ "bitmap" ∧ name ≠ "atom" ∧ s = name ∧ ¬(name = "list" ∧ ListSkip Y) ∧
        ∃ v : PN t n, v.1.1 = name ∧ denD (.map Y) v)

    theorem dom_step {Y : List (Term × Term)} (hY : DE (level t n).E (.map Y)) {name : String} {x : Term}
        (hx : mapLookup Y (.atom name) = some x) {m : Nat} (hm : (level t n).K + 23 ≤ m) (acc : List Term) :
        ∃ pre, Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4» (D m) (.map Y) (.atom name) x (Term.list acc) =
            .ok (Term.list (pre ++ acc)) ∧ (∀ d ∈ pre, ∃ s ∈ domainKinds, d = .atom s) ∧
          ∀ s, .atom s ∈ pre ↔ Contrib (t := t) (n := n) Y name x s := by
      have sY := de_map hY
      obtain ⟨name', mn, e⟩ := sY.keys (.atom name) (by rw [hx]; rfl)
      obtain rfl : name = name' := Term.atom.inj e
      have fx := sY.fields name x hx
      obtain ⟨dF, sF⟩ := field_de hY hx
      have emp := next_empty dF hm
      simp only [names, List.mem_cons, List.not_mem_nil, or_false] at mn
      have eb : bp (∀ v : PN t n, ¬denD (.map [(.atom name, x)]) v) =
          !bp (∃ v : PN t n, v.1.1 = name ∧ denD (.map Y) v) := by
        by_cases h : ∃ v : PN t n, v.1.1 = name ∧ denD (.map Y) v
        · obtain ⟨v, hv⟩ := h
          rw [bp_false.mpr fun h' => h' v ((sF v).mpr hv), bp_true.mpr ⟨v, hv⟩]; rfl
        · rw [bp_true.mpr fun v hv => h ⟨v, (sF v).mp hv⟩, bp_false.mpr h]; rfl
      rw [eb] at emp
      rcases mn with rfl | rfl | rfl | rfl | rfl | rfl
      · -- bitmap
        obtain ⟨b, rfl, -, -⟩ := fieldC_bitmap fx
        obtain ⟨pre, run, mem⟩ := bitmap_keys b acc
        refine ⟨pre, ?_, fun d md => ?_, fun s => ?_⟩
        · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, run]
        · obtain ⟨i, hi, -, rfl⟩ := (mem d).mp md
          refine ⟨_, ?_, rfl⟩
          match i, hi with
          | 0, _ | 1, _ | 2, _ | 3, _ | 4, _ | 5, _ | 6, _ | 7, _ => simp [bitKind, domainKinds]
        · rw [mem]
          simp only [Contrib, Term.atom.injEq, true_and]
          constructor
          · rintro ⟨i, hi, hb, rfl⟩
            exact Or.inl ⟨b, rfl, i, hi, hb, rfl⟩
          · rintro (⟨b', e, i, hi, hb, rfl⟩ | ⟨h, -⟩ | ⟨h, -⟩)
            · obtain rfl : b = b' := by have := Term.integer.inj e; omega
              exact ⟨i, hi, hb, rfl⟩
            · simp at h
            · exact absurd rfl h
      · -- atom
        obtain ⟨⟨pos, S, rfl, -⟩, q, hq⟩ := fieldC_atom fx
        cases pos
        · have ne : bp (∃ v : PN t n, v.1.1 = "atom" ∧ denD (.map Y) v) = Bool.true :=
            bp_true.mpr ⟨aPt q, rfl, (denD_field _).mpr ⟨_, hx, by simpa [aPt, dn_atom] using hq⟩⟩
          rw [ne] at emp
          simp only [Bool.false_eq_true, ↓reduceIte] at emp
          refine ⟨[.atom "atom"], ?_, fun d md => ⟨"atom", by simp [domainKinds], by simpa using md⟩, fun s => ?_⟩
          · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
              boolAtom, Term.list]
          · simp [Contrib]
        · refine ⟨[], ?_, by simp, fun s => ?_⟩
          · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso]
          · simp [Contrib]
      · -- fun
        by_cases ne : ∃ v : PN t n, v.1.1 = "fun" ∧ denD (.map Y) v
        · rw [bp_true.mpr ne] at emp
          refine ⟨[.atom "fun"], ?_, fun d md => ⟨"fun", by simp [domainKinds], by simpa using md⟩, fun s => ?_⟩
          · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
              boolAtom, Term.list]
          · simp [Contrib, ne]
        · rw [bp_false.mpr ne] at emp
          refine ⟨[], ?_, by simp, fun s => ?_⟩
          · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
              boolAtom]
          · simp [Contrib, ne]
      · -- list
        cases hb : mapLookup Y (.atom "bitmap") with
        | none =>
          have nsk : ¬ListSkip Y := fun ⟨b, h, _⟩ => by rw [hb] at h; cases h
          by_cases ne : ∃ v : PN t n, v.1.1 = "list" ∧ denD (.map Y) v
          · rw [bp_true.mpr ne] at emp
            refine ⟨[.atom "list"], ?_, fun d md => ⟨"list", by simp [domainKinds], by simpa using md⟩, fun s => ?_⟩
            · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
                boolAtom, Term.list, getMapKeys_single, hb]
            · simp [Contrib, ne, nsk]
          · rw [bp_false.mpr ne] at emp
            refine ⟨[], ?_, by simp, fun s => ?_⟩
            · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
                boolAtom, getMapKeys_single, hb]
            · simp [Contrib, ne]
        | some x' =>
          obtain ⟨b, rfl, -, -⟩ := fieldC_bitmap (sY.fields _ _ hb)
          have a2 : Erlang.erlang.«band/2» (.integer (b : Int)) (.integer 4) = .ok (.integer (Int.ofNat (b &&& 2 ^ 2))) :=
            band_nat b 4
          have n2 := ne_bit b 2
          have i2 : (if b &&& 4 = 0 then Term.atom "false" else Term.atom "true") = boolAtom (b.testBit 2) := by
            have := testBit_and_pow b 2
            cases h : b.testBit 2 <;> simp_all [boolAtom]
          cases tb : b.testBit 2
          · have nsk : ¬ListSkip Y := fun ⟨b', h, t'⟩ => by
              rw [hb] at h
              obtain rfl : b = b' := by have := Term.integer.inj (Option.some.inj h); omega
              rw [tb] at t'; cases t'
            by_cases ne : ∃ v : PN t n, v.1.1 = "list" ∧ denD (.map Y) v
            · rw [bp_true.mpr ne] at emp
              refine ⟨[.atom "list"], ?_, fun d md => ⟨"list", by simp [domainKinds], by simpa using md⟩, fun s => ?_⟩
              · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
                  boolAtom, Term.list, getMapKeys_single, hb, a2, i2, tb]
              · simp [Contrib, ne, nsk]
            · rw [bp_false.mpr ne] at emp
              refine ⟨[], ?_, by simp, fun s => ?_⟩
              · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
                  boolAtom, getMapKeys_single, hb, a2, i2, tb]
              · simp [Contrib, ne]
          · refine ⟨[], ?_, by simp, fun s => ?_⟩
            · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso,
                getMapKeys_single, hb, a2, i2, tb, boolAtom]
            · have sk : ListSkip Y := ⟨b, hb, tb⟩
              simp [Contrib, sk]
      · -- tuple
        by_cases ne : ∃ v : PN t n, v.1.1 = "tuple" ∧ denD (.map Y) v
        · rw [bp_true.mpr ne] at emp
          refine ⟨[.atom "tuple"], ?_, fun d md => ⟨"tuple", by simp [domainKinds], by simpa using md⟩, fun s => ?_⟩
          · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
              boolAtom, Term.list]
          · simp [Contrib, ne]
        · rw [bp_false.mpr ne] at emp
          refine ⟨[], ?_, by simp, fun s => ?_⟩
          · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
              boolAtom]
          · simp [Contrib, ne]
      · -- map
        by_cases ne : ∃ v : PN t n, v.1.1 = "map" ∧ denD (.map Y) v
        · rw [bp_true.mpr ne] at emp
          refine ⟨[.atom "map"], ?_, fun d md => ⟨"map", by simp [domainKinds], by simpa using md⟩, fun s => ?_⟩
          · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
              boolAtom, Term.list]
          · simp [Contrib, ne]
        · rw [bp_false.mpr ne] at emp
          refine ⟨[], ?_, by simp, fun s => ?_⟩
          · simp [Elixir.Module.Types.Descr.«-to_domain_keys/1-fun-0-/4», Erlang.erlang.«==/2», Lynx.Except.andAlso, emp,
              boolAtom]
          · simp [Contrib, ne]

    /-- `maps:fold/3` of the domain keys step over fields of a key type. -/
    theorem dom_fold {Y : List (Term × Term)} (hY : DE (level t n).E (.map Y)) {m : Nat} (hm : (level t n).K + 23 ≤ m) :
        ∀ (es : List (Term × Term)), (∀ e ∈ es, mapLookup Y e.1 = some e.2) → ∀ acc : List Term,
          ∃ out, es.foldlM (fun acc e => Lynx.Dispatcher.pure (D (m + 1))
              (.function "Elixir.Module.Types.Descr" "-to_domain_keys/1-fun-0-" 3 #[.map Y]) #[e.1, e.2, acc])
              (Term.list acc) = .ok (Term.list (out ++ acc)) ∧ (∀ d ∈ out, ∃ s ∈ domainKinds, d = .atom s) ∧
            ∀ s, .atom s ∈ out ↔ ∃ e ∈ es, ∃ name, e.1 = .atom name ∧ Contrib (t := t) (n := n) Y name e.2 s
      | [], _, acc => ⟨[], rfl, by simp, by simp⟩
      | (k, x) :: es, hes, acc => by
        have hk := hes _ List.mem_cons_self
        obtain ⟨name, -, rfl⟩ := (de_map hY).keys k (by rw [hk]; rfl)
        obtain ⟨pre, run, hpre, spre⟩ := dom_step hY hk hm acc
        obtain ⟨out, run', hout, sout⟩ := dom_fold hY hm es (fun e me => hes e (List.mem_cons_of_mem _ me)) (pre ++ acc)
        refine ⟨out ++ pre, ?_, fun d md => ?_, fun s => ?_⟩
        · simp only [List.foldlM_cons]
          rw [Erlang.program.«Elixir.Module.Types.Descr:-to_domain_keys/1-fun-0-/3».pure, run]
          simpa using run'
        · rcases List.mem_append.mp md with h | h
          · exact hout d h
          · exact hpre d h
        · rw [List.mem_append, sout, spre]
          constructor
          · rintro (⟨e, me, h⟩ | h)
            · exact ⟨e, List.mem_cons_of_mem _ me, h⟩
            · exact ⟨_, List.mem_cons_self, name, rfl, h⟩
          · rintro ⟨e, me, name', e₁, h⟩
            rcases List.mem_cons.mp me with rfl | me
            · obtain rfl : name = name' := Term.atom.inj e₁
              exact Or.inr h
            · exact Or.inl ⟨e, me, name', e₁, h⟩

    theorem entry_of_lookup_entries {es : List (Term × Term)} {q x : Term} (h : mapLookup es q = some x) :
        ∃ e ∈ mapEntries es, compareExact (fuel q e.1) q e.1 = .eq ∧ e.2 = x := by
      rw [← mapLookup_mapEntries, mapLookup] at h
      cases e : (mapEntries es).find? (fun entry => decide (compareExact (fuel q entry.1) q entry.1 = .eq)) with
      | none => rw [e] at h; cases h
      | some r =>
        rw [e] at h
        simp only [Option.map_some, Option.some.injEq] at h
        have := List.find?_some e
        simp only [decide_eq_true_eq] at this
        exact ⟨r, List.mem_of_find?_eq_some e, this, h⟩

    /-- `to_domain_keys/1` on a static key type: the kinds its fields contribute. -/
    theorem dom_keys {Y : List (Term × Term)} (hY : DE (level t n).E (.map Y)) {m : Nat} (hm : (level t n).K + 23 ≤ m) :
        ∃ ds, Elixir.Module.Types.Descr.«to_domain_keys/1» (D (m + 1)) (.map Y) = .ok (Term.list ds) ∧
          (∀ d ∈ ds, ∃ s ∈ domainKinds, d = .atom s) ∧
          ∀ s, .atom s ∈ ds ↔ ∃ name x, mapLookup Y (.atom name) = some x ∧ Contrib (t := t) (n := n) Y name x s := by
      obtain ⟨out, run, hout, sout⟩ := dom_fold hY hm (mapEntries Y)
        (fun e me => mapLookup_of_mem_mapEntries me) []
      refine ⟨out, ?_, hout, fun s => ?_⟩
      · rw [Elixir.Module.Types.Descr.«to_domain_keys/1».eq_def]
        simp only [getMapKeys_single, (de_map hY).static, Option.toList_none]
        simpa [Erlang.maps.«fold/3», Term.list] using run
      · rw [sout]
        constructor
        · rintro ⟨e, me, name, e₁, h⟩
          exact ⟨name, e.2, by rw [← e₁]; exact mapLookup_of_mem_mapEntries me, h⟩
        · rintro ⟨name, x, hx, h⟩
          obtain ⟨e, me, ec, rfl⟩ := entry_of_lookup_entries hx
          exact ⟨e, me, name, ((compareExact_eq_atom _ _).mp (Lynx.Term.compareExact_eq_symm ec)), h⟩

    /-- Kinds of keys of static key types: the atom kind for negated atoms, and the other kinds of their points. -/
    theorem dom_kinds {Y : List (Term × Term)} (hY : DE (level t n).E (.map Y)) {m : Nat} (hm : (level t n).K + 23 ≤ m) :
        ∃ ds, Elixir.Module.Types.Descr.«to_domain_keys/1» (D (m + 1)) (.map Y) = .ok (Term.list ds) ∧
          (∀ d ∈ ds, ∃ s ∈ domainKinds, d = .atom s) ∧
          (.atom "atom" ∈ ds ↔ ∃ S, mapLookup Y (.atom "atom") = some (.tuple #[.atom "negation", .map S])) ∧
          ∀ s, s ≠ "atom" → (.atom s ∈ ds ↔ ∃ v : PN t n, denD (.map Y) v ∧ ptKind v = s) := by
      obtain ⟨ds, run, hds, sds⟩ := dom_keys hY hm
      refine ⟨ds, run, hds, ?_, fun s ns => ?_⟩
      · rw [sds]
        constructor
        · rintro ⟨name, x, hx, (⟨rfl, b, -, i, hi, -, e⟩ | ⟨rfl, -, S, rfl⟩ | ⟨-, na, e, -⟩)⟩
          · match i, hi with
            | 0, _ | 1, _ | 2, _ | 3, _ | 4, _ | 5, _ | 6, _ | 7, _ => simp [bitKind] at e
          · exact ⟨S, hx⟩
          · exact absurd e.symm na
        · rintro ⟨S, hS⟩
          exact ⟨"atom", _, hS, Or.inr (Or.inl ⟨rfl, rfl, S, rfl⟩)⟩
      · rw [sds]
        constructor
        · rintro ⟨name, x, hx, (⟨rfl, b, rfl, i, hi, hb, rfl⟩ | ⟨-, e, -⟩ | ⟨nb, -, rfl, -, v, hv, dv⟩)⟩
          · refine ⟨bPt i hi, (denD_field _).mpr ⟨_, hx, ?_⟩, rfl⟩
            simp [bPt, dn_bitmap, bitOf, hb]
          · exact absurd e ns
          · exact ⟨v, dv, by simp [ptKind, hv, nb]⟩
        · rintro ⟨v, dv, rfl⟩
          obtain ⟨x, hx, dx⟩ := (denD_field v).mp dv
          by_cases hb : v.1.1 = "bitmap"
          · rw [hb] at hx dx
            obtain ⟨b, rfl, -, -⟩ := fieldC_bitmap ((de_map hY).fields _ _ hx)
            have hi : v.1.2.1 < 8 := v.2.2.2.1 hb
            refine ⟨"bitmap", _, hx, Or.inl ⟨rfl, b, rfl, v.1.2.1, hi, ?_, by simp [ptKind, hb]⟩⟩
            simpa [dn_bitmap, bitOf] using dx
          · have pk : ptKind v = v.1.1 := by simp [ptKind, hb]
            rw [pk] at ns ⊢
            by_cases sk : v.1.1 = "list" ∧ ListSkip Y
            · obtain ⟨e, b, hb', tb⟩ := sk
              exact ⟨"bitmap", _, hb', Or.inl ⟨rfl, b, rfl, 2, by omega, tb, by rw [e]; rfl⟩⟩
            · exact ⟨v.1.1, x, hx, Or.inr (Or.inr ⟨hb, ns, rfl, sk, v, rfl, dv⟩)⟩

    theorem denD_aPt {Y : List (Term × Term)} (q : Term) :
        denD (.map Y) (aPt (t := t) (n := n) q) ↔ amemV (mapLookup Y (.atom "atom")) q = Bool.true := by
      rw [denD_map]
      simp only [aPt]
      cases h : mapLookup Y (.atom "atom") <;> simp [dn_none, dn_atom, amemV]

    /-- `map_split_keys_and_domains/1` on a static key type, whose unions of atoms hold atoms: the atoms of its points,
    and the kinds of its other points. -/
    theorem split_map {Y : List (Term × Term)} (hY : DE (level t n).E (.map Y))
        (hU : ∀ S, mapLookup Y (.atom "atom") = some (.tuple #[.atom "union", .map S]) →
          ∀ q, (mapLookup S q).isSome → ∃ s, q = .atom s)
        {m : Nat} (hm : (level t n).K + 23 ≤ m) :
        ∃ rs neg ds, Elixir.Module.Types.Descr.«map_split_keys_and_domains/1» (D (m + 1)) (.map Y) =
            .ok (splitT rs neg ds) ∧ SplitOk rs neg ds ∧
          (∀ s, SplitKey rs neg ds (.atom s) ↔ denD (.map Y) (aPt (t := t) (n := n) (.atom s))) ∧
          ∀ k i, SplitKey rs neg ds (.dom k i) ↔ ∃ v : PN t n, denD (.map Y) v ∧ ptKind v = domKind k := by
      obtain ⟨ds, rd, hds, hat, hk⟩ := dom_kinds hY hm
      have dom : ∀ rs neg k i, SplitKey rs neg ds (.dom k i) ↔ ∃ v : PN t n, denD (.map Y) v ∧ ptKind v = domKind k :=
        fun rs neg k i => hk _ (domKind_ne_atom k)
      have st := (de_map hY).static
      cases ha : mapLookup Y (.atom "atom") with
      | none =>
        refine ⟨[], .atom "nil", ds, ?_, ⟨by simp, Or.inl rfl, hds, ?_⟩, fun s => ?_, dom _ _⟩
        · rw [Elixir.Module.Types.Descr.«map_split_keys_and_domains/1».eq_def]
          simp [getMapKeys_single, st, ha, rd, splitT, Term.list]
        · rw [hat, ha]; simp
        · rw [denD_aPt, ha]; simp [SplitKey, amemV]
      | some x =>
        obtain ⟨⟨pos, S, rfl, -⟩, -⟩ := fieldC_atom ((de_map hY).fields _ _ ha)
        cases pos
        · refine ⟨[], .map S, ds, ?_, ⟨by simp, Or.inr ⟨S, rfl⟩, hds, ?_⟩, fun s => ?_, dom _ _⟩
          · rw [Elixir.Module.Types.Descr.«map_split_keys_and_domains/1».eq_def]
            simp [getMapKeys_single, st, ha, rd, splitT, Term.list]
          · rw [hat, ha]; simp
          · rw [denD_aPt, ha]; simp [SplitKey, amemV]
        · have hU' := hU S (by simpa using ha)
          refine ⟨(mapEntries S).map Prod.fst, .atom "nil", ds, ?_, ⟨fun r mr => ?_, Or.inl rfl, hds, ?_⟩, fun s => ?_,
            dom _ _⟩
          · rw [Elixir.Module.Types.Descr.«map_split_keys_and_domains/1».eq_def]
            simp [getMapKeys_single, st, ha, rd, splitT, Erlang.sets.«to_list/1», Erlang.maps.«keys/1»]
          · obtain ⟨e, me, rfl⟩ := List.mem_map.mp mr
            exact hU' e.1 (by rw [mapLookup_of_mem_mapEntries me]; rfl)
          · rw [hat, ha]; simp
          · rw [denD_aPt, ha]
            simp only [SplitKey, ↓reduceIte, amemV]
            constructor
            · rintro (m | ⟨N, e, -⟩)
              · obtain ⟨e, me, he⟩ := List.mem_map.mp m
                rw [← he, mapLookup_of_mem_mapEntries me]; rfl
              · cases e
            · intro h
              obtain ⟨v, hv⟩ := Option.isSome_iff_exists.mp h
              obtain ⟨e, me, ec, -⟩ := entry_of_lookup_entries hv
              exact Or.inl (List.mem_map.mpr ⟨e, me, ((compareExact_eq_atom _ _).mp (Lynx.Term.compareExact_eq_symm ec))⟩)

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    section
    variable {t : Term} {n : Nat}

    /-- Unions of static map types of the next level are maps of the points of either. -/
    theorem union_map {A B : List (Term × Term)} (hA : DE (level t n).E (.map A)) (hB : DE (level t n).E (.map B)) {m : Nat}
        (hm : (level t n).K + 23 ≤ m) :
        ∃ U, Elixir.Module.Types.Descr.«bare_union/2» (D m) (.map A) (.map B) = .ok (.map U) ∧
          DE (level t n).E (.map U) ∧ ∀ v : PN t n, denD (.map U) v ↔ denD (.map A) v ∨ denD (.map B) v := by
      obtain ⟨c, hc, rc, sc, -⟩ := (ef_next t n).union hA hB
      obtain ⟨k, rfl⟩ : ∃ k, m = k + 1 := ⟨m - 1, by omega⟩
      have sA := de_map hA
      have sB := de_map hB
      obtain ⟨U, rU, -⟩ := union_any k A B sA.static sB.static (fun q h => let ⟨name, _, e⟩ := sB.keys q h; ⟨name, e⟩)
        (fun q x y hx hy => by
          obtain ⟨name, -, rfl⟩ := sA.keys q (by rw [hx]; rfl)
          obtain ⟨u, ru, -⟩ := fieldC_union (tks (level t n)) (tfc (level t n)) (m := k) (by omega)
            (sA.fields _ _ hx) (sB.fields _ _ hy)
          exact ⟨u, ru⟩)
      have e := (rc (k + 1) hm).symm.trans rU
      simp only [Except.ok.injEq] at e
      subst e
      exact ⟨U, rU, hc, sc⟩

    theorem denD_single (name : String) (x : Term) (v : PN t n) :
        denD (.map [(.atom name, x)]) v ↔ v.1.1 = name ∧ dn name (some x) v.1.2 = Bool.true := by
      rw [denD_map, lookup_cons_atom]
      by_cases e : name = v.1.1
      · subst e; simp
      · simp [e, mapLookup, dn_none]
        exact fun h => absurd h.symm e

    theorem single_de {name : String} {x : Term} (hn : name ∈ names)
        (fx : FieldC (FunA (level t n).E) (TField (level t n).E) (LF (level t n).E) (MField (level t n).E) name x) :
        DE (level t n).E (.map [(.atom name, x)]) := by
      refine Or.inr ⟨_, rfl, fun q h => ?_, fun name' w h => ?_⟩
      · simp only [mapLookup, List.find?_cons, List.find?_nil] at h
        by_cases e : compareExact (fuel q (.atom name)) q (.atom name) = .eq
        · exact ⟨name, hn, (compareExact_eq_atom _ _).mp e⟩
        · simp [e] at h
      · rw [lookup_cons_atom] at h
        by_cases e : name = name'
        · subst e; simp at h; subst h; exact fx
        · simp [e, mapLookup] at h

    /-- Key types of a kind: their points are of that kind, every atom for the atom kind, and some point otherwise. -/
    structure KindT (t : Term) (n : Nat) (d : String) (T : List (Term × Term)) : Prop where
      de : DE (level t n).E (.map T)
      pts : ∀ v : PN t n, denD (.map T) v → (d = "atom" ∧ v.1.1 = "atom") ∨ (v.1.1 ≠ "atom" ∧ ptKind v = d)
      wit : d ≠ "atom" → ∃ v : PN t n, denD (.map T) v ∧ ptKind v = d
      atoms : d = "atom" → ∀ q, denD (.map T) (aPt (t := t) (n := n) q)

    theorem kind_bit (i : Nat) (hi : i < 8) : KindT t n (bitKind i) [(.atom "bitmap", .integer ((2 ^ i : Nat) : Int))] := by
      have pos : 1 ≤ 2 ^ i := Nat.one_le_two_pow
      have le : 2 ^ i ≤ 255 := by
        have : 2 ^ i ≤ 2 ^ 7 := Nat.pow_le_pow_right (by omega) (by omega)
        omega
      have bk : bitKind i ≠ "atom" := by
        match i, hi with
        | 0, _ | 1, _ | 2, _ | 3, _ | 4, _ | 5, _ | 6, _ | 7, _ => simp [bitKind]
      refine ⟨single_de (by simp [names]) (Or.inl ⟨rfl, _, rfl, pos, le⟩), fun v hv => ?_, fun _ => ⟨bPt i hi, ?_, rfl⟩,
        fun h => absurd h bk⟩
      · obtain ⟨hb, hd⟩ := (denD_single _ _ v).mp hv
        rw [dn_bitmap, bitOf] at hd
        simp only [Int.toNat_natCast, Nat.testBit_two_pow, decide_eq_true_eq] at hd
        refine Or.inr ⟨by rw [hb]; decide, by simp [ptKind, hb, ← hd]⟩
      · rw [denD_single]
        simp only [bPt, dn_bitmap, bitOf, Int.toNat_natCast, Nat.testBit_two_pow_self, and_self]

    theorem kind_atom : KindT t n "atom" [(.atom "atom", .tuple #[.atom "negation", .map []])] := by
      refine ⟨single_de (by simp [names]) (Or.inr (Or.inl ⟨rfl, ⟨Bool.false, [], rfl, by simp [Erlang.sets.elements?]⟩, .nil,
        by simp [amemV, mapLookup]⟩)), fun v hv => Or.inl ⟨rfl, ((denD_single _ _ v).mp hv).1⟩, fun h => absurd rfl h, fun _ q => ?_⟩
      rw [denD_single]
      simp [aPt, dn_atom, amemV, mapLookup]

    theorem kind_fun : KindT t n "fun" [(.atom "fun", funTopT)] := by
      obtain ⟨a, ρ, rρ, fv⟩ := fVal_wit (E := (level t n).E) (den := (level t n).den)
      let w : PN t n := ⟨("fun", (0, a, ρ)), by simp [names],
        ⟨rρ, fun h => by simp at h, fun h => by simp at h, fun h => by simp at h, fun h => by simp at h, fun _ => fv⟩⟩
      refine ⟨single_de (by simp [names]) (Or.inr (Or.inr (Or.inl ⟨rfl, funA_top⟩))), fun v hv => ?_,
        fun _ => ⟨w, (denD_single _ _ w).mpr ⟨rfl, dn_funTop _⟩, rfl⟩, fun h => by simp at h⟩
      have hf := ((denD_single _ _ v).mp hv).1
      exact Or.inr ⟨by rw [hf]; decide, by simp [ptKind, hf]⟩

    theorem kind_map : KindT t n "map" [(.atom "map", .tuple #[.integer 61102469, .atom "open", .nil])] := by
      refine ⟨mapTop_de, fun v hv => ?_, fun _ => ⟨mpt (fun _ => none), (mapTop_den _).mpr rfl, rfl⟩,
        fun h => by simp at h⟩
      have hm := (mapTop_den v).mp hv
      exact Or.inr ⟨by rw [hm]; decide, by simp [ptKind, hm]⟩

    theorem kind_tuple : KindT t n "tuple" [(.atom "tuple", .tuple #[.integer 61102469, .atom "open", .nil])] := by
      refine ⟨tupleTop_de, fun v hv => ?_, fun _ => ⟨tpt [], (tupleTop_den _).mpr rfl, rfl⟩, fun h => by simp at h⟩
      have hm := (tupleTop_den v).mp hv
      exact Or.inr ⟨by rw [hm]; decide, by simp [ptKind, hm]⟩

    theorem non_empty_list_top (m : Nat) : Elixir.Module.Types.Descr.«non_empty_list/2» (D m) (.atom "term") (.atom "term") =
        .ok (.map [(.atom "list", .tuple #[.integer 46675407, .atom "term", .atom "term"])]) := by
      simp [Elixir.Module.Types.Descr.«non_empty_list/2», Elixir.Module.Types.Descr.«list_descr/3»,
        Elixir.Module.Types.Descr.«split_dynamic/1», Elixir.Module.Types.Descr.«list_descr_static/3», Erlang.erlang.«==/2»,
        Lynx.Except.orElse, Term.compare_step, Compare.compareStep]

    theorem kind_list {m : Nat} (hm : (level t n).K + 23 ≤ m) :
        ∃ T, Elixir.STTDescrProofsTest.«kind_type/1» (D m) (.atom "list") = .ok (.map T) ∧ KindT t n "list" T := by
      have b2 := kind_bit (t := t) (n := n) 2 (by omega)
      simp only [show ((2 ^ 2 : Nat) : Int) = 4 from rfl] at b2
      have dl : DE (level t n).E (.map [(.atom "list", .tuple #[.integer 46675407, .atom "term", .atom "term"])]) :=
        single_de (by simp [names]) (Or.inr (Or.inr (Or.inr (Or.inl ⟨rfl, Bdd.leaf_iff.mpr
          ⟨46675407, _, _, rfl, (level t n).ef.term, (level t n).ef.term⟩⟩))))
      obtain ⟨U, rU, dU, sU⟩ := union_map b2.de dl hm
      refine ⟨U, ?_, ⟨dU, fun v hv => ?_, fun _ => ⟨bPt 2 (by omega), (sU _).mpr (Or.inl ?_), rfl⟩, fun h => by simp at h⟩⟩
      · simp [Elixir.STTDescrProofsTest.«kind_type/1», Elixir.Module.Types.Descr.«empty_list/0»,
          Elixir.Module.Types.Descr.«term/0», non_empty_list_top, rU]
      · rcases (sU v).mp hv with h | h
        · rcases b2.pts v h with ⟨e, -⟩ | ⟨ne, pk⟩
          · simp [bitKind] at e
          · exact Or.inr ⟨ne, pk⟩
        · have hl := ((denD_single _ _ v).mp h).1
          exact Or.inr ⟨by rw [hl]; decide, by simp [ptKind, hl]⟩
      · exact (denD_single _ _ _).mpr ⟨rfl, by simp only [bPt, dn_bitmap, bitOf]; decide⟩

    /-- The key types of the spec's kinds. -/
    theorem kind_run {d : String} (hd : d ∈ domainKinds) {m : Nat} (hm : (level t n).K + 23 ≤ m) :
        ∃ T, Elixir.STTDescrProofsTest.«kind_type/1» (D m) (.atom d) = .ok (.map T) ∧ KindT t n d T := by
      simp only [domainKinds, List.mem_cons, List.not_mem_nil, or_false] at hd
      rcases hd with rfl | rfl | rfl | rfl | rfl | rfl | rfl | rfl | rfl | rfl | rfl | rfl
      · exact ⟨_, rfl, kind_atom⟩
      · exact ⟨_, rfl, by simpa [bitKind] using kind_bit (t := t) (n := n) 0 (by omega)⟩
      · exact ⟨_, rfl, by simpa [bitKind] using kind_bit (t := t) (n := n) 1 (by omega)⟩
      · exact ⟨_, rfl, by simpa [bitKind] using kind_bit (t := t) (n := n) 4 (by omega)⟩
      · exact ⟨_, rfl, kind_fun⟩
      · exact ⟨_, rfl, by simpa [bitKind] using kind_bit (t := t) (n := n) 3 (by omega)⟩
      · exact kind_list hm
      · exact ⟨_, rfl, kind_map⟩
      · exact ⟨_, rfl, by simpa [bitKind] using kind_bit (t := t) (n := n) 5 (by omega)⟩
      · exact ⟨_, rfl, by simpa [bitKind] using kind_bit (t := t) (n := n) 6 (by omega)⟩
      · exact ⟨_, rfl, by simpa [bitKind] using kind_bit (t := t) (n := n) 7 (by omega)⟩
      · exact ⟨_, rfl, kind_tuple⟩

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.Nest
    open Lynx Lynx.Term BddProofs

    section
    variable {t : Term} {n : Nat}

    /-- Key types of atoms and kinds: the atom points of the atoms `P`, or all of them with the atom kind, and points of
    the other kinds `ks`. -/
    structure KeyInv (t : Term) (n : Nat) (Y : List (Term × Term)) (P : Term → Prop) (ks : List Term) : Prop where
      de : DE (level t n).E (.map Y)
      atoms : ∀ q, denD (.map Y) (aPt (t := t) (n := n) q) ↔ P q ∨ .atom "atom" ∈ ks
      kinds : ∀ v : PN t n, denD (.map Y) v → v.1.1 ≠ "atom" → .atom (ptKind v) ∈ ks
      wit : ∀ s, .atom s ∈ ks → s ≠ "atom" → ∃ v : PN t n, denD (.map Y) v ∧ ptKind v = s

    theorem KeyInv.congr {Y : List (Term × Term)} {P : Term → Prop} {ks ks' : List Term} (h : KeyInv t n Y P ks)
        (e : ∀ x, x ∈ ks ↔ x ∈ ks') : KeyInv t n Y P ks' :=
      ⟨h.de, fun q => by rw [h.atoms, e], fun v hv nv => (e _).mp (h.kinds v hv nv),
        fun s ms ns => h.wit s ((e _).mpr ms) ns⟩

    /-- `kinds_type/2` unites the key types of kinds. -/
    theorem kinds_type_run {m : Nat} (hm : (level t n).K + 23 ≤ m) : ∀ (kinds : List Term),
        (∀ d ∈ kinds, ∃ s ∈ domainKinds, d = .atom s) → ∀ (Y : List (Term × Term)) (P : Term → Prop) (ks : List Term),
        KeyInv t n Y P ks → ∃ Y', Elixir.STTDescrProofsTest.«kinds_type/2» (D m) (Term.list kinds) (.map Y) = .ok (.map Y') ∧
          KeyInv t n Y' P (kinds ++ ks)
      | [], _, Y, P, ks, h => ⟨Y, by simp [Elixir.STTDescrProofsTest.«kinds_type/2»], by simpa using h⟩
      | d :: rest, hd, Y, P, ks, h => by
        obtain ⟨s, ms, rfl⟩ := hd _ List.mem_cons_self
        obtain ⟨T, rT, kT⟩ := kind_run ms hm
        obtain ⟨U, rU, dU, sU⟩ := union_map kT.de h.de hm
        have inT : ∀ q, denD (.map T) (aPt (t := t) (n := n) q) ↔ s = "atom" := fun q => by
          constructor
          · intro hq
            rcases kT.pts _ hq with ⟨e, -⟩ | ⟨ne, -⟩
            · exact e
            · exact absurd rfl ne
          · intro e; exact kT.atoms e q
        have inv : KeyInv t n U P (.atom s :: ks) := by
          refine ⟨dU, fun q => ?_, fun v hv nv => ?_, fun s' ms' ns' => ?_⟩
          · rw [sU, inT, h.atoms]
            simp only [List.mem_cons, Term.atom.injEq]
            constructor
            · rintro (e | h' | h')
              · exact Or.inr (Or.inl e.symm)
              · exact Or.inl h'
              · exact Or.inr (Or.inr h')
            · rintro (h' | e | h')
              · exact Or.inr (Or.inl h')
              · exact Or.inl e.symm
              · exact Or.inr (Or.inr h')
          · rcases (sU v).mp hv with h' | h'
            · rcases kT.pts v h' with ⟨-, e⟩ | ⟨-, pk⟩
              · exact absurd e nv
              · rw [pk]; exact List.mem_cons_self
            · exact List.mem_cons_of_mem _ (h.kinds v h' nv)
          · rcases List.mem_cons.mp ms' with e | m'
            · obtain rfl : s' = s := Term.atom.inj e
              obtain ⟨v, hv, pv⟩ := kT.wit ns'
              exact ⟨v, (sU v).mpr (Or.inl hv), pv⟩
            · obtain ⟨v, hv, pv⟩ := h.wit s' m' ns'
              exact ⟨v, (sU v).mpr (Or.inr hv), pv⟩
        obtain ⟨Y', r', h'⟩ := kinds_type_run hm rest (fun d md => hd d (List.mem_cons_of_mem _ md)) U P _ inv
        refine ⟨Y', ?_, h'.congr fun x => ?_⟩
        · simp only [Term.list] at r' ⊢
          simp [Elixir.STTDescrProofsTest.«kinds_type/2», rT, rU, r']
        · simp only [List.mem_append, List.mem_cons, List.cons_append, or_left_comm]

    theorem lookup_nil_pairs (atoms : List Term) (ha : ∀ a ∈ atoms, ∃ s, a = .atom s) (q : Term) :
        (mapLookup (atoms.map (·, Term.nil)) q).isSome = Bool.true ↔ q ∈ atoms := by
      induction atoms with
      | nil => simp [mapLookup]
      | cons a rest ih =>
        obtain ⟨s, rfl⟩ := ha a List.mem_cons_self
        have ih := ih fun a m => ha a (List.mem_cons_of_mem _ m)
        rw [List.map_cons]
        by_cases e : compareExact (fuel q (.atom s)) q (.atom s) = .eq
        · obtain rfl := (compareExact_eq_atom _ _).mp e
          simp [mapLookup]
        · have ne : q ≠ .atom s := fun h => e ((compareExact_eq_atom _ _).mpr h)
          have hl : mapLookup ((Term.atom s, Term.nil) :: rest.map (·, Term.nil)) q = mapLookup (rest.map (·, Term.nil)) q := by
            simp [mapLookup, e]
          rw [hl, ih]
          simp [ne]

    /-- `key_type/2` on atoms and kinds. -/
    theorem key_type_run (atoms kinds : List Term) (ha : ∀ a ∈ atoms, ∃ s, a = .atom s)
        (hk : ∀ d ∈ kinds, ∃ s ∈ domainKinds, d = .atom s) {m : Nat} (hm : (level t n).K + 23 ≤ m) :
        ∃ Y, Elixir.STTDescrProofsTest.«key_type/2» (D m) (Term.list atoms) (Term.list kinds) = .ok (.map Y) ∧
          KeyInv t n Y (· ∈ atoms) kinds := by
      cases atoms with
      | nil =>
        have base : KeyInv t n [] (· ∈ ([] : List Term)) [] :=
          ⟨Or.inr ⟨[], rfl, fun q h => by simp [mapLookup] at h, fun name w h => by simp [mapLookup] at h⟩,
            fun q => by simp [denD_map, mapLookup, dn_none], fun v hv => by simp [denD_map, mapLookup, dn_none] at hv,
            fun s ms => by simp at ms⟩
        obtain ⟨Y, rY, hY⟩ := kinds_type_run hm kinds hk [] _ [] base
        exact ⟨Y, by simpa [Elixir.STTDescrProofsTest.«key_type/2», Elixir.Module.Types.Descr.«none/0», Term.list] using rY,
          by simpa using hY⟩
      | cons a rest =>
        let S := (a :: rest).map (·, Term.nil)
        have hS : ∀ q, (mapLookup S q).isSome = Bool.true ↔ q ∈ a :: rest := lookup_nil_pairs _ ha
        have set : Erlang.sets.elements? (.map S) = some S := by
          simp only [Erlang.sets.elements?, List.all_eq_true]
          rw [ite_eq_left_iff.mpr fun h => absurd ?_ h]
          intro e me
          obtain ⟨b, -, rfl⟩ := List.mem_map.mp (mem_of_mem_mapEntries me)
          rfl
        have base : KeyInv t n [(.atom "atom", .tuple #[.atom "union", .map S])] (· ∈ a :: rest) [] := by
          refine ⟨single_de (by simp [names]) (Or.inr (Or.inl ⟨rfl, ⟨Bool.true, S, rfl, set⟩, a, ?_⟩)), fun q => ?_,
            fun v hv nv => absurd ((denD_single _ _ v).mp hv).1 nv, fun s ms => by simp at ms⟩
          · simp [amemV, (hS a).mpr List.mem_cons_self]
          · rw [denD_single]
            simp [aPt, dn_atom, amemV, hS q]
        obtain ⟨Y, rY, hY⟩ := kinds_type_run hm kinds hk _ _ [] base
        refine ⟨Y, ?_, by simpa using hY⟩
        have pl : Term.properList? (Term.cons a (Term.list rest)) = some (a :: rest) := Term.properList?_list (a :: rest)
        simp only [Term.list] at pl ⊢
        simp [Elixir.STTDescrProofsTest.«key_type/2», Elixir.Module.Types.Descr.«atom/1»,
          Elixir.Module.Types.Descr.«atom_new/1», Erlang.erlang.«is_list/1», Erlang.sets.«from_list/2»,
          Erlang.sets.«from_list/1», pl]
        exact rY

    /-- The keys of the given atoms and kinds. -/
    def KeysOf (atoms kinds : List Term) : MKey → Prop
      | .atom s => .atom s ∈ atoms ∨ .atom "atom" ∈ kinds
      | .dom k _ => .atom (domKind k) ∈ kinds

    /-- `map_split_keys_and_domains/1` on the key type of atoms and kinds selects their keys. -/
    theorem key_split (atoms kinds : List Term) (ha : ∀ a ∈ atoms, ∃ s, a = .atom s)
        (hk : ∀ d ∈ kinds, ∃ s ∈ domainKinds, d = .atom s) {m : Nat} (hm : (level t n).K + 24 ≤ m) :
        ∃ Y rs neg ds, Elixir.STTDescrProofsTest.«key_type/2» (D m) (Term.list atoms) (Term.list kinds) = .ok (.map Y) ∧
          Elixir.Module.Types.Descr.«map_split_keys_and_domains/1» (D m) (.map Y) = .ok (splitT rs neg ds) ∧
          SplitOk rs neg ds ∧ ∀ κ, SplitKey rs neg ds κ ↔ KeysOf atoms kinds κ := by
      obtain ⟨Y, rY, hY⟩ := key_type_run (t := t) (n := n) atoms kinds ha hk (m := m) (by omega)
      obtain ⟨k, rfl⟩ : ∃ k, m = k + 1 := ⟨m - 1, by omega⟩
      have hU : ∀ S, mapLookup Y (.atom "atom") = some (.tuple #[.atom "union", .map S]) →
          ∀ q, (mapLookup S q).isSome → ∃ s, q = .atom s := by
        intro S hS q hq
        have mem : ∀ q, (mapLookup S q).isSome = Bool.true → q ∈ atoms ∨ .atom "atom" ∈ kinds := fun q hq =>
          (hY.atoms q).mp ((denD_aPt q).mpr (by rw [hS]; simpa [amemV] using hq))
        rcases mem q hq with h | h
        · exact ha q h
        · obtain ⟨c, hc⟩ := fresh_str (keyStrs S)
          have := (denD_aPt (t := t) (n := n) (Y := Y) (.atom c)).mp ((hY.atoms _).mpr (Or.inr h))
          rw [hS] at this
          simp [amemV, lookup_fresh' hc] at this
      obtain ⟨rs, neg, ds, rs', ok, sa, sd⟩ := split_map hY.de hU (m := k) (by omega)
      refine ⟨Y, rs, neg, ds, rY, rs', ok, fun κ => ?_⟩
      cases κ with
      | atom s => rw [sa, hY.atoms]; rfl
      | dom k' i =>
        rw [sd]
        constructor
        · rintro ⟨v, hv, pv⟩
          by_cases va : v.1.1 = "atom"
          · exact absurd (by simpa [ptKind, va] using pv.symm) (domKind_ne_atom k')
          · show .atom (domKind k') ∈ kinds
            rw [← pv]; exact hY.kinds v hv va
        · intro h
          exact hY.wit _ h (domKind_ne_atom k')

    end

    end Elixir.STTDescrProofsTest.Nest
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.USort
    open Lynx

    /-! Abstract layer for `lists:usort/1` and `lists:ukeysort/2`: lists are compared by the
    first element of each key (`lk`), and the merge states of OTP's merge sorts are described by
    which sources remain and how they relate to the accumulated output. -/

    theorem c_swap {a b : Term} : Term.compare (Term.fuel b a) b a = (Term.compare (Term.fuel a b) a b).swap :=
      Lynx.Term.compare_swap b a

    theorem c_eq_symm {a b : Term} (h : Term.compare (Term.fuel a b) a b = .eq) : Term.compare (Term.fuel b a) b a = .eq :=
      Lynx.Term.compare_eq_symm h

    theorem c_gt_of_lt {a b : Term} (h : Term.compare (Term.fuel a b) a b = .lt) : Term.compare (Term.fuel b a) b a = .gt :=
      Lynx.Term.compare_gt_of_lt h

    theorem c_lt_of_gt {a b : Term} (h : Term.compare (Term.fuel a b) a b = .gt) : Term.compare (Term.fuel b a) b a = .lt :=
      Lynx.Term.compare_lt_of_gt h

    theorem c_lt_trans {a b c : Term} (h₁ : Term.compare (Term.fuel a b) a b = .lt) (h₂ : Term.compare (Term.fuel b c) b c = .lt) :
        Term.compare (Term.fuel a c) a c = .lt := Lynx.Term.compare_lt_trans h₁ h₂

    theorem c_eq_trans {a b c : Term} (h₁ : Term.compare (Term.fuel a b) a b = .eq) (h₂ : Term.compare (Term.fuel b c) b c = .eq) :
        Term.compare (Term.fuel a c) a c = .eq := Lynx.Term.compare_eq_trans h₁ h₂

    theorem c_lt_eq {a b c : Term} (h₁ : Term.compare (Term.fuel a b) a b = .lt) (h₂ : Term.compare (Term.fuel b c) b c = .eq) :
        Term.compare (Term.fuel a c) a c = .lt := Lynx.Term.compare_lt_of_lt_of_eq h₁ h₂

    theorem c_eq_lt {a b c : Term} (h₁ : Term.compare (Term.fuel a b) a b = .eq) (h₂ : Term.compare (Term.fuel b c) b c = .lt) :
        Term.compare (Term.fuel a c) a c = .lt := Lynx.Term.compare_lt_of_eq_of_lt h₁ h₂

    theorem c_lt_le {a b c : Term} (h₁ : Term.compare (Term.fuel a b) a b = .lt) (h₂ : (Term.compare (Term.fuel b c) b c).isLE) :
        Term.compare (Term.fuel a c) a c = .lt := Lynx.Term.compare_lt_of_lt_of_isLE h₁ h₂

    theorem c_le_lt {a b c : Term} (h₁ : (Term.compare (Term.fuel a b) a b).isLE) (h₂ : Term.compare (Term.fuel b c) b c = .lt) :
        Term.compare (Term.fuel a c) a c = .lt := Lynx.Term.compare_lt_of_isLE_of_lt h₁ h₂

    theorem c_le_iff {a b : Term} : (Term.compare (Term.fuel a b) a b).isLE ↔ Term.compare (Term.fuel a b) a b ≠ .gt := by
      cases Term.compare (Term.fuel a b) a b <;> simp

    theorem c_eq_ne_lt {a b : Term} (h : Term.compare (Term.fuel a b) a b = .eq) : Term.compare (Term.fuel a b) a b ≠ .lt := by
      simp [h]

    section
    variable (κ : Term → Term)

    /-- The first element of `l` whose key compares equal to `s`. -/
    def lk (s : Term) : List Term → Option Term
      | [] => none
      | x :: xs => if Term.compare (Term.fuel (κ x) s) (κ x) s = .eq then some x else lk s xs

    /-- Two lists agree on the first element of every key. -/
    def Eqv (A B : List Term) : Prop := ∀ s, lk κ s A = lk κ s B

    /-- Strictly ascending keys. -/
    def SA (l : List Term) : Prop := l.Pairwise (fun a b => Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) = .lt)

    /-- Strictly descending keys. -/
    def SD (l : List Term) : Prop := l.Pairwise (fun a b => Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) = .gt)

    variable {κ}

    @[simp] theorem lk_nil (s : Term) : lk κ s [] = none := rfl

    theorem lk_cons (s x : Term) (xs : List Term) :
        lk κ s (x :: xs) = if Term.compare (Term.fuel (κ x) s) (κ x) s = .eq then some x else lk κ s xs := rfl

    theorem lk_append (s : Term) (A B : List Term) : lk κ s (A ++ B) = (lk κ s A).or (lk κ s B) := by
      induction A with
      | nil => rfl
      | cons x xs ih => by_cases h : Term.compare (Term.fuel (κ x) s) (κ x) s = .eq <;> simp [lk_cons, h, ih]

    theorem lk_none {s : Term} {A : List Term} (h : ∀ x ∈ A, Term.compare (Term.fuel (κ x) s) (κ x) s ≠ .eq) :
        lk κ s A = none := by
      induction A with
      | nil => rfl
      | cons x xs ih =>
        simp only [List.mem_cons, forall_eq_or_imp] at h
        simp [lk_cons, h.1, ih h.2]

    theorem lk_some {s y : Term} {A : List Term} (hy : y ∈ A) (h : Term.compare (Term.fuel (κ y) s) (κ y) s = .eq) :
        ∃ z, lk κ s A = some z := by
      induction A with
      | nil => simp at hy
      | cons x xs ih =>
        by_cases hx : Term.compare (Term.fuel (κ x) s) (κ x) s = .eq
        · exact ⟨x, by simp [lk_cons, hx]⟩
        · simp only [List.mem_cons] at hy
          rcases hy with rfl | hy
          · exact absurd h hx
          · simpa [lk_cons, hx] using ih hy

    theorem Eqv.refl (A : List Term) : Eqv κ A A := fun _ => rfl
    theorem Eqv.symm {A B : List Term} (h : Eqv κ A B) : Eqv κ B A := fun s => (h s).symm
    theorem Eqv.trans {A B C : List Term} (h₁ : Eqv κ A B) (h₂ : Eqv κ B C) : Eqv κ A C :=
      fun s => (h₁ s).trans (h₂ s)
    theorem Eqv.append {A A' B B' : List Term} (h₁ : Eqv κ A A') (h₂ : Eqv κ B B') :
        Eqv κ (A ++ B) (A' ++ B') := fun s => by simp [lk_append, h₁ s, h₂ s]
    theorem Eqv.cons (x : Term) {A B : List Term} (h : Eqv κ A B) : Eqv κ (x :: A) (x :: B) :=
      Eqv.append (A := [x]) (A' := [x]) (Eqv.refl _) h

    /-- An element can move to the front past elements of other keys. -/
    theorem eqv_move {x : Term} {A B : List Term} (h : ∀ y ∈ A, Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) ≠ .eq) :
        Eqv κ (A ++ x :: B) (x :: (A ++ B)) := by
      intro s
      by_cases hx : Term.compare (Term.fuel (κ x) s) (κ x) s = .eq
      · have : lk κ s A = none := lk_none fun y hy hys => h y hy (c_eq_trans hys (c_eq_symm hx))
        simp [lk_append, lk_cons, hx, this]
      · simp [lk_append, lk_cons, hx]

    /-- An element shadowed by an earlier one of the same key can be dropped. -/
    theorem eqv_drop {x y : Term} {A B : List Term} (hy : y ∈ A) (h : Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .eq) :
        Eqv κ (A ++ x :: B) (A ++ B) := by
      intro s
      by_cases hx : Term.compare (Term.fuel (κ x) s) (κ x) s = .eq
      · obtain ⟨z, hz⟩ := lk_some hy (c_eq_trans h hx)
        simp [lk_append, hz]
      · simp [lk_append, lk_cons, hx]

    theorem eqv_comm {A B : List Term} (h : ∀ x ∈ A, ∀ y ∈ B, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) ≠ .eq) :
        Eqv κ (A ++ B) (B ++ A) := by
      induction B generalizing A with
      | nil => simpa using Eqv.refl A
      | cons y ys ih =>
        have hy : ∀ x ∈ A, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) ≠ .eq := fun x hx => h x hx y (by simp)
        refine (eqv_move hy).trans (Eqv.cons y (ih fun x hx z hz => h x hx z (by simp [hz]))) |>.trans ?_
        simpa using Eqv.refl (y :: (ys ++ A))

    theorem eqv_reverse {A : List Term} (h : A.Pairwise fun a b => Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) ≠ .eq) :
        Eqv κ A.reverse A := by
      induction A with
      | nil => exact Eqv.refl _
      | cons x xs ih =>
        rw [List.pairwise_cons] at h
        simp only [List.reverse_cons]
        refine (Eqv.append (ih h.2) (Eqv.refl [x])).trans ?_
        have := eqv_comm (κ := κ) (A := xs) (B := [x])
          (fun y hy z hz => by simp at hz; subst hz; intro e; exact h.1 y hy (c_eq_symm e))
        simpa using this

    theorem SA.ne {l : List Term} (h : SA κ l) : l.Pairwise fun a b => Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) ≠ .eq :=
      h.imp fun e => by simp [e]

    theorem SD.ne {l : List Term} (h : SD κ l) : l.Pairwise fun a b => Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) ≠ .eq :=
      h.imp fun e => by simp [e]

    @[simp] theorem SA_nil : SA κ [] := List.Pairwise.nil
    @[simp] theorem SD_nil : SD κ [] := List.Pairwise.nil

    theorem SA_cons {x : Term} {l : List Term} :
        SA κ (x :: l) ↔ (∀ y ∈ l, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt) ∧ SA κ l := List.pairwise_cons

    theorem SD_cons {x : Term} {l : List Term} :
        SD κ (x :: l) ↔ (∀ y ∈ l, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .gt) ∧ SD κ l := List.pairwise_cons

    theorem SA_reverse {l : List Term} : SA κ l.reverse ↔ SD κ l := by
      simp only [SA, SD, List.pairwise_reverse]
      exact ⟨fun h => h.imp c_gt_of_lt, fun h => h.imp c_lt_of_gt⟩

    theorem SD_reverse {l : List Term} : SD κ l.reverse ↔ SA κ l := by
      simp only [SA, SD, List.pairwise_reverse]
      exact ⟨fun h => h.imp c_lt_of_gt, fun h => h.imp c_gt_of_lt⟩

    /-- Every element of a strictly ascending list after a lower bound of its head. -/
    theorem SA.lt_all {x b : Term} {l : List Term} (s : SA κ (b :: l))
        (h : Term.compare (Term.fuel (κ x) (κ b)) (κ x) (κ b) = .lt) : ∀ y ∈ b :: l, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt := by
      intro y hy
      simp only [List.mem_cons] at hy
      rcases hy with rfl | hy
      · exact h
      · exact c_lt_trans h ((SA_cons.1 s).1 y hy)

    theorem SA.le_all {x b : Term} {l : List Term} (s : SA κ (b :: l))
        (h : (Term.compare (Term.fuel (κ x) (κ b)) (κ x) (κ b)).isLE) : ∀ y ∈ b :: l, (Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y)).isLE := by
      intro y hy
      simp only [List.mem_cons] at hy
      rcases hy with rfl | hy
      · exact h
      · have := c_le_lt h ((SA_cons.1 s).1 y hy); simp [this]

    theorem SD.gt_all {x b : Term} {l : List Term} (s : SD κ (b :: l))
        (h : Term.compare (Term.fuel (κ x) (κ b)) (κ x) (κ b) = .gt) : ∀ y ∈ b :: l, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .gt := by
      intro y hy
      simp only [List.mem_cons] at hy
      rcases hy with rfl | hy
      · exact h
      · exact c_gt_of_lt (c_lt_trans (c_lt_of_gt ((SD_cons.1 s).1 y hy)) (c_lt_of_gt h))

    theorem SD.ge_all {x b : Term} {l : List Term} (s : SD κ (b :: l))
        (h : Term.compare (Term.fuel (κ x) (κ b)) (κ x) (κ b) ≠ .lt) : ∀ y ∈ b :: l, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) ≠ .lt := by
      intro y hy
      simp only [List.mem_cons] at hy
      rcases hy with rfl | hy
      · exact h
      · exact fun e => h (c_lt_trans e (c_lt_of_gt ((SD_cons.1 s).1 y hy)))

    end

    end Elixir.STTDescrProofsTest.USort
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.USort
    open Lynx

    section
    variable (κ : Term → Term) (Kd : Term → Prop)

    /-! Ascending sources merged into a descending accumulator (`ukeymerge*`, `umerge*`). -/

    /-- Every key of the accumulator is below `x`. -/
    def Above (M : List Term) (x : Term) : Prop := ∀ m ∈ M, Term.compare (Term.fuel (κ m) (κ x)) (κ m) (κ x) = .lt

    /-- `x` is above the accumulator or a duplicate of its head. -/
    def Up (M : List Term) (x : Term) : Prop :=
      Above κ M x ∨ ∃ m M', M = m :: M' ∧ Term.compare (Term.fuel (κ x) (κ m)) (κ x) (κ m) = .eq

    /-- The tracked head key of the accumulator; when it is empty no source key matches it. -/
    def HdOK (M : List Term) (h : Term) (S : List Term) : Prop :=
      match M with
      | [] => ∀ x ∈ S, Term.compare (Term.fuel (κ x) h) (κ x) h ≠ .eq
      | m :: _ => Term.compare (Term.fuel h (κ m)) h (κ m) = .eq

    structure Pre (M A B C : List Term) : Prop where
      sm : SD κ M
      sa : SA κ A
      sb : SA κ B
      sc : SA κ C
      ka : ∀ x ∈ A, Kd x
      kb : ∀ x ∈ B, Kd x
      kc : ∀ x ∈ C, Kd x
      ua : ∀ x ∈ A, Above κ M x
      ub : ∀ x ∈ B, Up κ M x
      uc : ∀ x ∈ C, Up κ M x

    /-- A descending result with the contents of the state, earlier sources first. -/
    def Res (M A B C R : List Term) : Prop := SD κ R ∧ Eqv κ R (M ++ A ++ B ++ C)

    variable {κ Kd}

    theorem above_lt {M : List Term} {x y : Term} (hx : Above κ M x)
        (h : Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt) : Above κ M y :=
      fun m hm => c_lt_trans (hx m hm) h

    theorem above_cons {M : List Term} {x y : Term} (hx : Above κ M x)
        (h : Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt) : Above κ (x :: M) y := by
      intro m hm
      simp only [List.mem_cons] at hm
      rcases hm with rfl | hm
      · exact h
      · exact above_lt hx h m hm

    theorem up_cons {M : List Term} {x y : Term} (hx : Above κ M x)
        (h : (Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y)).isLE) : Up κ (x :: M) y := by
      cases e : Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y)
      · exact Or.inl (above_cons hx e)
      · exact Or.inr ⟨x, M, rfl, c_eq_symm e⟩
      · simp [e] at h

    theorem up_of_above {M : List Term} {x : Term} (h : Above κ M x) : Up κ M x := Or.inl h

    /-- A tracked head decides whether a source element duplicates the accumulator head. -/
    theorem up_split {M S : List Term} {h x : Term} (hd : HdOK κ M h S) (hx : x ∈ S)
        (u : Up κ M x) :
        (Term.compare (Term.fuel (κ x) h) (κ x) h = .eq → ∃ m M', M = m :: M' ∧ Term.compare (Term.fuel (κ x) (κ m)) (κ x) (κ m) = .eq) ∧
        (Term.compare (Term.fuel (κ x) h) (κ x) h ≠ .eq → Above κ M x) := by
      cases M with
      | nil => exact ⟨fun e => absurd e (hd x hx), fun _ m hm => by simp at hm⟩
      | cons m M' =>
        simp only [HdOK] at hd
        refine ⟨fun e => ⟨m, M', rfl, c_eq_trans e hd⟩, fun ne => ?_⟩
        rcases u with u | ⟨m', M'', e, u⟩
        · exact u
        · cases e; exact absurd (c_eq_trans u (c_eq_symm hd)) ne

    theorem hd_self {M S : List Term} {x : Term} : HdOK κ (x :: M) (κ x) S := by
      simp [HdOK]

    theorem eqv_mid {M A : List Term} {x : Term} (hm : Above κ M x)
        (ha : ∀ y ∈ A, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt) (B' : List Term) :
        Eqv κ (x :: M ++ A ++ B') (M ++ A ++ x :: B') := by
      have := eqv_move (κ := κ) (x := x) (A := M ++ A) (B := B') (by
        intro y hy e
        simp only [List.mem_append] at hy
        rcases hy with hy | hy
        · exact absurd (hm y hy) (by simp [e])
        · have := ha y hy; rw [c_swap, e] at this; simp at this)
      simpa using this.symm

    theorem pushA {M A B C : List Term} {x : Term} (p : Pre κ Kd M (x :: A) B C)
        (hb : ∀ y ∈ B.head?, (Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y)).isLE)
        (hc : ∀ y ∈ C.head?, (Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y)).isLE) :
        Pre κ Kd (x :: M) A B C ∧ ∀ R, Res κ (x :: M) A B C R → Res κ M (x :: A) B C R := by
      have hx : Above κ M x := p.ua x (by simp)
      have sa := SA_cons.1 p.sa
      have le_all : ∀ {S : List Term}, SA κ S → (∀ y ∈ S.head?, (Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y)).isLE) →
          ∀ y ∈ S, (Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y)).isLE := by
        intro S s h y hy
        cases S with
        | nil => simp at hy
        | cons b S => exact SA.le_all s (h b (by simp)) y hy
      refine ⟨⟨SD_cons.2 ⟨fun m hm => c_gt_of_lt (hx m hm), p.sm⟩, sa.2, p.sb, p.sc,
        fun y hy => p.ka y (by simp [hy]), p.kb, p.kc,
        fun y hy => above_cons hx (sa.1 y hy),
        fun y hy => up_cons hx (le_all p.sb hb y hy),
        fun y hy => up_cons hx (le_all p.sc hc y hy)⟩, ?_⟩
      rintro R ⟨sr, er⟩
      refine ⟨sr, er.trans ?_⟩
      simpa using eqv_mid (A := []) hx (fun _ h => by simp at h) (A ++ B ++ C)

    theorem pushB {M A B C : List Term} {x : Term} (p : Pre κ Kd M A (x :: B) C) (hx : Above κ M x)
        (ha : ∀ y ∈ A.head?, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt)
        (hc : ∀ y ∈ C.head?, (Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y)).isLE) :
        Pre κ Kd (x :: M) A B C ∧ ∀ R, Res κ (x :: M) A B C R → Res κ M A (x :: B) C R := by
      have sb := SA_cons.1 p.sb
      have lt_a : ∀ y ∈ A, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt := by
        intro y hy
        cases A with
        | nil => simp at hy
        | cons b A => exact SA.lt_all p.sa (ha b (by simp)) y hy
      have le_c : ∀ y ∈ C, (Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y)).isLE := by
        intro y hy
        cases C with
        | nil => simp at hy
        | cons b C => exact SA.le_all p.sc (hc b (by simp)) y hy
      refine ⟨⟨SD_cons.2 ⟨fun m hm => c_gt_of_lt (hx m hm), p.sm⟩, p.sa, sb.2, p.sc,
        p.ka, fun y hy => p.kb y (by simp [hy]), p.kc,
        fun y hy => above_cons hx (lt_a y hy),
        fun y hy => up_of_above (above_cons hx (sb.1 y hy)),
        fun y hy => up_cons hx (le_c y hy)⟩, ?_⟩
      rintro R ⟨sr, er⟩
      refine ⟨sr, er.trans ?_⟩
      simpa using eqv_mid hx lt_a (B ++ C)

    theorem pushC {M A B C : List Term} {x : Term} (p : Pre κ Kd M A B (x :: C)) (hx : Above κ M x)
        (ha : ∀ y ∈ A.head?, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt)
        (hb : ∀ y ∈ B.head?, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt) :
        Pre κ Kd (x :: M) A B C ∧ ∀ R, Res κ (x :: M) A B C R → Res κ M A B (x :: C) R := by
      have sc := SA_cons.1 p.sc
      have lt_all : ∀ {S : List Term}, SA κ S → (∀ y ∈ S.head?, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt) →
          ∀ y ∈ S, Term.compare (Term.fuel (κ x) (κ y)) (κ x) (κ y) = .lt := by
        intro S s h y hy
        cases S with
        | nil => simp at hy
        | cons b S => exact SA.lt_all s (h b (by simp)) y hy
      refine ⟨⟨SD_cons.2 ⟨fun m hm => c_gt_of_lt (hx m hm), p.sm⟩, p.sa, p.sb, sc.2,
        p.ka, p.kb, fun y hy => p.kc y (by simp [hy]),
        fun y hy => above_cons hx (lt_all p.sa ha y hy),
        fun y hy => up_of_above (above_cons hx (lt_all p.sb hb y hy)),
        fun y hy => up_of_above (above_cons hx (sc.1 y hy))⟩, ?_⟩
      rintro R ⟨sr, er⟩
      refine ⟨sr, er.trans ?_⟩
      have := eqv_mid (A := A ++ B) hx (fun y hy => by
        simp only [List.mem_append] at hy
        rcases hy with hy | hy
        · exact lt_all p.sa ha y hy
        · exact lt_all p.sb hb y hy) C
      simpa using this

    theorem dropB {M A B C : List Term} {x : Term} (p : Pre κ Kd M A (x :: B) C)
        (hd : ∃ m M', M = m :: M' ∧ Term.compare (Term.fuel (κ x) (κ m)) (κ x) (κ m) = .eq) :
        Pre κ Kd M A B C ∧ (∀ y ∈ B, Above κ M y) ∧
          ∀ R, Res κ M A B C R → Res κ M A (x :: B) C R := by
      have sb := SA_cons.1 p.sb
      obtain ⟨m, M', rfl, e⟩ := hd
      have ab : ∀ y ∈ B, Above κ (m :: M') y := by
        intro y hy m' hm'
        have hmx : (Term.compare (Term.fuel (κ m') (κ x)) (κ m') (κ x)).isLE := by
          simp only [List.mem_cons] at hm'
          rcases hm' with rfl | hm'
          · simp [c_eq_symm e]
          · have := (SD_cons.1 p.sm).1 m' hm'
            have := c_lt_eq (c_lt_of_gt this) (c_eq_symm e); simp [this]
        exact c_le_lt hmx (sb.1 y hy)
      refine ⟨⟨p.sm, p.sa, sb.2, p.sc, p.ka, fun y hy => p.kb y (by simp [hy]), p.kc, p.ua,
        fun y hy => up_of_above (ab y hy), p.uc⟩, ab, ?_⟩
      rintro R ⟨sr, er⟩
      refine ⟨sr, er.trans ?_⟩
      have := eqv_drop (κ := κ) (A := m :: M' ++ A) (B := B ++ C) (x := x) (y := m) (by simp)
        (c_eq_symm e)
      simpa using this.symm

    theorem dropC {M A B C : List Term} {x : Term} (p : Pre κ Kd M A B (x :: C))
        (hd : ∃ m M', M = m :: M' ∧ Term.compare (Term.fuel (κ x) (κ m)) (κ x) (κ m) = .eq) :
        Pre κ Kd M A B C ∧ (∀ y ∈ C, Above κ M y) ∧
          ∀ R, Res κ M A B C R → Res κ M A B (x :: C) R := by
      have sc := SA_cons.1 p.sc
      obtain ⟨m, M', rfl, e⟩ := hd
      have ac : ∀ y ∈ C, Above κ (m :: M') y := by
        intro y hy m' hm'
        have hmx : (Term.compare (Term.fuel (κ m') (κ x)) (κ m') (κ x)).isLE := by
          simp only [List.mem_cons] at hm'
          rcases hm' with rfl | hm'
          · simp [c_eq_symm e]
          · have := (SD_cons.1 p.sm).1 m' hm'
            have := c_lt_eq (c_lt_of_gt this) (c_eq_symm e); simp [this]
        exact c_le_lt hmx (sc.1 y hy)
      refine ⟨⟨p.sm, p.sa, p.sb, sc.2, p.ka, p.kb, fun y hy => p.kc y (by simp [hy]), p.ua, p.ub,
        fun y hy => up_of_above (ac y hy)⟩, ac, ?_⟩
      rintro R ⟨sr, er⟩
      refine ⟨sr, er.trans ?_⟩
      have := eqv_drop (κ := κ) (A := m :: M' ++ A ++ B) (B := C) (x := x) (y := m) (by simp)
        (c_eq_symm e)
      simpa using this.symm

    theorem res_congr {M A B C M' A' B' C' R : List Term}
        (h : M ++ A ++ B ++ C = M' ++ A' ++ B' ++ C') (r : Res κ M A B C R) : Res κ M' A' B' C' R :=
      ⟨r.1, h ▸ r.2⟩

    /-- Reversing the last source onto the accumulator. -/
    theorem finish {M T : List Term} (sm : SD κ M) (st : SA κ T) (ht : ∀ y ∈ T, Above κ M y) :
        SD κ (T.reverse ++ M) ∧ Eqv κ (T.reverse ++ M) (M ++ T) := by
      refine ⟨?_, ?_⟩
      · simp only [SD, List.pairwise_append]
        refine ⟨SD_reverse.2 st, sm, fun a ha m hm => c_gt_of_lt (ht a (by simpa using ha) m hm)⟩
      · refine (Eqv.append (eqv_reverse st.ne) (Eqv.refl M)).trans (eqv_comm ?_)
        intro a ha m hm e
        have := ht a ha m hm; rw [c_swap, e] at this; simp at this

    /-! Descending sources merged into an ascending accumulator (`rukeymerge*`, `rumerge*`). -/

    variable (κ Kd)

    def Below (M : List Term) (x : Term) : Prop := ∀ m ∈ M, Term.compare (Term.fuel (κ x) (κ m)) (κ x) (κ m) = .lt

    structure PreD (M A B C : List Term) : Prop where
      sm : SA κ M
      sa : SD κ A
      sb : SD κ B
      sc : SD κ C
      ka : ∀ x ∈ A, Kd x
      kb : ∀ x ∈ B, Kd x
      kc : ∀ x ∈ C, Kd x
      ua : ∀ x ∈ A, Below κ M x
      ub : ∀ x ∈ B, Below κ M x
      uc : ∀ x ∈ C, Below κ M x

    def ResD (M A B C R : List Term) : Prop := SA κ R ∧ Eqv κ R (M ++ A ++ B ++ C)

    variable {κ Kd}

    theorem resD_congr {M A B C M' A' B' C' R : List Term}
        (h : M ++ A ++ B ++ C = M' ++ A' ++ B' ++ C') (r : ResD κ M A B C R) : ResD κ M' A' B' C' R :=
      ⟨r.1, h ▸ r.2⟩

    theorem below_cons {M : List Term} {x y : Term} (hx : Below κ M x)
        (h : Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt) : Below κ (x :: M) y := by
      intro m hm
      simp only [List.mem_cons] at hm
      rcases hm with rfl | hm
      · exact h
      · exact c_lt_trans h (hx m hm)

    theorem gt_all {S : List Term} {x : Term} (s : SD κ S)
        (h : ∀ y ∈ S.head?, Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt) : ∀ y ∈ S, Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt := by
      intro y hy
      cases S with
      | nil => simp at hy
      | cons b S =>
        have := SD.gt_all s (x := x) (c_gt_of_lt (h b (by simp))) y hy
        exact c_lt_of_gt this

    theorem eqv_midD {M A : List Term} {x : Term} (hm : Below κ M x)
        (ha : ∀ y ∈ A, Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt) (B' : List Term) :
        Eqv κ (x :: M ++ A ++ B') (M ++ A ++ x :: B') := by
      have := eqv_move (κ := κ) (x := x) (A := M ++ A) (B := B') (by
        intro y hy e
        simp only [List.mem_append] at hy
        rcases hy with hy | hy
        · have := hm y hy; rw [c_swap, e] at this; simp at this
        · exact absurd (ha y hy) (by simp [e]))
      simpa using this.symm

    theorem pushDA {M A B C : List Term} {x : Term} (p : PreD κ Kd M (x :: A) B C)
        (hb : ∀ y ∈ B.head?, Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt)
        (hc : ∀ y ∈ C.head?, Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt) :
        PreD κ Kd (x :: M) A B C ∧ ∀ R, ResD κ (x :: M) A B C R → ResD κ M (x :: A) B C R := by
      have hx := p.ua x (by simp)
      have sa := SD_cons.1 p.sa
      refine ⟨⟨SA_cons.2 ⟨fun m hm => hx m hm, p.sm⟩, sa.2, p.sb, p.sc,
        fun y hy => p.ka y (by simp [hy]), p.kb, p.kc,
        fun y hy => below_cons hx (c_lt_of_gt (sa.1 y hy)),
        fun y hy => below_cons hx (gt_all p.sb hb y hy),
        fun y hy => below_cons hx (gt_all p.sc hc y hy)⟩, ?_⟩
      rintro R ⟨sr, er⟩
      refine ⟨sr, er.trans ?_⟩
      simpa using eqv_midD (A := []) hx (fun _ h => by simp at h) (A ++ B ++ C)

    theorem pushDB {M A B C : List Term} {x : Term} (p : PreD κ Kd M A (x :: B) C)
        (ha : ∀ y ∈ A.head?, Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt)
        (hc : ∀ y ∈ C.head?, Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt) :
        PreD κ Kd (x :: M) A B C ∧ ∀ R, ResD κ (x :: M) A B C R → ResD κ M A (x :: B) C R := by
      have hx := p.ub x (by simp)
      have sb := SD_cons.1 p.sb
      have la := gt_all p.sa ha
      refine ⟨⟨SA_cons.2 ⟨fun m hm => hx m hm, p.sm⟩, p.sa, sb.2, p.sc,
        p.ka, fun y hy => p.kb y (by simp [hy]), p.kc,
        fun y hy => below_cons hx (la y hy),
        fun y hy => below_cons hx (c_lt_of_gt (sb.1 y hy)),
        fun y hy => below_cons hx (gt_all p.sc hc y hy)⟩, ?_⟩
      rintro R ⟨sr, er⟩
      refine ⟨sr, er.trans ?_⟩
      simpa using eqv_midD hx la (B ++ C)

    theorem pushDC {M A B C : List Term} {x : Term} (p : PreD κ Kd M A B (x :: C))
        (ha : ∀ y ∈ A.head?, Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt)
        (hb : ∀ y ∈ B.head?, Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt) :
        PreD κ Kd (x :: M) A B C ∧ ∀ R, ResD κ (x :: M) A B C R → ResD κ M A B (x :: C) R := by
      have hx := p.uc x (by simp)
      have sc := SD_cons.1 p.sc
      have la := gt_all p.sa ha
      have lb := gt_all p.sb hb
      refine ⟨⟨SA_cons.2 ⟨fun m hm => hx m hm, p.sm⟩, p.sa, p.sb, sc.2,
        p.ka, p.kb, fun y hy => p.kc y (by simp [hy]),
        fun y hy => below_cons hx (la y hy),
        fun y hy => below_cons hx (lb y hy),
        fun y hy => below_cons hx (c_lt_of_gt (sc.1 y hy))⟩, ?_⟩
      rintro R ⟨sr, er⟩
      refine ⟨sr, er.trans ?_⟩
      have := eqv_midD (A := A ++ B) hx (fun y hy => by
        simp only [List.mem_append] at hy
        rcases hy with hy | hy
        · exact la y hy
        · exact lb y hy) C
      simpa using this

    /-- A source head equal to the head of an earlier source is shadowed. -/
    theorem dropDB {M A B C : List Term} {x a : Term} (p : PreD κ Kd M A (x :: B) C)
        (ha : a ∈ A) (e : Term.compare (Term.fuel (κ a) (κ x)) (κ a) (κ x) = .eq) :
        PreD κ Kd M A B C ∧ ∀ R, ResD κ M A B C R → ResD κ M A (x :: B) C R := by
      refine ⟨⟨p.sm, p.sa, (SD_cons.1 p.sb).2, p.sc, p.ka, fun y hy => p.kb y (by simp [hy]), p.kc,
        p.ua, fun y hy => p.ub y (by simp [hy]), p.uc⟩, ?_⟩
      rintro R ⟨sr, er⟩
      refine ⟨sr, er.trans ?_⟩
      have := eqv_drop (κ := κ) (A := M ++ A) (B := B ++ C) (x := x) (y := a) (by simp [ha]) e
      simpa using this.symm

    theorem dropDC {M A B C : List Term} {x a : Term} (p : PreD κ Kd M A B (x :: C))
        (ha : a ∈ A ++ B) (e : Term.compare (Term.fuel (κ a) (κ x)) (κ a) (κ x) = .eq) :
        PreD κ Kd M A B C ∧ ∀ R, ResD κ M A B C R → ResD κ M A B (x :: C) R := by
      refine ⟨⟨p.sm, p.sa, p.sb, (SD_cons.1 p.sc).2, p.ka, p.kb, fun y hy => p.kc y (by simp [hy]),
        p.ua, p.ub, fun y hy => p.uc y (by simp [hy])⟩, ?_⟩
      rintro R ⟨sr, er⟩
      refine ⟨sr, er.trans ?_⟩
      have := eqv_drop (κ := κ) (A := M ++ A ++ B) (B := C) (x := x) (y := a)
        (by simp only [List.mem_append] at ha ⊢; rcases ha with ha | ha <;> simp [ha]) e
      simpa using this.symm

    theorem finishD {M T : List Term} (sm : SA κ M) (st : SD κ T) (ht : ∀ y ∈ T, Below κ M y) :
        SA κ (T.reverse ++ M) ∧ Eqv κ (T.reverse ++ M) (M ++ T) := by
      refine ⟨?_, ?_⟩
      · simp only [SA, List.pairwise_append]
        refine ⟨SA_reverse.2 st, sm, fun a ha m hm => ht a (by simpa using ha) m hm⟩
      · refine (Eqv.append (eqv_reverse st.ne) (Eqv.refl M)).trans (eqv_comm ?_)
        intro a ha m hm e
        exact absurd (ht a ha m hm) (by simp [e])

    end

    end Elixir.STTDescrProofsTest.USort
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.USort
    open Lynx

    theorem g_if {α : Type} (p : Prop) [Decidable p] (body next : Unit → Except Exception α) :
        Lynx.Except.guard (.ok (if p then Term.atom "true" else Term.atom "false")) body next =
          if p then body () else next () := by
      by_cases h : p <;> simp [h]

    theorem eq_ok (a b : Term) : Erlang.erlang.«==/2» a b =
        .ok (if Term.compare (Term.fuel a b) a b = .eq then Term.atom "true" else Term.atom "false") := by
      simp [Erlang.erlang.«==/2»]

    theorem le_ok (a b : Term) : Erlang.erlang.«=</2» a b =
        .ok (if (Term.compare (Term.fuel a b) a b).isLE = true then Term.atom "true" else Term.atom "false") := by
      simp [Erlang.erlang.«=</2»]

    theorem lt_ok (a b : Term) : Erlang.erlang.«</2» a b =
        .ok (if (Term.compare (Term.fuel a b) a b).isLT = true then Term.atom "true" else Term.atom "false") := by
      simp [Erlang.erlang.«</2»]

    theorem gt_ok (a b : Term) : Erlang.erlang.«>/2» a b =
        .ok (if (Term.compare (Term.fuel a b) a b).isGT = true then Term.atom "true" else Term.atom "false") := by
      simp [Erlang.erlang.«>/2»]

    /-- Keyed elements of `ukeysort/2`: `element/2` yields the key, which never equals a cons. -/
    def KdK (I : Term) (κ : Term → Term) (x : Term) : Prop :=
      Erlang.erlang.«element/2» I x = .ok (κ x) ∧ ∀ a b, Term.compare (Term.fuel (κ x) (.cons a b)) (κ x) (.cons a b) ≠ .eq

    theorem rev2 (l : List Term) : ∀ acc : List Term,
        Erlang.lists.«reverse/2» (Term.list l) (Term.list acc) = .ok (Term.list (l.reverse ++ acc)) := by
      induction l with
      | nil => intro acc; simp [Erlang.lists.«reverse/2»]
      | cons x xs ih => intro acc; simpa [Term.list, Erlang.lists.«reverse/2»] using ih (x :: acc)

    theorem not_le_lt {a b : Term} (h : ¬(Term.compare (Term.fuel a b) a b).isLE = true) : Term.compare (Term.fuel b a) b a = .lt := by
      cases e : Term.compare (Term.fuel a b) a b
      · simp [e] at h
      · simp [e] at h
      · exact c_lt_of_gt e

    section
    variable {κ : Term → Term} {Kd : Term → Prop}

    /-- The accumulator plus one ascending source, reversed onto it. -/
    theorem res_fin {M T : List Term} (sm : SD κ M) (st : SA κ T) (ht : ∀ y ∈ T, Above κ M y) :
        Res κ M T [] [] (T.reverse ++ M) := by
      obtain ⟨s, e⟩ := finish sm st ht; exact ⟨s, by simpa using e⟩

    theorem resD_fin {M T : List Term} (sm : SA κ M) (st : SD κ T) (ht : ∀ y ∈ T, Below κ M y) :
        ResD κ M T [] [] (T.reverse ++ M) := by
      obtain ⟨s, e⟩ := finishD sm st ht; exact ⟨s, by simpa using e⟩

    end

    section
    variable {I : Term} {κ : Term → Term}

    theorem ukm2 (n : Nat) :
        (∀ T1 T2 M H2 HdM, T1.length + T2.length + 1 ≤ n → Pre κ (KdK I κ) M T1 (H2 :: T2) [] →
          HdOK κ M HdM (H2 :: T2) →
          ∃ R, Erlang.lists.«ukeymerge2_1/7» I (Term.list T1) (κ H2) HdM (Term.list T2) (Term.list M) H2 =
            .ok (Term.list R) ∧ Res κ M T1 (H2 :: T2) [] R) ∧
        (∀ T1 H1 T2 M, T1.length + 1 + T2.length ≤ n → Pre κ (KdK I κ) M (H1 :: T1) T2 [] →
          (∀ y ∈ T2, Above κ M y) →
          ∃ R, Erlang.lists.«ukeymerge2_2/6» I (Term.list T1) (κ H1) H1 (Term.list T2) (Term.list M) =
            .ok (Term.list R) ∧ Res κ M (H1 :: T1) T2 [] R) := by
      induction n with
      | zero => exact ⟨fun _ _ _ _ _ h => by omega, fun _ _ _ _ h => by omega⟩
      | succ n ih =>
      constructor
      · intro T1 T2 M H2 HdM len p hd
        have u2 := up_split hd (by simp) (p.ub H2 (by simp))
        cases T1 with
        | nil =>
          rw [Erlang.lists.«ukeymerge2_1/7».eq_def]
          simp only [eq_ok, g_if]
          by_cases c2 : Term.compare (Term.fuel (κ H2) HdM) (κ H2) HdM = .eq
          · obtain ⟨p', ab, tr⟩ := dropB p (u2.1 c2)
            refine ⟨_, by simp only [c2, ite_true, rev2], tr _ (res_congr (by simp) (res_fin p'.sm p'.sb ab))⟩
          · obtain ⟨p', tr⟩ := pushB p (u2.2 c2) (by simp) (by simp)
            refine ⟨_, by simpa [c2] using rev2 T2 (H2 :: M), tr _ (res_congr (by simp)
              (res_fin p'.sm p'.sb fun y hy => above_cons (u2.2 c2) ((SA_cons.1 p.sb).1 y hy)))⟩
        | cons H1 T1 =>
          have k1 := (p.ka H1 (by simp)).1
          rw [Erlang.lists.«ukeymerge2_1/7».eq_def]
          simp only [k1, Lynx.Except.ok_bind, le_ok, eq_ok, g_if]
          by_cases c1 : (Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)).isLE = true
          · simp only [c1, ↓reduceIte]
            obtain ⟨p', tr⟩ := pushA p (by simpa using c1) (by simp)
            obtain ⟨R, run, res⟩ := ih.1 T1 T2 (H1 :: M) H2 (κ H1) (by simp at len; omega) p' hd_self
            exact ⟨R, by simpa using run, tr R res⟩
          · simp only [c1]
            have c1' := not_le_lt c1
            by_cases c2 : Term.compare (Term.fuel (κ H2) HdM) (κ H2) HdM = .eq
            · simp only [c2, ↓reduceIte]
              obtain ⟨p', ab, tr⟩ := dropB p (u2.1 c2)
              obtain ⟨R, run, res⟩ := ih.2 T1 H1 T2 M (by simp at len; omega) p' ab
              exact ⟨R, run, tr R res⟩
            · simp only [c2, ↓reduceIte]
              obtain ⟨p', tr⟩ := pushB p (u2.2 c2) (by simpa using c1') (by simp)
              obtain ⟨R, run, res⟩ := ih.2 T1 H1 T2 (H2 :: M) (by simp at len; omega) p'
                (fun y hy => above_cons (u2.2 c2) ((SA_cons.1 p.sb).1 y hy))
              exact ⟨R, by simpa using run, tr R res⟩
      · intro T1 H1 T2 M len p ab
        cases T2 with
        | nil =>
          rw [Erlang.lists.«ukeymerge2_2/6».eq_def]
          obtain ⟨p', tr⟩ := pushA p (by simp) (by simp)
          refine ⟨_, by simpa using rev2 T1 (H1 :: M), tr _ (res_fin p'.sm p'.sa p'.ua)⟩
        | cons H2 T2 =>
          have k2 := (p.kb H2 (by simp)).1
          rw [Erlang.lists.«ukeymerge2_2/6».eq_def]
          simp only [k2, Lynx.Except.ok_bind, le_ok, g_if]
          by_cases c1 : (Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)).isLE = true
          · simp only [c1, ↓reduceIte]
            obtain ⟨p', tr⟩ := pushA p (by simpa using c1) (by simp)
            obtain ⟨R, run, res⟩ := ih.1 T1 T2 (H1 :: M) H2 (κ H1) (by simp at len; omega) p' hd_self
            exact ⟨R, by simpa using run, tr R res⟩
          · simp only [c1]
            have hx := ab H2 (by simp)
            obtain ⟨p', tr⟩ := pushB p hx (by simpa using not_le_lt c1) (by simp)
            obtain ⟨R, run, res⟩ := ih.2 T1 H1 T2 (H2 :: M) (by simp at len; omega) p'
              (fun y hy => above_cons hx ((SA_cons.1 p.sb).1 y hy))
            exact ⟨R, by simpa using run, tr R res⟩

    end

    end Elixir.STTDescrProofsTest.USort
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.USort
    open Lynx

    section
    variable {κ : Term → Term} {Kd : Term → Prop}

    theorem hd_sub {M S S' : List Term} {h : Term} (hd : HdOK κ M h S) (sub : ∀ x ∈ S', x ∈ S) :
        HdOK κ M h S' := by
      cases M with
      | nil => exact fun x hx => hd x (sub x hx)
      | cons m M => exact hd

    theorem pre_BC {M B C : List Term} (p : Pre κ Kd M [] B C) (ab : ∀ y ∈ B, Above κ M y) :
        Pre κ Kd M B C [] :=
      ⟨p.sm, p.sb, p.sc, SA_nil, p.kb, p.kc, fun _ h => by simp at h, ab, p.uc, fun _ h => by simp at h⟩

    theorem pre_AC {M A C : List Term} (p : Pre κ Kd M A [] C) : Pre κ Kd M A C [] :=
      ⟨p.sm, p.sa, p.sc, SA_nil, p.ka, p.kc, fun _ h => by simp at h, p.ua, p.uc, fun _ h => by simp at h⟩

    theorem above_all {M B : List Term} {x : Term} (s : SA κ (x :: B)) (hx : Above κ M x) :
        ∀ y ∈ x :: B, Above κ M y := by
      intro y hy
      simp only [List.mem_cons] at hy
      rcases hy with rfl | hy
      · exact hx
      · exact above_lt hx ((SA_cons.1 s).1 y hy)

    theorem above_tail {M B : List Term} {x : Term} (s : SA κ (x :: B)) (hx : Above κ M x) :
        ∀ y ∈ B, Above κ (x :: M) y :=
      fun y hy => above_cons hx ((SA_cons.1 s).1 y hy)

    end

    section
    variable {I : Term} {κ : Term → Term}

    theorem ukm3 (n : Nat) :
        (∀ T1 T2 T3 M H2 H3 HdM D, T1.length + T2.length + T3.length + 2 ≤ n →
          (Pre κ (KdK I κ)) M T1 (H2 :: T2) (H3 :: T3) → HdOK κ M HdM (H2 :: T2 ++ H3 :: T3) →
          ∃ R, Erlang.lists.«ukeymerge3_1/11» I (Term.list T1) D HdM (κ H2) H2 (Term.list T2) (Term.list M)
            (κ H3) H3 (Term.list T3) = .ok (Term.list R) ∧ Res κ M T1 (H2 :: T2) (H3 :: T3) R) ∧
        (∀ H1 T1 T2 H3 T3 M HdM D, T1.length + T2.length + T3.length + 2 ≤ n →
          (Pre κ (KdK I κ)) M (H1 :: T1) T2 (H3 :: T3) → (∀ y ∈ T2, Above κ M y) → HdOK κ M HdM (H3 :: T3) →
          ∃ R, Erlang.lists.«ukeymerge3_2/11» I (κ H1) (Term.list T1) H1 (Term.list T2) HdM D (Term.list M)
            (κ H3) H3 (Term.list T3) = .ok (Term.list R) ∧ Res κ M (H1 :: T1) T2 (H3 :: T3) R) ∧
        (∀ H1 T1 H2 T2 T3 M, T1.length + T2.length + T3.length + 2 ≤ n →
          (Pre κ (KdK I κ)) M (H1 :: T1) (H2 :: T2) T3 → (∀ y ∈ H2 :: T2, Above κ M y) → (∀ y ∈ T3, Above κ M y) →
          (Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)).isLE →
          ∃ R, Erlang.lists.«ukeymerge3_12_3/9» I (κ H1) (Term.list T1) H1 (κ H2) H2 (Term.list T2)
            (Term.list M) (Term.list T3) = .ok (Term.list R) ∧ Res κ M (H1 :: T1) (H2 :: T2) T3 R) ∧
        (∀ H1 T1 H2 T2 T3 M, T1.length + T2.length + T3.length + 2 ≤ n →
          (Pre κ (KdK I κ)) M (H1 :: T1) (H2 :: T2) T3 → (∀ y ∈ H2 :: T2, Above κ M y) → (∀ y ∈ T3, Above κ M y) →
          Term.compare (Term.fuel (κ H2) (κ H1)) (κ H2) (κ H1) = .lt →
          ∃ R, Erlang.lists.«ukeymerge3_21_3/9» I (κ H1) (Term.list T1) H1 (κ H2) H2 (Term.list T2)
            (Term.list M) (Term.list T3) = .ok (Term.list R) ∧ Res κ M (H1 :: T1) (H2 :: T2) T3 R) := by
      induction n with
      | zero => refine ⟨?_, ?_, ?_, ?_⟩ <;> intros <;> omega
      | succ n ih =>
      obtain ⟨ih1, ih2, ih12, ih21⟩ := ih
      have m2 := ukm2 (I := I) (κ := κ) n
      refine ⟨?_, ?_, ?_, ?_⟩
      · -- ukeymerge3_1
        intro T1 T2 T3 M H2 H3 HdM D len p hd
        have u2 := up_split hd (by simp) (p.ub H2 (by simp))
        have u3 := up_split hd (by simp) (p.uc H3 (by simp))
        rw [Erlang.lists.«ukeymerge3_1/11».eq_def]
        cases T1 with
        | nil =>
          simp only [le_ok, eq_ok, g_if]
          by_cases c2 : Term.compare (Term.fuel (κ H2) HdM) (κ H2) HdM = .eq
          · simp only [c2, ↓reduceIte]
            obtain ⟨p', ab, tr⟩ := dropB p (u2.1 c2)
            obtain ⟨R, run, res⟩ := m2.1 T2 T3 M H3 HdM (by simp at len; omega) (pre_BC p' ab)
              (hd_sub hd fun a ha => List.mem_append_right _ ha)
            exact ⟨R, run, tr R (res_congr (by simp) res)⟩
          simp only [c2, ↓reduceIte]
          have a2 := u2.2 c2
          by_cases c23 : (Term.compare (Term.fuel (κ H2) (κ H3)) (κ H2) (κ H3)).isLE = true
          · simp only [c23, ↓reduceIte]
            obtain ⟨p', tr⟩ := pushB p a2 (by simp) (by simpa using c23)
            obtain ⟨R, run, res⟩ := m2.1 T2 T3 (H2 :: M) H3 (κ H2) (by simp at len; omega)
              (pre_BC p' (above_tail p.sb a2)) hd_self
            exact ⟨R, by simpa using run, tr R (res_congr (by simp) res)⟩
          simp only [c23]
          have c32 := not_le_lt c23
          by_cases c3 : Term.compare (Term.fuel (κ H3) HdM) (κ H3) HdM = .eq
          · simp only [c3, ↓reduceIte]
            obtain ⟨p', ac, tr⟩ := dropC p (u3.1 c3)
            obtain ⟨R, run, res⟩ := m2.2 T2 H2 T3 M (by simp at len; omega)
              (pre_BC p' (above_all p.sb a2)) ac
            exact ⟨R, run, tr R (res_congr (by simp) res)⟩
          simp only [c3, ↓reduceIte]
          have a3 := u3.2 c3
          obtain ⟨p', tr⟩ := pushC p a3 (by simp) (by simpa using c32)
          obtain ⟨R, run, res⟩ := m2.2 T2 H2 T3 (H3 :: M) (by simp at len; omega)
            (pre_BC p' (above_all p.sb (above_cons a3 c32))) (above_tail p.sc a3)
          exact ⟨R, by simpa using run, tr R (res_congr (by simp) res)⟩
        | cons H1 T1 =>
          have k1 := (p.ka H1 (by simp)).1
          have a1 := p.ua H1 (by simp)
          simp only [k1, Lynx.Except.ok_bind, le_ok, eq_ok, g_if]
          by_cases c12 : (Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)).isLE = true
          · simp only [c12, ↓reduceIte]
            by_cases c13 : (Term.compare (Term.fuel (κ H1) (κ H3)) (κ H1) (κ H3)).isLE = true
            · simp only [c13, ↓reduceIte]
              obtain ⟨p', tr⟩ := pushA p (by simpa using c12) (by simpa using c13)
              obtain ⟨R, run, res⟩ := ih1 T1 T2 T3 (H1 :: M) H2 H3 (κ H1) D (by simp at len; omega) p' hd_self
              exact ⟨R, by simpa using run, tr R res⟩
            simp only [c13]
            have c31 := not_le_lt c13
            have b2 : ∀ y ∈ H2 :: T2, Above κ M y := above_all p.sb (by
              cases e : Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)
              · exact above_lt a1 e
              · exact fun m hm => c_lt_eq (a1 m hm) e
              · simp [e] at c12)
            by_cases c3 : Term.compare (Term.fuel (κ H3) HdM) (κ H3) HdM = .eq
            · simp only [c3, ↓reduceIte]
              obtain ⟨p', ac, tr⟩ := dropC p (u3.1 c3)
              obtain ⟨R, run, res⟩ := ih12 H1 T1 H2 T2 T3 M (by simp at len; omega) p' b2 ac c12
              exact ⟨R, run, tr R res⟩
            simp only [c3, ↓reduceIte]
            have a3 := u3.2 c3
            obtain ⟨p', tr⟩ := pushC p a3 (by simpa using c31) (by simpa using c_lt_le c31 c12)
            obtain ⟨R, run, res⟩ := ih12 H1 T1 H2 T2 T3 (H3 :: M) (by simp at len; omega) p'
              (above_all p.sb (above_cons a3 (c_lt_le c31 c12))) (above_tail p.sc a3) c12
            exact ⟨R, by simpa using run, tr R res⟩
          simp only [c12]
          have c21 := not_le_lt c12
          by_cases c2 : Term.compare (Term.fuel (κ H2) HdM) (κ H2) HdM = .eq
          · simp only [c2, ↓reduceIte]
            obtain ⟨p', ab, tr⟩ := dropB p (u2.1 c2)
            obtain ⟨R, run, res⟩ := ih2 H1 T1 T2 H3 T3 M HdM (Term.list T2) (by simp at len; omega) p' ab
              (hd_sub hd fun a ha => List.mem_append_right _ ha)
            exact ⟨R, run, tr R res⟩
          simp only [c2, ↓reduceIte]
          have a2 := u2.2 c2
          by_cases c23 : (Term.compare (Term.fuel (κ H2) (κ H3)) (κ H2) (κ H3)).isLE = true
          · simp only [c23, ↓reduceIte]
            obtain ⟨p', tr⟩ := pushB p a2 (by simpa using c21) (by simpa using c23)
            obtain ⟨R, run, res⟩ := ih2 H1 T1 T2 H3 T3 (H2 :: M) (κ H2) (Term.list T2)
              (by simp at len; omega) p' (above_tail p.sb a2) hd_self
            exact ⟨R, by simpa using run, tr R res⟩
          simp only [c23]
          have c32 := not_le_lt c23
          by_cases c3 : Term.compare (Term.fuel (κ H3) HdM) (κ H3) HdM = .eq
          · simp only [c3, ↓reduceIte]
            obtain ⟨p', ac, tr⟩ := dropC p (u3.1 c3)
            obtain ⟨R, run, res⟩ := ih21 H1 T1 H2 T2 T3 M (by simp at len; omega) p'
              (above_all p.sb a2) ac c21
            exact ⟨R, run, tr R res⟩
          simp only [c3, ↓reduceIte]
          have a3 := u3.2 c3
          obtain ⟨p', tr⟩ := pushC p a3 (by simpa using c_lt_trans c32 c21) (by simpa using c32)
          obtain ⟨R, run, res⟩ := ih21 H1 T1 H2 T2 T3 (H3 :: M) (by simp at len; omega) p'
            (above_all p.sb (above_cons a3 c32)) (above_tail p.sc a3) c21
          exact ⟨R, by simpa using run, tr R res⟩
      · -- ukeymerge3_2
        intro H1 T1 T2 H3 T3 M HdM D len p ab hd
        have u3 := up_split hd (by simp) (p.uc H3 (by simp))
        have a1 := p.ua H1 (by simp)
        rw [Erlang.lists.«ukeymerge3_2/11».eq_def]
        cases T2 with
        | nil =>
          simp only [le_ok, eq_ok, g_if]
          by_cases c13 : (Term.compare (Term.fuel (κ H1) (κ H3)) (κ H1) (κ H3)).isLE = true
          · simp only [c13, ↓reduceIte]
            obtain ⟨p', tr⟩ := pushA p (by simp) (by simpa using c13)
            obtain ⟨R, run, res⟩ := m2.1 T1 T3 (H1 :: M) H3 (κ H1) (by simp at len; omega) (pre_AC p') hd_self
            exact ⟨R, by simpa using run, tr R (res_congr (by simp) res)⟩
          simp only [c13]
          have c31 := not_le_lt c13
          by_cases c3 : Term.compare (Term.fuel (κ H3) HdM) (κ H3) HdM = .eq
          · simp only [c3, ↓reduceIte]
            obtain ⟨p', ac, tr⟩ := dropC p (u3.1 c3)
            obtain ⟨R, run, res⟩ := m2.2 T1 H1 T3 M (by simp at len; omega) (pre_AC p') ac
            exact ⟨R, run, tr R (res_congr (by simp) res)⟩
          simp only [c3, ↓reduceIte]
          have a3 := u3.2 c3
          obtain ⟨p', tr⟩ := pushC p a3 (by simpa using c31) (by simp)
          obtain ⟨R, run, res⟩ := m2.2 T1 H1 T3 (H3 :: M) (by simp at len; omega) (pre_AC p')
            (above_tail p.sc a3)
          exact ⟨R, by simpa using run, tr R (res_congr (by simp) res)⟩
        | cons H2 T2 =>
          have k2 := (p.kb H2 (by simp)).1
          have a2 := ab H2 (by simp)
          simp only [k2, Lynx.Except.ok_bind, le_ok, eq_ok, g_if]
          by_cases c12 : (Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)).isLE = true
          · simp only [c12, ↓reduceIte]
            by_cases c13 : (Term.compare (Term.fuel (κ H1) (κ H3)) (κ H1) (κ H3)).isLE = true
            · simp only [c13, ↓reduceIte]
              obtain ⟨p', tr⟩ := pushA p (by simpa using c12) (by simpa using c13)
              obtain ⟨R, run, res⟩ := ih1 T1 T2 T3 (H1 :: M) H2 H3 (κ H1) (Term.list T1)
                (by simp at len; omega) p' hd_self
              exact ⟨R, by simpa using run, tr R res⟩
            simp only [c13]
            have c31 := not_le_lt c13
            by_cases c3 : Term.compare (Term.fuel (κ H3) HdM) (κ H3) HdM = .eq
            · simp only [c3, ↓reduceIte]
              obtain ⟨p', ac, tr⟩ := dropC p (u3.1 c3)
              obtain ⟨R, run, res⟩ := ih12 H1 T1 H2 T2 T3 M (by simp at len; omega) p' ab ac c12
              exact ⟨R, run, tr R res⟩
            simp only [c3, ↓reduceIte]
            have a3 := u3.2 c3
            obtain ⟨p', tr⟩ := pushC p a3 (by simpa using c31) (by simpa using c_lt_le c31 c12)
            obtain ⟨R, run, res⟩ := ih12 H1 T1 H2 T2 T3 (H3 :: M) (by simp at len; omega) p'
              (above_all p.sb (above_cons a3 (c_lt_le c31 c12))) (above_tail p.sc a3) c12
            exact ⟨R, by simpa using run, tr R res⟩
          simp only [c12]
          have c21 := not_le_lt c12
          by_cases c23 : (Term.compare (Term.fuel (κ H2) (κ H3)) (κ H2) (κ H3)).isLE = true
          · simp only [c23, ↓reduceIte]
            obtain ⟨p', tr⟩ := pushB p a2 (by simpa using c21) (by simpa using c23)
            obtain ⟨R, run, res⟩ := ih2 H1 T1 T2 H3 T3 (H2 :: M) (κ H2) D (by simp at len; omega) p'
              (above_tail p.sb a2) hd_self
            exact ⟨R, by simpa using run, tr R res⟩
          simp only [c23]
          have c32 := not_le_lt c23
          by_cases c3 : Term.compare (Term.fuel (κ H3) HdM) (κ H3) HdM = .eq
          · simp only [c3, ↓reduceIte]
            obtain ⟨p', ac, tr⟩ := dropC p (u3.1 c3)
            obtain ⟨R, run, res⟩ := ih21 H1 T1 H2 T2 T3 M (by simp at len; omega) p' ab ac c21
            exact ⟨R, run, tr R res⟩
          simp only [c3, ↓reduceIte]
          have a3 := u3.2 c3
          obtain ⟨p', tr⟩ := pushC p a3 (by simpa using c_lt_trans c32 c21) (by simpa using c32)
          obtain ⟨R, run, res⟩ := ih21 H1 T1 H2 T2 T3 (H3 :: M) (by simp at len; omega) p'
            (above_all p.sb (above_cons a3 c32)) (above_tail p.sc a3) c21
          exact ⟨R, by simpa using run, tr R res⟩
      · -- ukeymerge3_12_3
        intro H1 T1 H2 T2 T3 M len p ab ac c12
        rw [Erlang.lists.«ukeymerge3_12_3/9».eq_def]
        cases T3 with
        | nil =>
          simp only []
          obtain ⟨p', tr⟩ := pushA p (by simpa using c12) (by simp)
          obtain ⟨R, run, res⟩ := m2.1 T1 T2 (H1 :: M) H2 (κ H1) (by simp at len; omega) p' hd_self
          exact ⟨R, by simpa using run, tr R res⟩
        | cons H3 T3 =>
          have k3 := (p.kc H3 (by simp)).1
          simp only [k3, Lynx.Except.ok_bind, le_ok, g_if]
          by_cases c13 : (Term.compare (Term.fuel (κ H1) (κ H3)) (κ H1) (κ H3)).isLE = true
          · simp only [c13, ↓reduceIte]
            obtain ⟨p', tr⟩ := pushA p (by simpa using c12) (by simpa using c13)
            obtain ⟨R, run, res⟩ := ih1 T1 T2 T3 (H1 :: M) H2 H3 (κ H1) (Term.list T1)
              (by simp at len; omega) p' hd_self
            exact ⟨R, by simpa using run, tr R res⟩
          simp only [c13]
          have c31 := not_le_lt c13
          have a3 := ac H3 (by simp)
          obtain ⟨p', tr⟩ := pushC p a3 (by simpa using c31) (by simpa using c_lt_le c31 c12)
          obtain ⟨R, run, res⟩ := ih12 H1 T1 H2 T2 T3 (H3 :: M) (by simp at len; omega) p'
            (above_all p.sb (above_cons a3 (c_lt_le c31 c12))) (above_tail p.sc a3) c12
          exact ⟨R, by simpa using run, tr R res⟩
      · -- ukeymerge3_21_3
        intro H1 T1 H2 T2 T3 M len p ab ac c21
        have a2 := ab H2 (by simp)
        rw [Erlang.lists.«ukeymerge3_21_3/9».eq_def]
        cases T3 with
        | nil =>
          simp only []
          obtain ⟨p', tr⟩ := pushB p a2 (by simpa using c21) (by simp)
          obtain ⟨R, run, res⟩ := m2.2 T1 H1 T2 (H2 :: M) (by simp at len; omega) p'
            (above_tail p.sb a2)
          exact ⟨R, by simpa using run, tr R res⟩
        | cons H3 T3 =>
          have k3 := (p.kc H3 (by simp)).1
          simp only [k3, Lynx.Except.ok_bind, le_ok, g_if]
          by_cases c23 : (Term.compare (Term.fuel (κ H2) (κ H3)) (κ H2) (κ H3)).isLE = true
          · simp only [c23, ↓reduceIte]
            obtain ⟨p', tr⟩ := pushB p a2 (by simpa using c21) (by simpa using c23)
            obtain ⟨R, run, res⟩ := ih2 H1 T1 T2 H3 T3 (H2 :: M) (κ H2) (Term.list T2)
              (by simp at len; omega) p' (above_tail p.sb a2) hd_self
            exact ⟨R, by simpa using run, tr R res⟩
          simp only [c23]
          have c32 := not_le_lt c23
          have a3 := ac H3 (by simp)
          obtain ⟨p', tr⟩ := pushC p a3 (by simpa using c_lt_trans c32 c21) (by simpa using c32)
          obtain ⟨R, run, res⟩ := ih21 H1 T1 H2 T2 T3 (H3 :: M) (by simp at len; omega) p'
            (above_all p.sb (above_cons a3 c32)) (above_tail p.sc a3) c21
          exact ⟨R, by simpa using run, tr R res⟩

    end

    end Elixir.STTDescrProofsTest.USort
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.USort
    open Lynx

    theorem le_ne_lt {a b : Term} (h : (Term.compare (Term.fuel a b) a b).isLE = true) (ne : ¬Term.compare (Term.fuel a b) a b = .eq) :
        Term.compare (Term.fuel a b) a b = .lt := by
      cases e : Term.compare (Term.fuel a b) a b <;> simp_all

    theorem le_le {a b : Term} (h : Term.compare (Term.fuel a b) a b = .lt) : (Term.compare (Term.fuel a b) a b).isLE = true := by
      simp [h]

    section
    variable {κ : Term → Term} {Kd : Term → Prop}

    theorem preD_BC {M B C : List Term} (p : PreD κ Kd M [] B C) : PreD κ Kd M B C [] :=
      ⟨p.sm, p.sb, p.sc, SD_nil, p.kb, p.kc, fun _ h => by simp at h, p.ub, p.uc, fun _ h => by simp at h⟩

    theorem preD_AC {M A C : List Term} (p : PreD κ Kd M A [] C) : PreD κ Kd M A C [] :=
      ⟨p.sm, p.sa, p.sc, SD_nil, p.ka, p.kc, fun _ h => by simp at h, p.ua, p.uc, fun _ h => by simp at h⟩

    /-- The head of a descending source is above the rest of it. -/
    theorem sd_head {x y : Term} {B : List Term} (s : SD κ (x :: y :: B)) :
        Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) = .lt := c_lt_of_gt ((SD_cons.1 s).1 y (by simp))

    end

    section
    variable {I : Term} {κ : Term → Term}

    theorem rkm2 (n : Nat) :
        (∀ T1 H2 T2 M, 2 * (T1.length + T2.length + 1) + 1 ≤ n → (PreD κ (KdK I κ)) M T1 (H2 :: T2) [] →
          ∃ R, Erlang.lists.«rukeymerge2_1/6» I (Term.list T1) (κ H2) (Term.list T2) (Term.list M) H2 =
            .ok (Term.list R) ∧ ResD κ M T1 (H2 :: T2) [] R) ∧
        (∀ H1 T1 H2M T2 M, 2 * (T1.length + T2.length + 2) ≤ n → (PreD κ (KdK I κ)) M (H1 :: T1) (H2M :: T2) [] →
          (Term.compare (Term.fuel (κ H1) (κ H2M)) (κ H1) (κ H2M)).isLE = true →
          ∃ R, Erlang.lists.«rukeymerge2_2/8» I (Term.list T1) (κ H1) (Term.list T2) (Term.list M)
            (κ H2M) H2M H1 = .ok (Term.list R) ∧ ResD κ M (H1 :: T1) (H2M :: T2) [] R) := by
      induction n with
      | zero => refine ⟨?_, ?_⟩ <;> intros <;> omega
      | succ n ih =>
      obtain ⟨ih1, ih2⟩ := ih
      refine ⟨?_, ?_⟩
      · intro T1 H2 T2 M len p
        rw [Erlang.lists.«rukeymerge2_1/6».eq_def]
        cases T1 with
        | nil =>
          obtain ⟨p', tr⟩ := pushDB p (by simp) (by simp)
          exact ⟨_, by simpa using rev2 T2 (H2 :: M), tr _ (resD_congr (by simp) (resD_fin p'.sm p'.sb p'.ub))⟩
        | cons H1 T1 =>
          have k1 := (p.ka H1 (by simp)).1
          simp only [k1, Lynx.Except.ok_bind, le_ok, g_if]
          by_cases c12 : (Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)).isLE = true
          · simp only [c12, ↓reduceIte]
            exact ih2 H1 T1 H2 T2 M (by simp at len; omega) p c12
          simp only [c12]
          obtain ⟨p', tr⟩ := pushDA p (by simpa using not_le_lt c12) (by simp)
          obtain ⟨R, run, res⟩ := ih1 T1 H2 T2 (H1 :: M) (by simp at len; omega) p'
          exact ⟨R, by simpa using run, tr R res⟩
      · intro H1 T1 H2M T2 M len p c1
        rw [Erlang.lists.«rukeymerge2_2/8».eq_def]
        cases T2 with
        | nil =>
          simp only [eq_ok, g_if]
          by_cases e : Term.compare (Term.fuel (κ H1) (κ H2M)) (κ H1) (κ H2M) = .eq
          · simp only [e, ↓reduceIte]
            obtain ⟨p1, tr1⟩ := dropDB p (a := H1) (by simp) e
            obtain ⟨p2, tr2⟩ := pushDA p1 (by simp) (by simp)
            exact ⟨_, by simpa using rev2 T1 (H1 :: M), tr1 _ (tr2 _ (resD_fin p2.sm p2.sa p2.ua))⟩
          simp only [e, ↓reduceIte]
          obtain ⟨p1, tr1⟩ := pushDB p (by simpa using le_ne_lt c1 e) (by simp)
          obtain ⟨p2, tr2⟩ := pushDA p1 (by simp) (by simp)
          exact ⟨_, by simpa using rev2 T1 (H1 :: H2M :: M),
            tr1 _ (tr2 _ (resD_fin p2.sm p2.sa p2.ua))⟩
        | cons H2 T2 =>
          have k2 := (p.kb H2 (by simp)).1
          have s2 := sd_head p.sb
          simp only [k2, Lynx.Except.ok_bind, le_ok, eq_ok, g_if]
          by_cases c12 : (Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)).isLE = true
          · simp only [c12, ↓reduceIte]
            obtain ⟨p1, tr1⟩ := pushDB p (by simpa using c_le_lt c12 s2) (by simp)
            obtain ⟨R, run, res⟩ := ih2 H1 T1 H2 T2 (H2M :: M) (by simp at len; omega) p1 c12
            exact ⟨R, by simpa using run, tr1 R res⟩
          simp only [c12]
          have c21 := not_le_lt c12
          by_cases e : Term.compare (Term.fuel (κ H1) (κ H2M)) (κ H1) (κ H2M) = .eq
          · simp only [e, ↓reduceIte]
            obtain ⟨p1, tr1⟩ := dropDB p (a := H1) (by simp) e
            obtain ⟨p2, tr2⟩ := pushDA p1 (by simpa using c21) (by simp)
            obtain ⟨R, run, res⟩ := ih1 T1 H2 T2 (H1 :: M) (by simp at len; omega) p2
            exact ⟨R, by simpa using run, tr1 R (tr2 R res)⟩
          simp only [e, ↓reduceIte]
          obtain ⟨p1, tr1⟩ := pushDB p (by simpa using le_ne_lt c1 e) (by simp)
          obtain ⟨p2, tr2⟩ := pushDA p1 (by simpa using c21) (by simp)
          obtain ⟨R, run, res⟩ := ih1 T1 H2 T2 (H1 :: H2M :: M) (by simp at len; omega) p2
          exact ⟨R, by simpa using run, tr1 R (tr2 R res)⟩

    theorem rkm3 (n : Nat) :
        (∀ T1 H2 T2 H3 T3 M D1 D2, 2 * (T1.length + T2.length + T3.length + 2) + 1 ≤ n →
          (PreD κ (KdK I κ)) M T1 (H2 :: T2) (H3 :: T3) →
          ∃ R, Erlang.lists.«rukeymerge3_1/11» I (Term.list T1) D1 D2 (κ H2) H2 (Term.list T2) (Term.list M)
            (κ H3) H3 (Term.list T3) = .ok (Term.list R) ∧ ResD κ M T1 (H2 :: T2) (H3 :: T3) R) ∧
        (∀ H1 T1 H2M T2 H3 T3 M, 2 * (T1.length + T2.length + T3.length + 3) ≤ n →
          (PreD κ (KdK I κ)) M (H1 :: T1) (H2M :: T2) (H3 :: T3) → (Term.compare (Term.fuel (κ H1) (κ H2M)) (κ H1) (κ H2M)).isLE = true →
          Term.compare (Term.fuel (κ H3) (κ H2M)) (κ H3) (κ H2M) = .lt →
          ∃ R, Erlang.lists.«rukeymerge3_2/11» I (κ H1) H1 (Term.list T1) (Term.list T2) H2M (κ H2M)
            (Term.list M) (κ H3) H3 (Term.list T3) = .ok (Term.list R) ∧
            ResD κ M (H1 :: T1) (H2M :: T2) (H3 :: T3) R) ∧
        (∀ H1 T1 H2 T2 H3M T3 M, 2 * (T1.length + T2.length + T3.length + 3) ≤ n →
          (PreD κ (KdK I κ)) M (H1 :: T1) (H2 :: T2) (H3M :: T3) → (Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)).isLE = true →
          (Term.compare (Term.fuel (κ H2) (κ H3M)) (κ H2) (κ H3M)).isLE = true →
          ∃ R, Erlang.lists.«rukeymerge3_12_3/11» I (κ H1) H1 (Term.list T1) (κ H2) H2 (Term.list T2)
            (Term.list M) (κ H3M) H3M (Term.list T3) = .ok (Term.list R) ∧
            ResD κ M (H1 :: T1) (H2 :: T2) (H3M :: T3) R) ∧
        (∀ H1 T1 H2 T2 H3M T3 M, 2 * (T1.length + T2.length + T3.length + 3) ≤ n →
          (PreD κ (KdK I κ)) M (H1 :: T1) (H2 :: T2) (H3M :: T3) → Term.compare (Term.fuel (κ H2) (κ H1)) (κ H2) (κ H1) = .lt →
          (Term.compare (Term.fuel (κ H1) (κ H3M)) (κ H1) (κ H3M)).isLE = true →
          ∃ R, Erlang.lists.«rukeymerge3_21_3/11» I (κ H1) H1 (Term.list T1) (κ H2) H2 (Term.list T2)
            (Term.list M) (κ H3M) H3M (Term.list T3) = .ok (Term.list R) ∧
            ResD κ M (H1 :: T1) (H2 :: T2) (H3M :: T3) R) := by
      induction n with
      | zero => refine ⟨?_, ?_, ?_, ?_⟩ <;> intros <;> omega
      | succ n ih =>
      obtain ⟨ih1, ih2, ih12, ih21⟩ := ih
      have m2 := rkm2 (I := I) (κ := κ) n
      refine ⟨?_, ?_, ?_, ?_⟩
      · -- rukeymerge3_1
        intro T1 H2 T2 H3 T3 M D1 D2 len p
        rw [Erlang.lists.«rukeymerge3_1/11».eq_def]
        cases T1 with
        | nil =>
          simp only [le_ok, g_if]
          by_cases c23 : (Term.compare (Term.fuel (κ H2) (κ H3)) (κ H2) (κ H3)).isLE = true
          · simp only [c23, ↓reduceIte]
            obtain ⟨R, run, res⟩ := m2.2 H2 T2 H3 T3 M (by simp at len; omega) (preD_BC p) c23
            exact ⟨R, run, resD_congr (by simp) res⟩
          simp only [c23]
          obtain ⟨p1, tr1⟩ := pushDB p (by simp) (by simpa using not_le_lt c23)
          obtain ⟨R, run, res⟩ := m2.1 T2 H3 T3 (H2 :: M) (by simp at len; omega) (preD_BC p1)
          exact ⟨R, by simpa using run, tr1 R (resD_congr (by simp) res)⟩
        | cons H1 T1 =>
          have k1 := (p.ka H1 (by simp)).1
          simp only [k1, Lynx.Except.ok_bind, le_ok, g_if]
          by_cases c12 : (Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)).isLE = true
          · simp only [c12, ↓reduceIte]
            by_cases c23 : (Term.compare (Term.fuel (κ H2) (κ H3)) (κ H2) (κ H3)).isLE = true
            · simp only [c23, ↓reduceIte]
              exact ih12 H1 T1 H2 T2 H3 T3 M (by simp at len; omega) p c12 c23
            simp only [c23]
            exact ih2 H1 T1 H2 T2 H3 T3 M (by simp at len; omega) p c12 (not_le_lt c23)
          simp only [c12]
          by_cases c13 : (Term.compare (Term.fuel (κ H1) (κ H3)) (κ H1) (κ H3)).isLE = true
          · simp only [c13, ↓reduceIte]
            exact ih21 H1 T1 H2 T2 H3 T3 M (by simp at len; omega) p (not_le_lt c12) c13
          simp only [c13]
          obtain ⟨p1, tr1⟩ := pushDA p (by simpa using not_le_lt c12) (by simpa using not_le_lt c13)
          obtain ⟨R, run, res⟩ := ih1 T1 H2 T2 H3 T3 (H1 :: M) D1 D2 (by simp at len; omega) p1
          exact ⟨R, by simpa using run, tr1 R res⟩
      · -- rukeymerge3_2
        intro H1 T1 H2M T2 H3 T3 M len p c1 c3
        rw [Erlang.lists.«rukeymerge3_2/11».eq_def]
        cases T2 with
        | nil =>
          simp only [le_ok, eq_ok, g_if]
          by_cases e : Term.compare (Term.fuel (κ H1) (κ H2M)) (κ H1) (κ H2M) = .eq
          · simp only [e, ↓reduceIte]
            obtain ⟨p1, tr1⟩ := dropDB p (a := H1) (by simp) e
            obtain ⟨p2, tr2⟩ := pushDA p1 (by simp) (by simpa using c_lt_eq c3 (c_eq_symm e))
            obtain ⟨R, run, res⟩ := m2.1 T1 H3 T3 (H1 :: M) (by simp at len; omega) (preD_AC p2)
            exact ⟨R, by simpa using run, tr1 R (tr2 R (resD_congr (by simp) res))⟩
          simp only [e, ↓reduceIte]
          have l12 := le_ne_lt c1 e
          obtain ⟨p1, tr1⟩ := pushDB p (by simpa using l12) (by simpa using c3)
          by_cases c13 : (Term.compare (Term.fuel (κ H1) (κ H3)) (κ H1) (κ H3)).isLE = true
          · simp only [c13, ↓reduceIte]
            obtain ⟨R, run, res⟩ := m2.2 H1 T1 H3 T3 (H2M :: M) (by simp at len; omega) (preD_AC p1) c13
            exact ⟨R, by simpa using run, tr1 R (resD_congr (by simp) res)⟩
          simp only [c13]
          obtain ⟨p2, tr2⟩ := pushDA p1 (by simp) (by simpa using not_le_lt c13)
          obtain ⟨R, run, res⟩ := m2.1 T1 H3 T3 (H1 :: H2M :: M) (by simp at len; omega) (preD_AC p2)
          exact ⟨R, by simpa using run, tr1 R (tr2 R (resD_congr (by simp) res))⟩
        | cons H2 T2 =>
          have k2 := (p.kb H2 (by simp)).1
          have s2 := sd_head p.sb
          simp only [k2, Lynx.Except.ok_bind, le_ok, eq_ok, g_if]
          by_cases c12 : (Term.compare (Term.fuel (κ H1) (κ H2)) (κ H1) (κ H2)).isLE = true
          · simp only [c12, ↓reduceIte]
            obtain ⟨p1, tr1⟩ := pushDB p (by simpa using c_le_lt c12 s2) (by simpa using c3)
            by_cases c23 : (Term.compare (Term.fuel (κ H2) (κ H3)) (κ H2) (κ H3)).isLE = true
            · simp only [c23, ↓reduceIte]
              obtain ⟨R, run, res⟩ := ih12 H1 T1 H2 T2 H3 T3 (H2M :: M) (by simp at len; omega) p1 c12 c23
              exact ⟨R, by simpa using run, tr1 R res⟩
            simp only [c23]
            obtain ⟨R, run, res⟩ := ih2 H1 T1 H2 T2 H3 T3 (H2M :: M) (by simp at len; omega) p1 c12
              (not_le_lt c23)
            exact ⟨R, by simpa using run, tr1 R res⟩
          simp only [c12]
          have c21 := not_le_lt c12
          by_cases e : Term.compare (Term.fuel (κ H1) (κ H2M)) (κ H1) (κ H2M) = .eq
          · simp only [e, ↓reduceIte]
            obtain ⟨p1, tr1⟩ := dropDB p (a := H1) (by simp) e
            obtain ⟨p2, tr2⟩ := pushDA p1 (by simpa using c21) (by simpa using c_lt_eq c3 (c_eq_symm e))
            obtain ⟨R, run, res⟩ := ih1 T1 H2 T2 H3 T3 (H1 :: M) H1 (Term.list T1) (by simp at len; omega) p2
            exact ⟨R, by simpa using run, tr1 R (tr2 R res)⟩
          simp only [e, ↓reduceIte]
          have l12 := le_ne_lt c1 e
          obtain ⟨p1, tr1⟩ := pushDB p (by simpa using l12) (by simpa using c3)
          by_cases c13 : (Term.compare (Term.fuel (κ H1) (κ H3)) (κ H1) (κ H3)).isLE = true
          · simp only [c13, ↓reduceIte]
            obtain ⟨R, run, res⟩ := ih21 H1 T1 H2 T2 H3 T3 (H2M :: M) (by simp at len; omega) p1 c21 c13
            exact ⟨R, by simpa using run, tr1 R res⟩
          simp only [c13]
          obtain ⟨p2, tr2⟩ := pushDA p1 (by simpa using c21) (by simpa using not_le_lt c13)
          obtain ⟨R, run, res⟩ := ih1 T1 H2 T2 H3 T3 (H1 :: H2M :: M) H1 (Term.list T1)
            (by simp at len; omega) p2
          exact ⟨R, by simpa using run, tr1 R (tr2 R res)⟩
      · -- rukeymerge3_12_3
        intro H1 T1 H2 T2 H3M T3 M len p c12 c23
        rw [Erlang.lists.«rukeymerge3_12_3/11».eq_def]
        cases T3 with
        | nil =>
          simp only [eq_ok, g_if]
          by_cases e : Term.compare (Term.fuel (κ H2) (κ H3M)) (κ H2) (κ H3M) = .eq
          · simp only [e, ↓reduceIte]
            obtain ⟨p1, tr1⟩ := dropDC p (a := H2) (by simp) e
            obtain ⟨R, run, res⟩ := m2.2 H1 T1 H2 T2 M (by simp at len; omega) p1 c12
            exact ⟨R, run, tr1 R res⟩
          simp only [e, ↓reduceIte]
          have l23 := le_ne_lt c23 e
          obtain ⟨p1, tr1⟩ := pushDC p (by simpa using c_le_lt c12 l23) (by simpa using l23)
          obtain ⟨R, run, res⟩ := m2.2 H1 T1 H2 T2 (H3M :: M) (by simp at len; omega) p1 c12
          exact ⟨R, by simpa using run, tr1 R res⟩
        | cons H3 T3 =>
          have k3 := (p.kc H3 (by simp)).1
          have s3 := sd_head p.sc
          simp only [k3, Lynx.Except.ok_bind, le_ok, eq_ok, g_if]
          by_cases c23' : (Term.compare (Term.fuel (κ H2) (κ H3)) (κ H2) (κ H3)).isLE = true
          · simp only [c23', ↓reduceIte]
            have l23 := c_le_lt c23' s3
            obtain ⟨p1, tr1⟩ := pushDC p (by simpa using c_le_lt c12 l23) (by simpa using l23)
            obtain ⟨R, run, res⟩ := ih12 H1 T1 H2 T2 H3 T3 (H3M :: M) (by simp at len; omega) p1 c12 c23'
            exact ⟨R, by simpa using run, tr1 R res⟩
          simp only [c23']
          have c32 := not_le_lt c23'
          by_cases e : Term.compare (Term.fuel (κ H2) (κ H3M)) (κ H2) (κ H3M) = .eq
          · simp only [e, ↓reduceIte]
            obtain ⟨p1, tr1⟩ := dropDC p (a := H2) (by simp) e
            obtain ⟨R, run, res⟩ := ih2 H1 T1 H2 T2 H3 T3 M (by simp at len; omega) p1 c12 c32
            exact ⟨R, run, tr1 R res⟩
          simp only [e, ↓reduceIte]
          have l23 := le_ne_lt c23 e
          obtain ⟨p1, tr1⟩ := pushDC p (by simpa using c_le_lt c12 l23) (by simpa using l23)
          obtain ⟨R, run, res⟩ := ih2 H1 T1 H2 T2 H3 T3 (H3M :: M) (by simp at len; omega) p1 c12 c32
          exact ⟨R, by simpa using run, tr1 R res⟩
      · -- rukeymerge3_21_3
        intro H1 T1 H2 T2 H3M T3 M len p c21 c13
        rw [Erlang.lists.«rukeymerge3_21_3/11».eq_def]
        cases T3 with
        | nil =>
          simp only [eq_ok, g_if]
          by_cases e : Term.compare (Term.fuel (κ H1) (κ H3M)) (κ H1) (κ H3M) = .eq
          · simp only [e, ↓reduceIte]
            obtain ⟨p1, tr1⟩ := dropDC p (a := H1) (by simp) e
            obtain ⟨p2, tr2⟩ := pushDA p1 (by simpa using c21) (by simp)
            obtain ⟨R, run, res⟩ := m2.1 T1 H2 T2 (H1 :: M) (by simp at len; omega) p2
            exact ⟨R, by simpa using run, tr1 R (tr2 R res)⟩
          simp only [e, ↓reduceIte]
          have l13 := le_ne_lt c13 e
          obtain ⟨p1, tr1⟩ := pushDC p (by simpa using l13) (by simpa using c_lt_trans c21 l13)
          obtain ⟨p2, tr2⟩ := pushDA p1 (by simpa using c21) (by simp)
          obtain ⟨R, run, res⟩ := m2.1 T1 H2 T2 (H1 :: H3M :: M) (by simp at len; omega) p2
          exact ⟨R, by simpa using run, tr1 R (tr2 R res)⟩
        | cons H3 T3 =>
          have k3 := (p.kc H3 (by simp)).1
          have s3 := sd_head p.sc
          simp only [k3, Lynx.Except.ok_bind, le_ok, eq_ok, g_if]
          by_cases c13' : (Term.compare (Term.fuel (κ H1) (κ H3)) (κ H1) (κ H3)).isLE = true
          · simp only [c13', ↓reduceIte]
            have l13 := c_le_lt c13' s3
            obtain ⟨p1, tr1⟩ := pushDC p (by simpa using l13) (by simpa using c_lt_trans c21 l13)
            obtain ⟨R, run, res⟩ := ih21 H1 T1 H2 T2 H3 T3 (H3M :: M) (by simp at len; omega) p1 c21 c13'
            exact ⟨R, by simpa using run, tr1 R res⟩
          simp only [c13']
          have c31 := not_le_lt c13'
          by_cases e : Term.compare (Term.fuel (κ H1) (κ H3M)) (κ H1) (κ H3M) = .eq
          · simp only [e, ↓reduceIte]
            obtain ⟨p1, tr1⟩ := dropDC p (a := H1) (by simp) e
            obtain ⟨p2, tr2⟩ := pushDA p1 (by simpa using c21) (by simpa using c31)
            obtain ⟨R, run, res⟩ := ih1 T1 H2 T2 H3 T3 (H1 :: M) H1 (Term.list T1) (by simp at len; omega) p2
            exact ⟨R, by simpa using run, tr1 R (tr2 R res)⟩
          simp only [e, ↓reduceIte]
          have l13 := le_ne_lt c13 e
          obtain ⟨p1, tr1⟩ := pushDC p (by simpa using l13) (by simpa using c_lt_trans c21 l13)
          obtain ⟨p2, tr2⟩ := pushDA p1 (by simpa using c21) (by simpa using c31)
          obtain ⟨R, run, res⟩ := ih1 T1 H2 T2 H3 T3 (H1 :: H3M :: M) H1 (Term.list T1)
            (by simp at len; omega) p2
          exact ⟨R, by simpa using run, tr1 R (tr2 R res)⟩

    end

    end Elixir.STTDescrProofsTest.USort
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.USort
    open Lynx

    section
    variable {κ : Term → Term}

    theorem eqv_ne_nil {R S : List Term} (e : Eqv κ R S) (h : S ≠ []) : R ≠ [] := by
      obtain ⟨x, S', rfl⟩ := List.exists_cons_of_ne_nil h
      intro hr
      have := e (κ x)
      simp [hr, lk_cons] at this

    theorem lk_mem {s z : Term} {A : List Term} (h : lk κ s A = some z) : z ∈ A := by
      induction A with
      | nil => simp at h
      | cons y ys ih =>
        by_cases e : Term.compare (Term.fuel (κ y) s) (κ y) s = .eq
        · simp [lk_cons, e] at h; simp [h]
        · simp [lk_cons, e] at h; simp [ih h]

    theorem lk_self {x : Term} {A : List Term}
        (h : A.Pairwise fun a b => Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) ≠ .eq) (hx : x ∈ A) :
        lk κ (κ x) A = some x := by
      induction A with
      | nil => simp at hx
      | cons y ys ih =>
        rw [List.pairwise_cons] at h
        simp only [List.mem_cons] at hx
        by_cases e : x = y
        · subst e; simp [lk_cons]
        · have hx' : x ∈ ys := hx.resolve_left e
          simp [lk_cons, h.1 x hx', ih h.2 hx']

    theorem mem_of_eqv {R S : List Term} {x : Term}
        (h : R.Pairwise fun a b => Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) ≠ .eq) (e : Eqv κ R S) (hx : x ∈ R) :
        x ∈ S := lk_mem ((e (κ x)).symm.trans (lk_self h hx))

    theorem eqv_acc {R M X : List Term} (P Q : List Term) (er : Eqv κ R (P ++ M ++ Q)) (em : Eqv κ M X) :
        Eqv κ R (P ++ X ++ Q) := er.trans (((Eqv.refl P).append em).append (Eqv.refl Q))

    /-- Members of a merge of keyed sources are keyed. -/
    theorem kd_of_eqv {Kd : Term → Prop} {M S : List Term}
        (h : M.Pairwise fun a b => Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) ≠ .eq) (e : Eqv κ M S)
        (k : ∀ x ∈ S, Kd x) : ∀ x ∈ M, Kd x := fun x hx => k x (mem_of_eqv h e hx)

    /-- Nonempty runs of keyed elements, ascending or descending. -/
    def RunsA (Kd : Term → Prop) (Rs : List (List Term)) : Prop :=
      ∀ r ∈ Rs, r ≠ [] ∧ SA κ r ∧ ∀ x ∈ r, Kd x

    def RunsD (Kd : Term → Prop) (Rs : List (List Term)) : Prop :=
      ∀ r ∈ Rs, r ≠ [] ∧ SD κ r ∧ ∀ x ∈ r, Kd x

    end

    section
    variable {I : Term} {κ : Term → Term}

    theorem ukm_mergel (n : Nat) :
        (∀ Rs Acc, 4 * (Rs.length + Acc.length) + 2 * min Acc.length 1 ≤ n →
          1 ≤ Rs.length + Acc.length → RunsA (κ := κ) (KdK I κ) Rs → RunsD (κ := κ) (KdK I κ) Acc →
          ∃ R, Erlang.lists.«ukeymergel/3» I (Term.list (Rs.map Term.list)) (Term.list (Acc.map Term.list)) =
            .ok (Term.list R) ∧ SA κ R ∧ Eqv κ R (Acc.reverse.flatten ++ Rs.flatten)) ∧
        (∀ Rs Acc, 4 * (Rs.length + Acc.length) + 2 * min Acc.length 1 + 1 ≤ n →
          1 ≤ Rs.length + Acc.length → RunsD (κ := κ) (KdK I κ) Rs → RunsA (κ := κ) (KdK I κ) Acc →
          ∃ R, Erlang.lists.«rukeymergel/3» I (Term.list (Rs.map Term.list)) (Term.list (Acc.map Term.list)) =
            .ok (Term.list R) ∧ SA κ R ∧ Eqv κ R (Rs.reverse.flatten ++ Acc.flatten)) := by
      induction n with
      | zero => refine ⟨?_, ?_⟩ <;> intros <;> omega
      | succ n ih =>
      obtain ⟨ih1, ih2⟩ := ih
      refine ⟨?_, ?_⟩
      · intro Rs Acc len one ra rd
        rw [Erlang.lists.«ukeymergel/3».eq_def]
        match Rs with
        | [] =>
          simp only [List.map_nil]
          obtain ⟨R, run, sr, er⟩ := ih2 Acc [] (by simp at len one ⊢; omega) (by simpa using one) rd
            (by simp [RunsA])
          exact ⟨R, run, sr, by simpa using er⟩
        | [L] =>
          cases Acc with
          | nil =>
            obtain ⟨_, sl, _⟩ := ra L (by simp)
            exact ⟨L, by simp, sl, by simpa using Eqv.refl L⟩
          | cons A Acc =>
            obtain ⟨nl, sl, kl⟩ := ra L (by simp)
            have rv := rev2 L []
            simp only [List.append_nil] at rv
            simp only [List.map_cons, List.map_nil, ← Term.list_nil, rv,
              Lynx.Except.ok_bind]
            obtain ⟨R, run, sr, er⟩ := ih2 (L.reverse :: A :: Acc) [] (by simp at len ⊢; omega) (by simp)
              (by
                intro r hr
                simp only [List.mem_cons] at hr
                rcases hr with rfl | hr
                · exact ⟨by simpa using nl, SD_reverse.2 sl, fun x hx => kl x (by simpa using hx)⟩
                · exact rd r (by simp [hr]))
              (by simp [RunsA])
            refine ⟨R, by simpa using run, sr, er.trans ?_⟩
            simp only [List.reverse_cons, List.flatten_append, List.flatten_cons, List.flatten_nil,
              List.append_nil, List.append_assoc]
            exact Eqv.append (Eqv.refl _) (Eqv.append (Eqv.refl _) (eqv_reverse sl.ne))
        | [r1, r2] =>
          obtain ⟨n1, s1, k1⟩ := ra r1 (by simp)
          obtain ⟨n2, s2, k2⟩ := ra r2 (by simp)
          obtain ⟨H1, T1, rfl⟩ := List.exists_cons_of_ne_nil n1
          obtain ⟨H2, T2, rfl⟩ := List.exists_cons_of_ne_nil n2
          have e1 := (k1 H1 (by simp)).1
          obtain ⟨M, run, sm, em⟩ := (ukm2 (I := I) (κ := κ) (T1.length + 1 + (H2 :: T2).length)).2 T1 H1 (H2 :: T2) []
            (by omega) ⟨SD_nil, s1, s2, SA_nil, k1, k2, by simp, fun _ _ _ h => by simp at h,
              fun _ _ => Or.inl fun _ h => by simp at h, by simp⟩ (fun _ _ _ h => by simp at h)
          simp only [List.map_cons, List.map_nil, e1, run,
            Lynx.Except.ok_bind]
          obtain ⟨R, run', sr, er⟩ := ih1 [] (M :: Acc) (by simp at len ⊢; omega) (by simp)
            (by simp [RunsA]) (by
              intro r hr
              simp only [List.mem_cons] at hr
              rcases hr with rfl | hr
              · exact ⟨eqv_ne_nil em (by simp), sm, kd_of_eqv sm.ne em (by
                  intro x hx; simp only [List.nil_append, List.append_nil, List.mem_append] at hx
                  rcases hx with hx | hx; exact k1 x hx; exact k2 x hx)⟩
              · exact rd r hr)
          refine ⟨R, by simpa using run', sr, ?_⟩
          have := eqv_acc Acc.reverse.flatten [] (by simpa using er) em
          simpa using this
        | r1 :: r2 :: r3 :: L =>
          obtain ⟨_, s1, k1⟩ := ra r1 (by simp)
          obtain ⟨n2, s2, k2⟩ := ra r2 (by simp)
          obtain ⟨n3, s3, k3⟩ := ra r3 (by simp)
          obtain ⟨H2, T2, rfl⟩ := List.exists_cons_of_ne_nil n2
          obtain ⟨H3, T3, rfl⟩ := List.exists_cons_of_ne_nil n3
          have e2 := (k2 H2 (by simp)).1
          have e3 := (k3 H3 (by simp)).1
          obtain ⟨M, run, sm, em⟩ := (ukm3 (I := I) (κ := κ) (r1.length + T2.length + T3.length + 2)).1
            r1 T2 T3 [] H2 H3 (.cons H2 H3) (Term.list (Acc.map Term.list)) (by omega)
            ⟨SD_nil, s1, s2, s3, k1, k2, k3, fun _ _ _ h => by simp at h,
              fun _ _ => Or.inl fun _ h => by simp at h, fun _ _ => Or.inl fun _ h => by simp at h⟩
            (fun x hx => by
              simp only [List.cons_append, List.mem_cons, List.mem_append] at hx
              rcases hx with h | h | h | h
              · subst h; exact (k2 x (by simp)).2 _ _
              · exact (k2 x (by simp [h])).2 _ _
              · subst h; exact (k3 x (by simp)).2 _ _
              · exact (k3 x (by simp [h])).2 _ _)
          simp only [List.map_cons, e2, e3, run, Lynx.Except.ok_bind]
          obtain ⟨R, run', sr, er⟩ := ih1 L (M :: Acc) (by simp at len ⊢; omega) (by simp only [List.length_cons]; omega)
            (fun r hr => ra r (by simp [hr])) (by
              intro r hr
              simp only [List.mem_cons] at hr
              rcases hr with rfl | hr
              · exact ⟨eqv_ne_nil em (by simp), sm, kd_of_eqv sm.ne em (by
                  intro x hx; simp only [List.nil_append, List.mem_append] at hx
                  rcases hx with (hx | hx) | hx
                  · exact k1 x hx
                  · exact k2 x hx
                  · exact k3 x hx)⟩
              · exact rd r hr)
          refine ⟨R, by simpa using run', sr, ?_⟩
          have := eqv_acc Acc.reverse.flatten L.flatten (by simpa using er) em
          simpa using this
      · intro Rs Acc len one rd ra
        rw [Erlang.lists.«rukeymergel/3».eq_def]
        match Rs with
        | [] =>
          simp only [List.map_nil]
          obtain ⟨R, run, sr, er⟩ := ih1 Acc [] (by simp at len one ⊢; omega) (by simpa using one) ra
            (by simp [RunsD])
          exact ⟨R, run, sr, by simpa using er⟩
        | [L] =>
          obtain ⟨nl, sl, kl⟩ := rd L (by simp)
          have rv := rev2 L []
          simp only [List.append_nil] at rv
          simp only [List.map_cons, List.map_nil, ← Term.list_nil, rv,
            Lynx.Except.ok_bind]
          obtain ⟨R, run, sr, er⟩ := ih1 (L.reverse :: Acc) [] (by simp at len ⊢; omega) (by simp)
            (by
              intro r hr
              simp only [List.mem_cons] at hr
              rcases hr with rfl | hr
              · exact ⟨by simpa using nl, SA_reverse.2 sl, fun x hx => kl x (by simpa using hx)⟩
              · exact ra r hr)
            (by simp [RunsD])
          refine ⟨R, by simpa using run, sr, er.trans ?_⟩
          simp only [List.reverse_nil, List.flatten_nil, List.nil_append, List.flatten_cons,
            List.reverse_cons, List.append_nil]
          exact Eqv.append (eqv_reverse sl.ne) (Eqv.refl _)
        | [r2, r1] =>
          obtain ⟨n1, s1, k1⟩ := rd r1 (by simp)
          obtain ⟨n2, s2, k2⟩ := rd r2 (by simp)
          obtain ⟨H2, T2, rfl⟩ := List.exists_cons_of_ne_nil n2
          obtain ⟨H1, T1, rfl⟩ := List.exists_cons_of_ne_nil n1
          have e2 := (k2 H2 (by simp)).1
          obtain ⟨M, run, sm, em⟩ := (rkm2 (I := I) (κ := κ) (2 * ((H1 :: T1).length + T2.length + 1) + 1)).1
            (H1 :: T1) H2 T2 [] (by omega) ⟨SA_nil, s1, s2, SD_nil, k1, k2, by simp, fun _ _ _ h => by simp at h,
              fun _ _ _ h => by simp at h, by simp⟩
          simp only [List.map_cons, List.map_nil, e2, run,
            Lynx.Except.ok_bind]
          obtain ⟨R, run', sr, er⟩ := ih2 [] (M :: Acc) (by simp at len ⊢; omega) (by simp)
            (by simp [RunsD]) (by
              intro r hr
              simp only [List.mem_cons] at hr
              rcases hr with rfl | hr
              · exact ⟨eqv_ne_nil em (by simp), sm, kd_of_eqv sm.ne em (by
                  intro x hx; simp only [List.nil_append, List.append_nil, List.mem_append] at hx
                  rcases hx with hx | hx; exact k1 x hx; exact k2 x hx)⟩
              · exact ra r hr)
          refine ⟨R, by simpa using run', sr, ?_⟩
          have := eqv_acc [] Acc.flatten (by simpa using er) em
          simpa using this
        | r3 :: r2 :: r1 :: L =>
          obtain ⟨_, s1, k1⟩ := rd r1 (by simp)
          obtain ⟨n2, s2, k2⟩ := rd r2 (by simp)
          obtain ⟨n3, s3, k3⟩ := rd r3 (by simp)
          obtain ⟨H2, T2, rfl⟩ := List.exists_cons_of_ne_nil n2
          obtain ⟨H3, T3, rfl⟩ := List.exists_cons_of_ne_nil n3
          have e2 := (k2 H2 (by simp)).1
          have e3 := (k3 H3 (by simp)).1
          obtain ⟨M, run, sm, em⟩ := (rkm3 (I := I) (κ := κ)
            (2 * (r1.length + T2.length + T3.length + 2) + 1)).1
            r1 H2 T2 H3 T3 [] (Term.list (Acc.map Term.list)) .nil (by omega)
            ⟨SA_nil, s1, s2, s3, k1, k2, k3, fun _ _ _ h => by simp at h,
              fun _ _ _ h => by simp at h, fun _ _ _ h => by simp at h⟩
          simp only [List.map_cons, e2, e3, run, Lynx.Except.ok_bind]
          obtain ⟨R, run', sr, er⟩ := ih2 L (M :: Acc) (by simp at len ⊢; omega) (by simp only [List.length_cons]; omega)
            (fun r hr => rd r (by simp [hr])) (by
              intro r hr
              simp only [List.mem_cons] at hr
              rcases hr with rfl | hr
              · exact ⟨eqv_ne_nil em (by simp), sm, kd_of_eqv sm.ne em (by
                  intro x hx; simp only [List.nil_append, List.mem_append] at hx
                  rcases hx with (hx | hx) | hx
                  · exact k1 x hx
                  · exact k2 x hx
                  · exact k3 x hx)⟩
              · exact ra r hr)
          refine ⟨R, by simpa using run', sr, ?_⟩
          have := eqv_acc L.reverse.flatten Acc.flatten (by simpa using er) em
          simpa using this

    end

    end Elixir.STTDescrProofsTest.USort
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.USort
    open Lynx

    section
    variable {κ : Term → Term}

    /-- An element moved into the middle of a run, past keys it does not share. -/
    theorem ins_mid {P A B L : List Term} {z : Term}
        (h : ∀ y ∈ A ++ B, Term.compare (Term.fuel (κ y) (κ z)) (κ y) (κ z) ≠ .eq) :
        Eqv κ (P ++ (A ++ z :: B) ++ L) (P ++ (A ++ B) ++ z :: L) := by
      have e1 := eqv_move (κ := κ) (A := A) (B := B ++ L) (x := z) (fun y hy => h y (by simp [hy]))
      have e2 := eqv_move (κ := κ) (A := A ++ B) (B := L) (x := z) h
      simp only [List.append_assoc] at e1 e2 ⊢
      exact (Eqv.refl P).append (e1.trans e2.symm)

    theorem drop_at {P L : List Term} {y z : Term} (hy : y ∈ P) (e : Term.compare (Term.fuel (κ y) (κ z)) (κ y) (κ z) = .eq) :
        Eqv κ (P ++ L) (P ++ z :: L) := (eqv_drop hy e).symm

    theorem not_islt {a b : Term} (h : ¬Term.compare (Term.fuel a b) a b = .lt) : ¬(Term.compare (Term.fuel a b) a b).isLT = true := by
      cases e : Term.compare (Term.fuel a b) a b <;> simp_all

    theorem lt_swap_of {a b : Term} (e : ¬Term.compare (Term.fuel a b) a b = .eq) (l : ¬Term.compare (Term.fuel a b) a b = .lt) :
        Term.compare (Term.fuel b a) b a = .lt := by
      cases e' : Term.compare (Term.fuel a b) a b
      · exact absurd e' l
      · exact absurd e' e
      · exact c_lt_of_gt e'

    theorem nil_cmp {R : List Term} : Term.compare (Term.fuel (Term.list R) .nil) (Term.list R) .nil = .eq ↔ R = [] := by
      cases R <;> simp

    end

    section
    variable {I : Term} {κ : Term → Term}

    theorem uks1_end (X Y : Term) (R : List Term) (Rs : List (List Term)) (sc : SD κ (Y :: X :: R))
        (kc : ∀ x ∈ Y :: X :: R, (KdK I κ) x) (rs : RunsD (κ := κ) (KdK I κ) Rs) :
        ∃ Res, Erlang.lists.«ukeysplit_1/8» I X (κ X) Y (κ Y) (Term.list []) (Term.list R)
          (Term.list (Rs.map Term.list)) = .ok (Term.list Res) ∧ SA κ Res ∧
          Eqv κ Res (Rs.reverse.flatten ++ (Y :: X :: R) ++ []) := by
      rw [Erlang.lists.«ukeysplit_1/8».eq_def]
      obtain ⟨Res, run, sr, er⟩ := (ukm_mergel (I := I) (κ := κ) (4 * (Rs.length + 2) + 1)).2
        ((Y :: X :: R) :: Rs) [] (by simp; omega) (by simp) (by
          intro r hr
          simp only [List.mem_cons] at hr
          rcases hr with rfl | hr
          · exact ⟨by simp, sc, kc⟩
          · exact rs r hr) (by simp [RunsA])
      exact ⟨Res, by simpa using run, sr, by simpa using er⟩

    theorem uks11_end (X Y S : Term) (R : List Term) (Rs : List (List Term)) (sc : SD κ (Y :: X :: R))
        (kc : ∀ x ∈ Y :: X :: R, (KdK I κ) x) (ks : (KdK I κ) S) (rs : RunsD (κ := κ) (KdK I κ) Rs) :
        ∃ Res, Erlang.lists.«ukeysplit_1_1/10» I X (κ X) Y (κ Y) (Term.list []) (Term.list R)
          (Term.list (Rs.map Term.list)) S (κ S) = .ok (Term.list Res) ∧ SA κ Res ∧
          Eqv κ Res (Rs.reverse.flatten ++ (Y :: X :: R) ++ [S]) := by
      rw [Erlang.lists.«ukeysplit_1_1/10».eq_def]
      obtain ⟨Res, run, sr, er⟩ := (ukm_mergel (I := I) (κ := κ) (4 * (Rs.length + 3) + 1)).2
        ([S] :: (Y :: X :: R) :: Rs) [] (by simp; omega) (by simp) (by
          intro r hr
          simp only [List.mem_cons] at hr
          rcases hr with rfl | rfl | hr
          · exact ⟨by simp, by simp [SD], by simpa using ks⟩
          · exact ⟨by simp, sc, kc⟩
          · exact rs r hr) (by simp [RunsA])
      exact ⟨Res, by simpa using run, sr, by simpa using er⟩

    theorem uks1 (n : Nat) :
        (∀ X Y L R Rs, L.length ≤ n → SD κ (Y :: X :: R) → (∀ x ∈ Y :: X :: R, (KdK I κ) x) →
          RunsD (κ := κ) (KdK I κ) Rs → (∀ x ∈ L, (KdK I κ) x) →
          ∃ Res, Erlang.lists.«ukeysplit_1/8» I X (κ X) Y (κ Y) (Term.list L) (Term.list R)
            (Term.list (Rs.map Term.list)) = .ok (Term.list Res) ∧ SA κ Res ∧
            Eqv κ Res (Rs.reverse.flatten ++ (Y :: X :: R) ++ L)) ∧
        (∀ X Y L R Rs S, L.length ≤ n → SD κ (Y :: X :: R) → (∀ x ∈ Y :: X :: R, (KdK I κ) x) →
          Term.compare (Term.fuel (κ S) (κ X)) (κ S) (κ X) = .lt → (KdK I κ) S → RunsD (κ := κ) (KdK I κ) Rs → (∀ x ∈ L, (KdK I κ) x) →
          ∃ Res, Erlang.lists.«ukeysplit_1_1/10» I X (κ X) Y (κ Y) (Term.list L) (Term.list R)
            (Term.list (Rs.map Term.list)) S (κ S) = .ok (Term.list Res) ∧ SA κ Res ∧
            Eqv κ Res (Rs.reverse.flatten ++ (Y :: X :: R) ++ S :: L)) := by
      induction n with
      | zero =>
        refine ⟨?_, ?_⟩
        · intro X Y L R Rs len sc kc rs _
          cases L with
          | cons => simp at len
          | nil => exact uks1_end X Y R Rs sc kc rs
        · intro X Y L R Rs S len sc kc _ ks rs _
          cases L with
          | cons => simp at len
          | nil => exact uks11_end X Y S R Rs sc kc ks rs
      | succ n ih =>
      obtain ⟨ih1, ih2⟩ := ih
      refine ⟨?_, ?_⟩
      · intro X Y L R Rs len sc kc rs kl
        cases L with
        | nil => exact uks1_end X Y R Rs sc kc rs
        | cons Z L =>
        have kz := kl Z (by simp)
        have kl' : ∀ x ∈ L, (KdK I κ) x := fun x hx => kl x (by simp [hx])
        have len' : L.length ≤ n := by simp at len; omega
        have sc' := SD_cons.1 sc
        have yx : Term.compare (Term.fuel (κ X) (κ Y)) (κ X) (κ Y) = .lt := c_lt_of_gt (sc'.1 X (by simp))
        rw [Erlang.lists.«ukeysplit_1/8».eq_def]
        simp only [kz.1, Lynx.Except.ok_bind, eq_ok, lt_ok, g_if]
        by_cases e1 : Term.compare (Term.fuel (κ Y) (κ Z)) (κ Y) (κ Z) = .eq
        · simp only [e1, ↓reduceIte]
          obtain ⟨Res, run, sr, er⟩ := ih1 X Y L R Rs len' sc kc rs kl'
          have dd := drop_at (κ := κ) (P := Rs.reverse.flatten ++ Y :: X :: R) (L := L) (y := Y) (z := Z)
            (by simp) e1
          exact ⟨Res, run, sr, er.trans (by simpa using dd)⟩
        simp only [e1, ↓reduceIte]
        have zy : Term.compare (Term.fuel (κ Z) (κ Y)) (κ Z) (κ Y) ≠ .eq := fun e => e1 (c_eq_symm e)
        by_cases l1 : Term.compare (Term.fuel (κ Y) (κ Z)) (κ Y) (κ Z) = .lt
        · simp only [l1, Ordering.isLT_lt, ↓reduceIte]
          have gz := SD.gt_all sc (c_gt_of_lt l1)
          obtain ⟨Res, run, sr, er⟩ := ih1 Y Z L (X :: R) Rs len' (SD_cons.2 ⟨gz, sc⟩)
            (fun x hx => by simp only [List.mem_cons] at hx; rcases hx with rfl | hx; exact kz; exact kc x (by simpa using hx))
            rs kl'
          have := ins_mid (κ := κ) (P := Rs.reverse.flatten) (A := []) (B := Y :: X :: R) (L := L) (z := Z)
            (fun y hy => by have := gz y (by simpa using hy); rw [c_swap, this]; simp)
          exact ⟨Res, by simpa using run, sr, er.trans (by simpa using this)⟩
        have l1' := not_islt l1
        simp only [l1', Bool.false_eq_true, ↓reduceIte]
        have gzy := lt_swap_of e1 l1
        by_cases e2 : Term.compare (Term.fuel (κ X) (κ Z)) (κ X) (κ Z) = .eq
        · simp only [e2, ↓reduceIte]
          obtain ⟨Res, run, sr, er⟩ := ih1 X Y L R Rs len' sc kc rs kl'
          have dd := drop_at (κ := κ) (P := Rs.reverse.flatten ++ Y :: X :: R) (L := L) (y := X) (z := Z)
            (by simp) e2
          exact ⟨Res, run, sr, er.trans (by simpa using dd)⟩
        simp only [e2, ↓reduceIte]
        have sx := SD_cons.1 sc'.2
        by_cases l2 : Term.compare (Term.fuel (κ X) (κ Z)) (κ X) (κ Z) = .lt
        · simp only [l2, Ordering.isLT_lt, ↓reduceIte]
          have gzx := SD.gt_all sc'.2 (c_gt_of_lt l2)
          obtain ⟨Res, run, sr, er⟩ := ih1 Z Y L (X :: R) Rs len'
            (SD_cons.2 ⟨fun w hw => by
                simp only [List.mem_cons] at hw
                rcases hw with rfl | hw
                · exact c_gt_of_lt gzy
                · exact sc'.1 w (by simpa using hw), SD_cons.2 ⟨gzx, sc'.2⟩⟩)
            (fun x hx => by
              simp only [List.mem_cons] at hx
              rcases hx with rfl | rfl | hx
              · exact kc x (by simp)
              · exact kz
              · exact kc x (by simp [hx]))
            rs kl'
          have := ins_mid (κ := κ) (P := Rs.reverse.flatten) (A := [Y]) (B := X :: R) (L := L) (z := Z)
            (fun y hy => by
              simp only [List.cons_append, List.nil_append, List.mem_cons] at hy
              rcases hy with rfl | hy
              · intro e; exact zy (c_eq_symm e)
              · have := gzx y (by simpa using hy); rw [c_swap, this]; simp)
          exact ⟨Res, by simpa using run, sr, er.trans (by simpa using this)⟩
        have l2' := not_islt l2
        simp only [l2', Bool.false_eq_true, ↓reduceIte]
        have gzx := lt_swap_of e2 l2
        cases R with
        | nil =>
          simp only [Term.compare_self, ↓reduceIte]
          obtain ⟨Res, run, sr, er⟩ := ih1 X Y L [Z] Rs len'
            (by simp [SD]; exact ⟨⟨sc'.1 X (by simp), c_gt_of_lt (c_lt_trans gzx yx)⟩, c_gt_of_lt gzx⟩)
            (fun x hx => by
              simp only [List.mem_cons, List.not_mem_nil, or_false] at hx
              rcases hx with rfl | rfl | rfl
              · exact kc x (by simp)
              · exact kc x (by simp)
              · exact kz)
            rs kl'
          exact ⟨Res, by simpa using run, sr, by simpa using er⟩
        | cons r R =>
          have : ¬Term.compare (Term.fuel (Term.list (r :: R)) .nil) (Term.list (r :: R)) .nil = .eq := by simp
          simp only [this, ↓reduceIte]
          obtain ⟨Res, run, sr, er⟩ := ih2 X Y L (r :: R) Rs Z len' sc kc gzx kz rs kl'
          exact ⟨Res, run, sr, by simpa using er⟩
      · intro X Y L R Rs S len sc kc sx ks rs kl
        cases L with
        | nil => exact uks11_end X Y S R Rs sc kc ks rs
        | cons Z L =>
        have kz := kl Z (by simp)
        have kl' : ∀ x ∈ L, (KdK I κ) x := fun x hx => kl x (by simp [hx])
        have len' : L.length ≤ n := by simp at len; omega
        have sc' := SD_cons.1 sc
        have yx : Term.compare (Term.fuel (κ X) (κ Y)) (κ X) (κ Y) = .lt := c_lt_of_gt (sc'.1 X (by simp))
        have sy := c_lt_trans sx yx
        rw [Erlang.lists.«ukeysplit_1_1/10».eq_def]
        simp only [kz.1, Lynx.Except.ok_bind, eq_ok, lt_ok, g_if]
        by_cases e1 : Term.compare (Term.fuel (κ Y) (κ Z)) (κ Y) (κ Z) = .eq
        · simp only [e1, ↓reduceIte]
          obtain ⟨Res, run, sr, er⟩ := ih2 X Y L R Rs S len' sc kc sx ks rs kl'
          have dd := drop_at (κ := κ) (P := Rs.reverse.flatten ++ Y :: X :: R ++ [S]) (L := L) (y := Y)
            (z := Z) (by simp) e1
          exact ⟨Res, run, sr, er.trans (by simpa using dd)⟩
        simp only [e1, ↓reduceIte]
        have zy : Term.compare (Term.fuel (κ Z) (κ Y)) (κ Z) (κ Y) ≠ .eq := fun e => e1 (c_eq_symm e)
        by_cases l1 : Term.compare (Term.fuel (κ Y) (κ Z)) (κ Y) (κ Z) = .lt
        · simp only [l1, Ordering.isLT_lt, ↓reduceIte]
          have gz := SD.gt_all sc (c_gt_of_lt l1)
          obtain ⟨Res, run, sr, er⟩ := ih2 Y Z L (X :: R) Rs S len' (SD_cons.2 ⟨gz, sc⟩)
            (fun x hx => by simp only [List.mem_cons] at hx; rcases hx with rfl | hx; exact kz; exact kc x (by simpa using hx))
            sy ks rs kl'
          have := ins_mid (κ := κ) (P := Rs.reverse.flatten) (A := []) (B := Y :: X :: R ++ [S]) (L := L)
            (z := Z) (fun y hy => by
              simp only [List.nil_append, List.mem_append, List.mem_singleton] at hy
              rcases hy with hy | rfl
              · have := gz y hy; rw [c_swap, this]; simp
              · rw [c_lt_trans sy l1]; simp)
          exact ⟨Res, by simpa using run, sr, er.trans (by simpa using this)⟩
        have l1' := not_islt l1
        simp only [l1', Bool.false_eq_true, ↓reduceIte]
        have gzy := lt_swap_of e1 l1
        by_cases e2 : Term.compare (Term.fuel (κ X) (κ Z)) (κ X) (κ Z) = .eq
        · simp only [e2, ↓reduceIte]
          obtain ⟨Res, run, sr, er⟩ := ih2 X Y L R Rs S len' sc kc sx ks rs kl'
          have dd := drop_at (κ := κ) (P := Rs.reverse.flatten ++ Y :: X :: R ++ [S]) (L := L) (y := X)
            (z := Z) (by simp) e2
          exact ⟨Res, run, sr, er.trans (by simpa using dd)⟩
        simp only [e2, ↓reduceIte]
        by_cases l2 : Term.compare (Term.fuel (κ X) (κ Z)) (κ X) (κ Z) = .lt
        · simp only [l2, Ordering.isLT_lt, ↓reduceIte]
          have gzx := SD.gt_all sc'.2 (c_gt_of_lt l2)
          obtain ⟨Res, run, sr, er⟩ := ih2 Z Y L (X :: R) Rs S len'
            (SD_cons.2 ⟨fun w hw => by
                simp only [List.mem_cons] at hw
                rcases hw with rfl | hw
                · exact c_gt_of_lt gzy
                · exact sc'.1 w (by simpa using hw), SD_cons.2 ⟨gzx, sc'.2⟩⟩)
            (fun x hx => by
              simp only [List.mem_cons] at hx
              rcases hx with rfl | rfl | hx
              · exact kc x (by simp)
              · exact kz
              · exact kc x (by simp [hx]))
            (c_lt_trans sx l2) ks rs kl'
          have := ins_mid (κ := κ) (P := Rs.reverse.flatten) (A := [Y]) (B := X :: R ++ [S]) (L := L) (z := Z)
            (fun y hy => by
              simp only [List.cons_append, List.nil_append, List.mem_cons, List.mem_append,
                List.not_mem_nil, or_false] at hy
              rcases hy with rfl | rfl | hy | rfl
              · intro e; exact zy (c_eq_symm e)
              · rw [c_swap, gzx _ (by simp)]; simp
              · rw [c_swap, gzx y (by simp [hy])]; simp
              · rw [c_lt_trans sx l2]; simp)
          exact ⟨Res, by simpa using run, sr, er.trans (by simpa using this)⟩
        have l2' := not_islt l2
        simp only [l2', Bool.false_eq_true, ↓reduceIte]
        have rs' : RunsD (κ := κ) (KdK I κ) ((Y :: X :: R) :: Rs) := by
          intro r hr
          simp only [List.mem_cons] at hr
          rcases hr with rfl | hr
          · exact ⟨by simp, sc, kc⟩
          · exact rs r hr
        by_cases e3 : Term.compare (Term.fuel (κ S) (κ Z)) (κ S) (κ Z) = .eq
        · simp only [e3, ↓reduceIte]
          obtain ⟨Res, run, sr, er⟩ := ih2 X Y L R Rs S len' sc kc sx ks rs kl'
          have dd := drop_at (κ := κ) (P := Rs.reverse.flatten ++ Y :: X :: R ++ [S]) (L := L) (y := S)
            (z := Z) (by simp) e3
          exact ⟨Res, run, sr, er.trans (by simpa using dd)⟩
        simp only [e3, ↓reduceIte]
        by_cases l3 : Term.compare (Term.fuel (κ S) (κ Z)) (κ S) (κ Z) = .lt
        · simp only [l3, Ordering.isLT_lt, ↓reduceIte]
          obtain ⟨Res, run, sr, er⟩ := ih1 S Z L [] ((Y :: X :: R) :: Rs) len'
            (by simp [SD]; exact c_gt_of_lt l3)
            (fun x hx => by simp only [List.mem_cons, List.not_mem_nil, or_false] at hx; rcases hx with rfl | rfl; exact kz; exact ks)
            rs' kl'
          have := ins_mid (κ := κ) (P := Rs.reverse.flatten ++ Y :: X :: R) (A := []) (B := [S]) (L := L)
            (z := Z) (fun y hy => by simp only [List.nil_append, List.mem_cons, List.not_mem_nil, or_false] at hy; subst hy; exact e3)
          exact ⟨Res, by simpa using run, sr, er.trans (by simpa using this)⟩
        have l3' := not_islt l3
        simp only [l3', Bool.false_eq_true, ↓reduceIte]
        have gzs := lt_swap_of e3 l3
        obtain ⟨Res, run, sr, er⟩ := ih1 Z S L [] ((Y :: X :: R) :: Rs) len'
          (by simp [SD]; exact c_gt_of_lt gzs)
          (fun x hx => by simp only [List.mem_cons, List.not_mem_nil, or_false] at hx; rcases hx with rfl | rfl; exact ks; exact kz)
          rs' kl'
        exact ⟨Res, by simpa using run, sr, by simpa using er⟩

    end

    end Elixir.STTDescrProofsTest.USort
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.USort
    open Lynx

    section
    variable {I : Term} {κ : Term → Term}

    theorem uks2 (n : Nat) : ∀ Y L R, L.length ≤ n → SA κ (Y :: R) → R ≠ [] → (∀ x ∈ Y :: R, (KdK I κ) x) →
        (∀ x ∈ L, (KdK I κ) x) →
        ∃ Res, Erlang.lists.«ukeysplit_2/5» I Y (κ Y) (Term.list L) (Term.list R) = .ok (Term.list Res) ∧
          SA κ Res ∧ Eqv κ Res ((Y :: R) ++ L) := by
      induction n with
      | zero =>
        intro Y L R len sr _ _ _
        cases L with
        | cons => simp at len
        | nil =>
          rw [Erlang.lists.«ukeysplit_2/5».eq_def]
          exact ⟨Y :: R, by simp, sr, by simpa using Eqv.refl (Y :: R)⟩
      | succ n ih =>
      intro Y L R len sr rn kr kl
      cases L with
      | nil =>
        rw [Erlang.lists.«ukeysplit_2/5».eq_def]
        exact ⟨Y :: R, by simp, sr, by simpa using Eqv.refl (Y :: R)⟩
      | cons Z L =>
      have kz := kl Z (by simp)
      have kl' : ∀ x ∈ L, (KdK I κ) x := fun x hx => kl x (by simp [hx])
      have len' : L.length ≤ n := by simp at len; omega
      have sr' := SA_cons.1 sr
      rw [Erlang.lists.«ukeysplit_2/5».eq_def]
      simp only [kz.1, Lynx.Except.ok_bind, eq_ok, lt_ok, g_if]
      by_cases e1 : Term.compare (Term.fuel (κ Y) (κ Z)) (κ Y) (κ Z) = .eq
      · simp only [e1, ↓reduceIte]
        obtain ⟨Res, run, s, er⟩ := ih Y L R len' sr rn kr kl'
        have dd := drop_at (κ := κ) (P := Y :: R) (L := L) (y := Y) (z := Z) (by simp) e1
        exact ⟨Res, run, s, er.trans dd⟩
      simp only [e1, ↓reduceIte]
      by_cases l1 : Term.compare (Term.fuel (κ Y) (κ Z)) (κ Y) (κ Z) = .lt
      · simp only [l1, Ordering.isLT_lt, ↓reduceIte]
        have rv := rev2 R []
        simp only [List.append_nil] at rv
        simp only [rv, Lynx.Except.ok_bind]
        obtain ⟨Res, run, s, er⟩ := (uks1 (I := I) (κ := κ) L.length).1 Y Z L [] [R.reverse] (by omega)
          (by simp [SD]; exact c_gt_of_lt l1)
          (fun x hx => by
            simp only [List.mem_cons, List.not_mem_nil, or_false] at hx
            rcases hx with rfl | rfl; exact kz; exact kr _ (by simp))
          (by
            intro r hr
            simp only [List.mem_cons, List.not_mem_nil, or_false] at hr
            subst hr
            exact ⟨by simpa using rn, SD_reverse.2 sr'.2, fun x hx => kr x (by simp at hx; simp [hx])⟩)
          kl'
        refine ⟨Res, by simpa using run, s, er.trans ?_⟩
        -- rev R ++ [Z, Y] ++ L ≈ Y :: R ++ Z :: L
        have e2 := eqv_move (κ := κ) (A := R ++ [Z]) (B := L) (x := Y) (by
          intro y hy
          simp only [List.mem_append, List.mem_cons, List.not_mem_nil, or_false] at hy
          rcases hy with hy | rfl
          · rw [c_swap, sr'.1 y hy]; simp
          · intro e; exact e1 (c_eq_symm e))
        have e3 := (eqv_reverse (κ := κ) (SA.ne sr'.2)).append (Eqv.refl (Z :: Y :: L))
        simp only [List.append_assoc, List.cons_append, List.nil_append] at e2 e3 ⊢
        simpa using e3.trans e2
      have zy := lt_swap_of e1 l1
      simp only [not_islt l1, Bool.false_eq_true, ↓reduceIte]
      obtain ⟨Res, run, s, er⟩ := ih Z L (Y :: R) len' (SA_cons.2 ⟨SA.lt_all sr zy, sr⟩) (by simp)
        (fun x hx => by simp only [List.mem_cons] at hx; rcases hx with rfl | hx; exact kz; exact kr x (by simpa using hx))
        kl'
      have := eqv_move (κ := κ) (A := Y :: R) (B := L) (x := Z) (fun y hy => by
        have := SA.lt_all sr zy y hy; rw [c_swap, this]; simp)
      exact ⟨Res, by simpa using run, s, er.trans (by simpa using this.symm)⟩

    theorem uksort1 (n : Nat) : ∀ X L, L.length ≤ n → (KdK I κ) X → (∀ x ∈ L, (KdK I κ) x) →
        ∃ Res, Erlang.lists.«ukeysort_1/4» I X (κ X) (Term.list L) = .ok (Term.list Res) ∧
          SA κ Res ∧ Eqv κ Res (X :: L) := by
      induction n with
      | zero =>
        intro X L len _ _
        cases L with
        | cons => simp at len
        | nil =>
          rw [Erlang.lists.«ukeysort_1/4».eq_def]
          exact ⟨[X], by simp, by simp [SA], Eqv.refl _⟩
      | succ n ih =>
      intro X L len kx kl
      cases L with
      | nil =>
        rw [Erlang.lists.«ukeysort_1/4».eq_def]
        exact ⟨[X], by simp, by simp [SA], Eqv.refl _⟩
      | cons Z L =>
      have kz := kl Z (by simp)
      have kl' : ∀ x ∈ L, (KdK I κ) x := fun x hx => kl x (by simp [hx])
      rw [Erlang.lists.«ukeysort_1/4».eq_def]
      simp only [kz.1, Lynx.Except.ok_bind, eq_ok, lt_ok, g_if]
      by_cases e1 : Term.compare (Term.fuel (κ X) (κ Z)) (κ X) (κ Z) = .eq
      · simp only [e1, ↓reduceIte]
        obtain ⟨Res, run, s, er⟩ := ih X L (by simp at len; omega) kx kl'
        exact ⟨Res, run, s, er.trans (drop_at (P := [X]) (y := X) (by simp) e1)⟩
      simp only [e1, ↓reduceIte]
      have swap : Eqv κ ([Z, X] ++ L) (X :: Z :: L) := by
        have := eqv_move (κ := κ) (A := [X]) (B := L) (x := Z) (fun y hy => by
          simp at hy; subst hy; exact e1)
        simpa using this.symm
      by_cases l1 : Term.compare (Term.fuel (κ X) (κ Z)) (κ X) (κ Z) = .lt
      · simp only [l1, Ordering.isLT_lt, ↓reduceIte]
        obtain ⟨Res, run, s, er⟩ := (uks1 (I := I) (κ := κ) L.length).1 X Z L [] [] (by omega)
          (by simp [SD]; exact c_gt_of_lt l1)
          (fun x hx => by simp only [List.mem_cons, List.not_mem_nil, or_false] at hx; rcases hx with rfl | rfl; exact kz; exact kx)
          (by simp [RunsD]) kl'
        exact ⟨Res, by simpa using run, s, er.trans (by simpa using swap)⟩
      have zx := lt_swap_of e1 l1
      simp only [not_islt l1, Bool.false_eq_true, ↓reduceIte]
      obtain ⟨Res, run, s, er⟩ := uks2 (I := I) (κ := κ) L.length Z L [X] (by omega)
        (by simp [SA]; exact zx) (by simp)
        (fun x hx => by simp only [List.mem_cons, List.not_mem_nil, or_false] at hx; rcases hx with rfl | rfl; exact kz; exact kx)
        kl'
      exact ⟨Res, by simpa using run, s, er.trans (by simpa using swap)⟩

    end

    end Elixir.STTDescrProofsTest.USort
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.USort
    open Lynx

    section
    variable {κ : Term → Term}

    theorem eqv_perm {A B : List Term} (p : A.Perm B)
        (h : A.Pairwise fun a b => Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) ≠ .eq) : Eqv κ A B := by
      induction p with
      | nil => exact Eqv.refl _
      | cons x _ ih => exact Eqv.cons x (ih (List.pairwise_cons.1 h).2)
      | swap x y l =>
        have hyx : Term.compare (Term.fuel (κ y) (κ x)) (κ y) (κ x) ≠ .eq := (List.pairwise_cons.1 h).1 x (by simp)
        have := eqv_move (κ := κ) (A := [y]) (B := l) (x := x) (by simpa using hyx)
        simpa using this
      | trans p1 _ ih1 ih2 =>
        exact (ih1 h).trans (ih2 ((p1.pairwise_iff fun e => fun e' => e (c_eq_symm e')).1 h))

    end

    section
    variable {κ : Term → Term}

    theorem and_tt : Erlang.erlang.«and/2» (.atom "true") (.atom "true") = .ok (.atom "true") := by
      simp [Erlang.erlang.«and/2»]

    theorem small2 {a b : Term} (h : Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) = .lt) : SA κ [a, b] := by
      simp [SA, h]

    theorem small3 {a b c : Term} (h1 : Term.compare (Term.fuel (κ a) (κ b)) (κ a) (κ b) = .lt) (h2 : Term.compare (Term.fuel (κ b) (κ c)) (κ b) (κ c) = .lt) :
        SA κ [a, b, c] := by
      simp [SA, h1, h2, c_lt_trans h1 h2]

    /-- `lists:ukeysort/2` returns the strictly key-sorted list of the first element of each key. -/
    theorem ukeysort_spec (i : Int) (hi : 0 < i) (L : List Term) (kl : ∀ x ∈ L, KdK (.integer i) κ x) :
        ∃ R, Erlang.lists.«ukeysort/2» (.integer i) (Term.list L) = .ok (Term.list R) ∧ SA κ R ∧
          Eqv κ R L := by
      rw [Erlang.lists.«ukeysort/2».eq_def]
      simp only [Erlang.erlang.«>/2_integers», hi, ↓reduceIte, Lynx.Except.ok_bind, Term.true, and_tt,
        Lynx.Except.guard_ok]
      match L with
      | [] => exact ⟨[], by simp, by simp, Eqv.refl _⟩
      | [x] => exact ⟨[x], by simp, by simp [SA], Eqv.refl _⟩
      | X :: Y :: T =>
      have kx := kl X (by simp)
      have ky := kl Y (by simp)
      have kt : ∀ x ∈ T, KdK (.integer i) κ x := fun x hx => kl x (by simp [hx])
      simp only [kx.1, ky.1, Lynx.Except.ok_bind, eq_ok, lt_ok, le_ok, g_if]
      by_cases e : Term.compare (Term.fuel (κ X) (κ Y)) (κ X) (κ Y) = .eq
      · simp only [e, ↓reduceIte]
        obtain ⟨R, run, s, er⟩ := uksort1 (I := .integer i) (κ := κ) T.length X T (by omega) kx kt
        exact ⟨R, run, s, er.trans (drop_at (P := [X]) (y := X) (by simp) e)⟩
      simp only [e, ↓reduceIte]
      by_cases l : Term.compare (Term.fuel (κ X) (κ Y)) (κ X) (κ Y) = .lt
      · simp only [l, Ordering.isLT_lt, ↓reduceIte]
        match T with
        | [] => exact ⟨[X, Y], by simp, small2 l, Eqv.refl _⟩
        | [Z] =>
          have kz := (kl Z (by simp)).1
          simp only [kz, Lynx.Except.ok_bind]
          by_cases e2 : Term.compare (Term.fuel (κ Y) (κ Z)) (κ Y) (κ Z) = .eq
          · simp only [e2, ↓reduceIte]
            exact ⟨[X, Y], by simp, small2 l, drop_at (P := [X, Y]) (L := []) (y := Y) (by simp) e2⟩
          simp only [e2, ↓reduceIte]
          by_cases l2 : Term.compare (Term.fuel (κ Y) (κ Z)) (κ Y) (κ Z) = .lt
          · simp only [l2, Ordering.isLT_lt, ↓reduceIte]
            exact ⟨[X, Y, Z], by simp, small3 l l2, Eqv.refl _⟩
          simp only [not_islt l2, Bool.false_eq_true, ↓reduceIte]
          have zy := lt_swap_of e2 l2
          by_cases e3 : Term.compare (Term.fuel (κ Z) (κ X)) (κ Z) (κ X) = .eq
          · simp only [e3, ↓reduceIte]
            exact ⟨[X, Y], by simp, small2 l,
              drop_at (P := [X, Y]) (L := []) (y := X) (by simp) (c_eq_symm e3)⟩
          simp only [e3, ↓reduceIte]
          have e3' : Term.compare (Term.fuel (κ X) (κ Z)) (κ X) (κ Z) ≠ .eq := fun h => e3 (c_eq_symm h)
          by_cases l3 : (Term.compare (Term.fuel (κ X) (κ Z)) (κ X) (κ Z)).isLE = true
          · simp only [l3, ↓reduceIte]
            have xz := le_ne_lt l3 e3'
            have s := small3 xz zy
            exact ⟨[X, Z, Y], by simp, s, eqv_perm (.cons X (.swap Y Z [])) s.ne⟩
          simp only [l3, Bool.false_eq_true, ↓reduceIte]
          have s := small3 (not_le_lt l3) l
          exact ⟨[Z, X, Y], by simp, s, eqv_perm (List.perm_append_singleton Z [X, Y]).symm s.ne⟩
        | Z :: W :: T' =>
          simp only []
          obtain ⟨R, run, s, er⟩ := (uks1 (I := .integer i) (κ := κ) (T'.length + 2)).1 X Y (Z :: W :: T') []
            [] (by simp) (by simp [SD]; exact c_gt_of_lt l)
            (fun x hx => by simp only [List.mem_cons, List.not_mem_nil, or_false] at hx; rcases hx with rfl | rfl; exact ky; exact kx)
            (by simp [RunsD]) kt
          have := eqv_move (κ := κ) (A := [Y]) (B := Z :: W :: T') (x := X)
            (by simp only [List.mem_cons, List.not_mem_nil, or_false, forall_eq]; exact fun h => e (c_eq_symm h))
          exact ⟨R, by simpa using run, s, er.trans (by simpa using this)⟩
      simp only [not_islt l, Bool.false_eq_true, ↓reduceIte]
      have yx := lt_swap_of e l
      have swap : ∀ T, Eqv κ (Y :: X :: T) (X :: Y :: T) := fun T => by
        have := eqv_move (κ := κ) (A := [Y]) (B := T) (x := X)
          (by simp only [List.mem_cons, List.not_mem_nil, or_false, forall_eq]; exact fun h => e (c_eq_symm h))
        simpa using this
      match T with
      | [] => exact ⟨[Y, X], by simp, small2 yx, swap []⟩
      | [Z] =>
        have kz := (kl Z (by simp)).1
        simp only [kz, Lynx.Except.ok_bind]
        by_cases e2 : Term.compare (Term.fuel (κ X) (κ Z)) (κ X) (κ Z) = .eq
        · simp only [e2, ↓reduceIte]
          exact ⟨[Y, X], by simp, small2 yx,
            (swap []).trans (drop_at (P := [X, Y]) (L := []) (y := X) (by simp) e2)⟩
        simp only [e2, ↓reduceIte]
        by_cases l2 : Term.compare (Term.fuel (κ X) (κ Z)) (κ X) (κ Z) = .lt
        · simp only [l2, Ordering.isLT_lt, ↓reduceIte]
          exact ⟨[Y, X, Z], by simp, small3 yx l2, swap [Z]⟩
        simp only [not_islt l2, Bool.false_eq_true, ↓reduceIte]
        have zx := lt_swap_of e2 l2
        by_cases e3 : Term.compare (Term.fuel (κ Y) (κ Z)) (κ Y) (κ Z) = .eq
        · simp only [e3, ↓reduceIte]
          exact ⟨[Y, X], by simp, small2 yx,
            (swap []).trans (drop_at (P := [X, Y]) (L := []) (y := Y) (by simp) e3)⟩
        simp only [e3, ↓reduceIte]
        by_cases l3 : (Term.compare (Term.fuel (κ Y) (κ Z)) (κ Y) (κ Z)).isLE = true
        · simp only [l3, ↓reduceIte]
          have s := small3 (le_ne_lt l3 e3) zx
          exact ⟨[Y, Z, X], by simp, s, eqv_perm (List.perm_append_singleton X [Y, Z]) s.ne⟩
        simp only [l3, Bool.false_eq_true, ↓reduceIte]
        have s := small3 (not_le_lt l3) yx
        exact ⟨[Z, Y, X], by simp, s, eqv_perm (List.reverse_perm [X, Y, Z]) s.ne⟩
      | Z :: W :: T' =>
        simp only []
        obtain ⟨R, run, s, er⟩ := uks2 (I := .integer i) (κ := κ) (T'.length + 2) Y (Z :: W :: T') [X]
          (by simp) (small2 yx) (by simp)
          (fun x hx => by simp only [List.mem_cons, List.not_mem_nil, or_false] at hx; rcases hx with rfl | rfl; exact ky; exact kx)
          kt
        exact ⟨R, by simpa using run, s, er.trans (by simpa using swap (Z :: W :: T'))⟩

    end

    end Elixir.STTDescrProofsTest.USort
    """

    postlude ~LEAN"""
    namespace Elixir.STTDescrProofsTest.USort
    open Lynx

    /-- Elements of `usort/1` never equal a cons, the head sentinel of `umergel/3`. -/
    def KdU (x : Term) : Prop := ∀ a b, Term.compare (Term.fuel x (.cons a b)) x (.cons a b) ≠ .eq

    theorem um2 (n : Nat) :
        (∀ T1 T2 M H2 HdM, T1.length + T2.length + 1 ≤ n → Pre (fun x : Term => x) KdU M T1 (H2 :: T2) [] →
          HdOK (fun x : Term => x) M HdM (H2 :: T2) →
          ∃ R, Erlang.lists.«umerge2_1/5» (Term.list T1) (Term.list T2) (Term.list M) HdM H2 =
            .ok (Term.list R) ∧ Res (fun x : Term => x) M T1 (H2 :: T2) [] R) ∧
        (∀ T1 H1 T2 M, T1.length + 1 + T2.length ≤ n → Pre (fun x : Term => x) KdU M (H1 :: T1) T2 [] →
          (∀ y ∈ T2, Above (fun x : Term => x) M y) →
          ∃ R, Erlang.lists.«umerge2_2/4» (Term.list T1) (Term.list T2) (Term.list M) H1 =
            .ok (Term.list R) ∧ Res (fun x : Term => x) M (H1 :: T1) T2 [] R) := by
      induction n with
      | zero => exact ⟨fun _ _ _ _ _ h => by omega, fun _ _ _ _ h => by omega⟩
      | succ n ih =>
      constructor
      · intro T1 T2 M H2 HdM len p hd
        have u2 := up_split hd (by simp) (p.ub H2 (by simp))
        cases T1 with
        | nil =>
          rw [Erlang.lists.«umerge2_1/5».eq_def]
          simp only [eq_ok, g_if]
          by_cases c2 : Term.compare (Term.fuel H2 HdM) H2 HdM = .eq
          · obtain ⟨p', ab, tr⟩ := dropB p (u2.1 c2)
            refine ⟨_, by simp only [c2, ite_true, rev2], tr _ (res_congr (by simp) (res_fin p'.sm p'.sb ab))⟩
          · obtain ⟨p', tr⟩ := pushB p (u2.2 c2) (by simp) (by simp)
            refine ⟨_, by simpa [c2] using rev2 T2 (H2 :: M), tr _ (res_congr (by simp)
              (res_fin p'.sm p'.sb fun y hy => above_cons (u2.2 c2) ((SA_cons.1 p.sb).1 y hy)))⟩
        | cons H1 T1 =>
          rw [Erlang.lists.«umerge2_1/5».eq_def]
          simp only [le_ok, eq_ok, g_if]
          by_cases c1 : (Term.compare (Term.fuel H1 H2) H1 H2).isLE = true
          · simp only [c1, ↓reduceIte]
            obtain ⟨p', tr⟩ := pushA p (by simpa using c1) (by simp)
            obtain ⟨R, run, res⟩ := ih.1 T1 T2 (H1 :: M) H2 H1 (by simp at len; omega) p' hd_self
            exact ⟨R, by simpa using run, tr R res⟩
          · simp only [c1, Bool.false_eq_true, ↓reduceIte]
            have c1' := not_le_lt c1
            by_cases c2 : Term.compare (Term.fuel H2 HdM) H2 HdM = .eq
            · simp only [c2, ↓reduceIte]
              obtain ⟨p', ab, tr⟩ := dropB p (u2.1 c2)
              obtain ⟨R, run, res⟩ := ih.2 T1 H1 T2 M (by simp at len; omega) p' ab
              exact ⟨R, run, tr R res⟩
            · simp only [c2, ↓reduceIte]
              obtain ⟨p', tr⟩ := pushB p (u2.2 c2) (by simpa using c1') (by simp)
              obtain ⟨R, run, res⟩ := ih.2 T1 H1 T2 (H2 :: M) (by simp at len; omega) p'
                (fun y hy => above_cons (u2.2 c2) ((SA_cons.1 p.sb).1 y hy))
              exact ⟨R, by simpa using run, tr R res⟩
      · intro T1 H1 T2 M len p ab
        cases T2 with
        | nil =>
          rw [Erlang.lists.«umerge2_2/4».eq_def]
          obtain ⟨p', tr⟩ := pushA p (by simp) (by simp)
          refine ⟨_, by simpa using rev2 T1 (H1 :: M), tr _ (res_fin p'.sm p'.sa p'.ua)⟩
        | cons H2 T2 =>
          rw [Erlang.lists.«umerge2_2/4».eq_def]
          simp only [le_ok, g_if]
          by_cases c1 : (Term.compare (Term.fuel H1 H2) H1 H2).isLE = true
          · simp only [c1, ↓reduceIte]
            obtain ⟨p', tr⟩ := pushA p (by simpa using c1) (by simp)
            obtain ⟨R, run, res⟩ := ih.1 T1 T2 (H1 :: M) H2 H1 (by simp at len; omega) p' hd_self
            exact ⟨R, by simpa using run, tr R res⟩
          · simp only [c1, Bool.false_eq_true, ↓reduceIte]
            have hx := ab H2 (by simp)
            obtain ⟨p', tr⟩ := pushB p hx (by simpa using not_le_lt c1) (by simp)
            obtain ⟨R, run, res⟩ := ih.2 T1 H1 T2 (H2 :: M) (by simp at len; omega) p'
              (fun y hy => above_cons hx ((SA_cons.1 p.sb).1 y hy))
            exact ⟨R, by simpa using run, tr R res⟩

    theorem um3 (n : Nat) :
        (∀ T1 T2 T3 M H2 H3 HdM, T1.length + T2.length + T3.length + 2 ≤ n →
          (Pre (fun x : Term => x) KdU) M T1 (H2 :: T2) (H3 :: T3) → HdOK (fun x : Term => x) M HdM (H2 :: T2 ++ H3 :: T3) →
          ∃ R, Erlang.lists.«umerge3_1/7» (Term.list T1) HdM (Term.list T2) H2 (Term.list M)
            (Term.list T3) H3 = .ok (Term.list R) ∧ Res (fun x : Term => x) M T1 (H2 :: T2) (H3 :: T3) R) ∧
        (∀ H1 T1 T2 H3 T3 M HdM, T1.length + T2.length + T3.length + 2 ≤ n →
          (Pre (fun x : Term => x) KdU) M (H1 :: T1) T2 (H3 :: T3) → (∀ y ∈ T2, Above (fun x : Term => x) M y) → HdOK (fun x : Term => x) M HdM (H3 :: T3) →
          ∃ R, Erlang.lists.«umerge3_2/7» (Term.list T1) H1 (Term.list T2) HdM (Term.list M)
            (Term.list T3) H3 = .ok (Term.list R) ∧ Res (fun x : Term => x) M (H1 :: T1) T2 (H3 :: T3) R) ∧
        (∀ H1 T1 H2 T2 T3 M, T1.length + T2.length + T3.length + 2 ≤ n →
          (Pre (fun x : Term => x) KdU) M (H1 :: T1) (H2 :: T2) T3 → (∀ y ∈ H2 :: T2, Above (fun x : Term => x) M y) → (∀ y ∈ T3, Above (fun x : Term => x) M y) →
          (Term.compare (Term.fuel H1 H2) H1 H2).isLE →
          ∃ R, Erlang.lists.«umerge3_12_3/6» (Term.list T1) H1 (Term.list T2) H2
            (Term.list M) (Term.list T3) = .ok (Term.list R) ∧ Res (fun x : Term => x) M (H1 :: T1) (H2 :: T2) T3 R) ∧
        (∀ H1 T1 H2 T2 T3 M, T1.length + T2.length + T3.length + 2 ≤ n →
          (Pre (fun x : Term => x) KdU) M (H1 :: T1) (H2 :: T2) T3 → (∀ y ∈ H2 :: T2, Above (fun x : Term => x) M y) → (∀ y ∈ T3, Above (fun x : Term => x) M y) →
          Term.compare (Term.fuel H2 H1) H2 H1 = .lt →
          ∃ R, Erlang.lists.«umerge3_21_3/6» (Term.list T1) H1 (Term.list T2) H2
            (Term.list M) (Term.list T3) = .ok (Term.list R) ∧ Res (fun x : Term => x) M (H1 :: T1) (H2 :: T2) T3 R) := by
      induction n with
      | zero => refine ⟨?_, ?_, ?_, ?_⟩ <;> intros <;> omega
      | succ n ih =>
      obtain ⟨ih1, ih2, ih12, ih21⟩ := ih
      have m2 := um2 n
      refine ⟨?_, ?_, ?_, ?_⟩
      · -- ukeymerge3_1
        intro T1 T2 T3 M H2 H3 HdM len p hd
        have u2 := up_split hd (by simp) (p.ub H2 (by simp))
        have u3 := up_split hd (by simp) (p.uc H3 (by simp))
        rw [Erlang.lists.«umerge3_1/7».eq_def]
        cases T1 with
        | nil =>
          simp only [le_ok, eq_ok, g_if]
          by_cases c2 : Term.compare (Term.fuel H2 HdM) H2 HdM = .eq
          · simp only [c2, ↓reduceIte]
            obtain ⟨p', ab, tr⟩ := dropB p (u2.1 c2)
            obtain ⟨R, run, res⟩ := m2.1 T2 T3 M H3 HdM (by simp at len; omega) (pre_BC p' ab)
              (hd_sub hd fun a ha => List.mem_append_right _ ha)
            exact ⟨R, run, tr R (res_congr (by simp) res)⟩
          simp only [c2, ↓reduceIte]
          have a2 := u2.2 c2
          by_cases c23 : (Term.compare (Term.fuel H2 H3) H2 H3).isLE = true
