          have a3 := ac H3 (by simp)
          obtain ⟨p', tr⟩ := pushC p a3 (by simpa using c_lt_trans c32 c21) (by simpa using c32)
          obtain ⟨R, run, res⟩ := ih21 H1 T1 H2 T2 T3 (H3 :: M) (by simp at len; omega) p'
