      have hm : (Nest.level node d).K + 23 ≤ δ + 100 := by rw [Nest.level_K]; omega
      rw [Lynx.apply_eq, «subtype_transitive:ensures/5», Nest.gd_sub ga gb la ua lb ub hm, Nest.gd_sub gb gc lb ub lc uc hm,
