          (Nest.mfused_de (Nest.mleaf_field (Or.inl rfl) (Nest.fieldsV_req hterm) key)) (m := δ + 100) (by omega)
        rw [Nest.bp_false.mpr fun h => by
          have := h _ ((Nest.denD_mpt w₀).mpr hw₀)
          rw [Nest.denD_mpt, Nest.mt_open_at hterm a k] at this
